# go_version_needed reads the go directive out of the go.mod that is baked
# into the function above, so there is one statement of the minimum and the
# build cannot disagree with the module. The old script kept its own
# GO_MIN_MINOR=19 beside a module that said 1.24, accepted a toolchain four
# years too old, and then died inside go build with a message about toolchain
# downloads that named none of that.
#
# declare -f prints a function's heredocs verbatim, so the whole embedded
# tree is readable without touching the disk. It is fed to awk with a here
# string rather than a pipe on purpose: awk exits at the first match, and a
# printf pouring a hundred kilobytes into a pipe that just closed takes
# SIGPIPE and reports 141 under pipefail.
go_version_needed() {
    local body v=
    body=$(declare -f write_core_sources 2>/dev/null) || body=
    if [ -n "$body" ]; then
        v=$(awk '/^go [0-9]/ { print $2; exit }' <<<"$body")
    fi
    # If bash ever stops reproducing heredocs, fall back to reading the file
    # this writes. Slower, and correct for the same reason.
    if [ -z "$v" ]; then
        local tmp
        tmp=$(mktemp -d) || return 1
        write_core_sources "$tmp" >/dev/null 2>&1 &&
            v=$(awk '/^go [0-9]/ { print $2; exit }' "$tmp/go.mod")
        rm -rf "$tmp"
    fi
    [ -n "$v" ] || return 1
    printf '%s' "$v"
}

# ver_ge compares two dotted versions, missing parts counting as zero, so
# 1.24 and 1.24.0 are the same version. String comparison gets 1.9 and 1.24
# the wrong way round, which is exactly the pair that matters here.
ver_ge() {
    local i av bv
    local -a A B
    IFS=. read -r -a A <<<"$1"
    IFS=. read -r -a B <<<"$2"
    for i in 0 1 2; do
        av=${A[i]:-0}
        bv=${B[i]:-0}
        case $av in '' | *[!0-9]*) av=0 ;; esac
        case $bv in '' | *[!0-9]*) bv=0 ;; esac
        [ "$av" -gt "$bv" ] && return 0
        [ "$av" -lt "$bv" ] && return 1
    done
    return 0
}

# --------------------------------------------------------------------------
# a compiler
# --------------------------------------------------------------------------

# ensure_go finds a Go new enough for the module or offers to fetch one, and
# sets GO_BIN. It never installs anything without being asked.
ensure_go() {
    local want cand out v found= arch tar_ver url tmp pid rc

    if ! want=$(go_version_needed); then
        bad "the embedded go.mod could not be read, so I cannot tell what Go this needs"
        fix "rebuild the script from the repository:  ./build.sh"
        return 1
    fi

    # /usr/local/go before PATH: if an earlier run put one there it is the one
    # known to be new enough, and a distro package earlier on PATH usually is
    # not. command -v may print nothing; the quotes keep that an empty word
    # rather than dropping the loop item.
    for cand in /usr/local/go/bin/go "$(command -v go 2>/dev/null)"; do
        [ -x "$cand" ] || continue
        out=$("$cand" version 2>/dev/null) || continue
        v=${out#go version go}
        v=${v%% *}
        case $v in '' | *[!0-9.]*) continue ;; esac
        if ver_ge "$v" "$want"; then
            GO_BIN=$cand
            return 0
        fi
        found=$v
    done

    arch=$(arch_go)
    if [ -z "$arch" ]; then
        bad "$(uname -m) is not a machine this can build for"
        fix "amd64 and arm64 are what the core is built and tested on"
        return 1
    fi

    # A released minor always has a .0, so deriving the tarball from the go
    # directive keeps this from drifting the way a hardcoded GO_FALLBACK did.
    tar_ver=$want
    case $want in *.*.*) ;; *) tar_ver=$want.0 ;; esac
    url=$GO_DL_BASE/go$tar_ver.linux-$arch.tar.gz

    blank
    if [ -n "$found" ]; then
        warn "the Go here is $found and the core needs $want or newer"
    else
        warn "there is no Go on this machine, and the core is built here"
    fi
    blank
    dim "This is the one step that wants the network. It would fetch:"
    dim "  $url"
    field "size" "about 80 MB, roughly 250 MB unpacked"
    field "into" "/usr/local/go, deleting whatever is there now"
    blank
    dim "Nothing verifies it beyond TLS to go.dev: this script carries no"
    dim "checksum, and one fetched from the same place as the tarball would"
    dim "prove nothing. If that is not good enough, install Go by hand and run"
    dim "this again - it wants a compiler, not that compiler."
    blank

    if ! confirm "fetch it?" y; then
        bad "no compiler, so no core"
        fix "install Go $want or newer, then run this again"
        return 1
    fi

    tmp=$(mktemp) || return 1
    if have curl; then
        curl -fSL --retry 2 --connect-timeout 20 -o "$tmp" "$url"             >"$STATE_DIR/fetch.log" 2>&1 &
        pid=$!
    elif have wget; then
        wget -O "$tmp" "$url" >"$STATE_DIR/fetch.log" 2>&1 &
        pid=$!
    else
        rm -f "$tmp"
        bad "neither curl nor wget is installed, so nothing here can fetch it"
        fix "apt install curl   (or install Go yourself from $url)"
        return 1
    fi
    spin "fetching go$tar_ver for $arch" "$pid"
    rc=$?

    if [ "$rc" != 0 ]; then
        rm -f "$tmp"
        bad "the download failed, exit $rc"
        [ -s "$STATE_DIR/fetch.log" ] &&
            tail -n 3 "$STATE_DIR/fetch.log" | sed 's/^/       /'
        fix "from a machine that can reach it:  curl -fLO $url"
        fix "copy it here, then:  tar -C /usr/local -xzf go$tar_ver.linux-$arch.tar.gz"
        return 1
    fi

    # Unpack beside whatever is there and swap only when it worked. Deleting
    # first is how a truncated download leaves a server with no compiler at
    # all - including the too-old one it had a minute ago - and the advice
    # printed after that failure needs the network that just failed.
    rm -rf /usr/local/go.new
    if ! tar -C /usr/local --one-top-level=go.new --strip-components=1 -xzf "$tmp"; then
        rm -rf /usr/local/go.new
        rm -f "$tmp"
        bad "the tarball would not unpack - it is probably a truncated download"
        fix "run this again, or unpack it by hand into /usr/local"
        return 1
    fi
    rm -f "$tmp"
    if [ ! -x /usr/local/go.new/bin/go ]; then
        rm -rf /usr/local/go.new
        bad "the tarball unpacked but there is no bin/go in it"
        return 1
    fi
    rm -rf /usr/local/go.old
    [ -d /usr/local/go ] && mv /usr/local/go /usr/local/go.old
    mv /usr/local/go.new /usr/local/go
    rm -rf /usr/local/go.old

    if [ ! -x /usr/local/go/bin/go ]; then
        bad "the tarball unpacked but there is no /usr/local/go/bin/go in it"
        return 1
    fi
    GO_BIN=/usr/local/go/bin/go
    ok "go $tar_ver is installed in /usr/local/go"
    return 0
}

# --------------------------------------------------------------------------
# building
# --------------------------------------------------------------------------

build_core() {
    require_root
    ensure_dirs
    ensure_go || return 1

    local log out rc
    log=$STATE_DIR/build.log
    out=$SRC_DIR/pingify-core

    # Clear the tree first. A file dropped between versions would otherwise
    # sit there and be compiled alongside the new ones, and a stale
    # internal/carrier/*.go is a build error nobody can explain by reading
    # this script. The build cache under gocache/ is kept, so an unchanged
    # rebuild is a couple of seconds rather than forty.
    rm -rf "$SRC_DIR/cmd" "$SRC_DIR/internal" "$SRC_DIR/go.mod"
    if ! write_core_sources "$SRC_DIR"; then
        bad "the core sources could not be written into $SRC_DIR"
        fix "check there is space and that $SRC_DIR is writable:  df -h $SRC_DIR"
        return 1
    fi

    # GOPROXY=off and GOFLAGS=-mod=mod because there is nothing to fetch:
    # saying so turns a confusing "cannot reach proxy.golang.org" into a build
    # that simply works. GOTOOLCHAIN=local because from 1.21 go will otherwise
    # try to download the toolchain the go directive names, over the network
    # this machine may not have - ensure_go has already checked the local one
    # is new enough, so there is nothing to gain and a hang to lose.
    (
        cd "$SRC_DIR" &&
            GOTOOLCHAIN=local GO111MODULE=on GOPROXY=off GOSUMDB=off \
                GOFLAGS=-mod=mod GOPATH="$SRC_DIR/gopath" \
                GOCACHE="$SRC_DIR/gocache" CGO_ENABLED=0 \
                "$GO_BIN" build -trimpath -ldflags "-s -w" -o "$out" ./cmd/pingify
    ) >"$log" 2>&1 &
    spin "building the core - up to a minute on a small server" $!
    rc=$?

    if [ "$rc" != 0 ]; then
        bad "the core did not build, go exited $rc"
        tail -n 20 "$log" | sed 's/^/       /'
        fix "the whole log is in $log"
        return 1
    fi

    # Only now. An install that overwrites the binary before the build is
    # known to have worked leaves a machine with no core and a running tunnel
    # that cannot be restarted.
    if ! install -m 0755 "$out" "$CORE_BIN"; then
        bad "the core built but would not install to $CORE_BIN"
        return 1
    fi
    # Ask the binary that just landed. `ok "core $(core_version) ..."` reads as
    # a check and is not one: the substitution runs inside an argument, so a
    # core that will not exec - wrong architecture, most likely - prints
    # "core  is installed" in green and returns success, and every later run
    # rebuilds it from scratch and says the same thing again.
    local here
    here=$(core_version)
    if [ -z "$here" ]; then
        bad "the core installed but will not run - is $(arch_go) really this machine?"
        return 1
    fi
    if [ "$here" != "$PINGIFY_VERSION" ]; then
        bad "the core says it is $here and this script is $PINGIFY_VERSION"
        fix "they are built from the same file, so this means a stale copy somewhere"
        return 1
    fi
    ok "core $here is installed at $CORE_BIN"
    return 0
}

# core_version prints what is installed, and nothing at all when there is no
# core to ask. The binary answers "pingify-core 2.0.0"; only the number is of
# use to a caller comparing it with this script's own.
core_version() {
    local out
    [ -x "$CORE_BIN" ] || return 1
    out=$("$CORE_BIN" -version 2>/dev/null) || return 1
    printf '%s' "${out#pingify-core }"
}

# ensure_core is what every path that needs a working core calls first.
#
# The version has to match this script exactly, not merely be present. The two
# halves ship together and a config key the manager writes may be one the
# older core refuses, which surfaces as the core rejecting a file the manager
# just built - a confusing failure a long way from its cause.
#
# Replacing the binary does not disturb a running tunnel: systemd keeps the
# old inode open until the unit is restarted, so nothing is felt until the
# caller restarts it, which is the caller's decision to make and to announce.
ensure_core() {
    local here
    here=$(core_version) || here=

    [ "$here" = "$PINGIFY_VERSION" ] && return 0

    if [ -n "$here" ]; then
        blank
        dim "the core here is $here and this manager is $PINGIFY_VERSION - rebuilding"
    fi
    build_core
}
#!/usr/bin/env bash
#
# AmneziaWG: obfuscated WireGuard, from their packages rather than ours.
#
# This is the one transport Pingify does not implement. It is somebody else's
# careful cryptography with a deliberate junk-and-header layer on top of it,
# and the right thing to do with that is install it from the repository the
# people who wrote it publish - ppa:amnezia/ppa, the same one their own
# clients use - and drive it.
#
# What the tunnel does on top is unchanged. awg-quick brings up a private link
# between the two servers; the core then runs its ordinary UDP carrier inside
# that link, so the profile's queue depth, the socket buffers, the counters
# every screen reads, the status endpoint and the health port all work exactly
# as they do on every other transport. The obfuscation is theirs, the tuning
# is ours, and neither has to know about the other.
#
# The keys are the one thing that does not fit the shared-file design without
# help: WireGuard needs a private key on each side and the far side's public
# key, which is four values rather than one shared secret. Both keypairs are
# generated once, on the first server, and all four values travel in the file
# - so the second server still needs nothing but the paste, and each side
# picks out the half that is its own.

AWG_DIR=${PINGIFY_AWG_DIR:-/etc/amnezia/amneziawg}
AWG_PPA=${PINGIFY_AWG_PPA:-ppa:amnezia/ppa}

awg_ready() { have awg && have awg-quick; }

# awg_install adds their repository and installs from it.
#
# It is a network operation on a server that may not be able to reach a
# launchpad mirror, so the failure is reported as what it is rather than as a
# broken tunnel: the packages are missing, here is the command, and every
# other transport still works.
awg_install() {
    awg_ready && return 0
    blank
    dim "installing AmneziaWG from $AWG_PPA"
    if have add-apt-repository; then
        add-apt-repository -y "$AWG_PPA" >/dev/null 2>&1
    fi
    if have apt-get; then
        apt-get update >/dev/null 2>&1
        DEBIAN_FRONTEND=noninteractive apt-get install -y \
            amneziawg amneziawg-tools >/dev/null 2>&1
    fi
    if awg_ready; then
        ok "AmneziaWG installed - $(awg --version 2>/dev/null | head -1)"
        return 0
    fi
    bad "AmneziaWG could not be installed on this server"
    fix "it needs $AWG_PPA, which a server in Iran often cannot reach"
    fix "install it from a server that can, or pick another transport"
    return 1
}

# --------------------------------------------------------------------------
# what the wizard generates
# --------------------------------------------------------------------------

# awg_rand is a number in a range, from the kernel's own random device.
awg_rand() {
    local lo=$1 hi=$2 n
    n=$(od -An -N4 -tu4 /dev/urandom 2>/dev/null | tr -d ' \n')
    case $n in '' | *[!0-9]*) n=$((RANDOM * 32768 + RANDOM)) ;; esac
    printf '%s' $((lo + n % (hi - lo + 1)))
}

# awg_generate fills in the keys and the obfuscation for a new tunnel.
#
# The obfuscation numbers are what make an AmneziaWG packet not look like a
# WireGuard one: Jc junk packets of Jmin to Jmax bytes before the handshake,
# S1 and S2 bytes of junk inside the first two handshake packets, and H1 to H4
# in place of WireGuard's four fixed message types. They have to match on both
# servers, which they do, because they are generated once and travel in the
# file. The ranges are the ones Amnezia's own documentation gives.
awg_generate() {
    awg_ready || return 1
    T_AWG_IKEY=$(awg genkey)
    T_AWG_IPUB=$(printf '%s' "$T_AWG_IKEY" | awg pubkey)
    T_AWG_KKEY=$(awg genkey)
    T_AWG_KPUB=$(printf '%s' "$T_AWG_KKEY" | awg pubkey)
    [ -n "$T_AWG_IPUB" ] && [ -n "$T_AWG_KPUB" ] || return 1

    # Not generated. These five are the set that has been run on this path and
    # found stable - no periodic drops - and randomising them was how this
    # transport came to hand shake and then carry nothing. The documentation
    # gives ranges; the ranges contain combinations that do not work, and
    # finding out which is not something to do on somebody's live tunnel.
    #
    # S1 + 56 must not equal S2, and 68 and 91 do not.
    T_AWG_JC=5
    T_AWG_JMIN=50
    T_AWG_JMAX=1000
    T_AWG_S1=68
    T_AWG_S2=91

    # Four distinct header types, none of them the four WireGuard uses.
    local i h
    T_AWG_H1= T_AWG_H2= T_AWG_H3= T_AWG_H4=
    for i in 1 2 3 4; do
        while :; do
            h=$(awg_rand 5 2147483000)
            list_has "$h" "$T_AWG_H1" "$T_AWG_H2" "$T_AWG_H3" "$T_AWG_H4" || break
        done
        eval "T_AWG_H$i=\$h"
    done
    return 0
}

# --------------------------------------------------------------------------
# the link itself
# --------------------------------------------------------------------------

awg_iface() { toml_get "$(cfg_file "$1")" awg name; }

# awg_conf writes this server's half of the link.
#
# The file is built from the shared config every time rather than kept, so a
# change to the tunnel is a change to the interface without anybody having to
# remember there are two of them. 0600, because the private key is in it.
awg_conf() {
    local name=$1 f side iface mine peer_pub my_key peer_addr port endpoint
    f=$(cfg_file "$name")
    side=$(toml_get "$f" tunnel side)
    iface=$(toml_get "$f" awg name)
    [ -n "$iface" ] || return 1

    if [ "$side" = iran ]; then
        mine=$(toml_get "$f" awg iran)
        my_key=$(toml_get "$f" awg iran_key)
        peer_pub=$(toml_get "$f" awg kharej_pub)
        peer_addr=$(toml_get "$f" awg kharej)
    else
        mine=$(toml_get "$f" awg kharej)
        my_key=$(toml_get "$f" awg kharej_key)
        peer_pub=$(toml_get "$f" awg iran_pub)
        peer_addr=$(toml_get "$f" awg iran)
    fi
    port=$(toml_get "$f" awg port)

    # Both ends get an Endpoint and both get a ListenPort.
    #
    # WireGuard only needs one of them to know where the other is - the far
    # end learns the address from the first handshake that arrives. Setting
    # both anyway is what a working AmneziaWG deployment on this path does,
    # and the reason is the path: a side that has to learn the address has
    # nothing to send to until something arrives, and on a link where the
    # first packets are the ones most likely to be dropped that is a tunnel
    # that comes up only sometimes.
    if [ "$side" = iran ]; then
        endpoint="Endpoint = $(toml_get "$f" transport kharej):$port"
    else
        endpoint="Endpoint = $(toml_get "$f" transport iran):$port"
    fi

    mkdir -p "$AWG_DIR"
    umask 077
    cat >"$AWG_DIR/$iface.conf" <<CONF
# Written by Pingify for the tunnel $name. Edited here, it is overwritten on
# the next change: the tunnel's own file in $CFG_DIR is where it comes from.
[Interface]
PrivateKey = $my_key
Address = $mine
MTU = $(toml_get "$f" awg mtu)
ListenPort = $port
Jc = $(toml_get "$f" awg jc)
Jmin = $(toml_get "$f" awg jmin)
Jmax = $(toml_get "$f" awg jmax)
S1 = $(toml_get "$f" awg s1)
S2 = $(toml_get "$f" awg s2)
H1 = $(toml_get "$f" awg h1)
H2 = $(toml_get "$f" awg h2)
H3 = $(toml_get "$f" awg h3)
H4 = $(toml_get "$f" awg h4)

[Peer]
PublicKey = $peer_pub
AllowedIPs = ${peer_addr%.*}.0/24
$endpoint
PersistentKeepalive = 25
CONF
    chmod 0600 "$AWG_DIR/$iface.conf"
}

# awg_up writes the interface's config and starts it, and is safe to call
# again: awg-quick refuses a device that already exists, so the old one goes
# first. That is also what makes a settings change take effect.
awg_up() {
    local name=$1 iface
    iface=$(awg_iface "$name")
    [ -n "$iface" ] || return 0
    awg_conf "$name" || return 1
    systemctl disable --now "awg-quick@$iface" >/dev/null 2>&1
    ip link del "$iface" >/dev/null 2>&1
    if ! systemctl enable --now "awg-quick@$iface" >/dev/null 2>&1; then
        bad "the AmneziaWG link $iface would not come up"
        fix "journalctl -u awg-quick@$iface -n 20"
        return 1
    fi
    return 0
}

awg_down() {
    local name=$1 iface
    iface=$(awg_iface "$name")
    [ -n "$iface" ] || return 0
    systemctl disable --now "awg-quick@$iface" >/dev/null 2>&1
    ip link del "$iface" >/dev/null 2>&1
    rm -f "$AWG_DIR/$iface.conf"
    return 0
}

# awg_free_iface is the first awgN nothing on this host is using. The tunnel's
# own device is pfyN and this one is beside it, so a server with three tunnels
# has three of each and no two of them meet.
awg_free_iface() {
    local i=0
    while [ "$i" -lt 64 ]; do
        if ! ip link show "awg$i" >/dev/null 2>&1 &&
            [ ! -e "$AWG_DIR/awg$i.conf" ]; then
            printf 'awg%s' "$i"
            return 0
        fi
        i=$((i + 1))
    done
    return 1
}

# awg_handshake is how long ago the far end was last heard from, in seconds,
# or nothing when there has been no handshake at all. It is the one number
# that says whether the link underneath a tunnel is alive.
awg_handshake() {
    local iface=$1 t now
    have awg || return 1
    t=$(awg show "$iface" latest-handshakes 2>/dev/null | awk 'NR == 1 { print $2 }')
    case $t in '' | 0 | *[!0-9]*) return 1 ;; esac
    now=$(date +%s)
    printf '%s' $((now - t))
}
#!/usr/bin/env bash
#
# The wizard: six questions on the first server, one paste on the second.
#
# That asymmetry is the whole design, and it falls out of one fact about the
# core - the config file is byte-identical on both servers except the line
# side = "iran" / side = "kharej". So the second server does not answer
# questions at all. It takes the first server's file, flips one line, and
# writes it. A setting added to the core needs no change here, and the two ends
# cannot drift apart, which was the most common way a tunnel came up carrying
# nothing.
#
# The old setup token was 31 pipe-separated fields. Both the encoder and the
# decoder had to agree on the order, a new core setting meant editing both, and
# a truncated paste was diagnosed by counting fields. Here the token *is* the
# config file, and one hash catches every kind of damage.
#
# Every question is its own function reading into a T_* variable. That is so a
# test can drive the real wizard through its stdin instead of grepping this
# file for the strings it hopes are in it: the old suite had 130 assertions
# that were greps over the script's own source, and they pinned wording, broke
# on renames, and passed happily on dead code.

# The tunnel being edited may keep its own values - a screen that re-asks for a
# port must not report the tunnel's own port as taken. The wizard creates, so
# this stays empty here; every owner lookup below also takes the name as an
# optional last argument, so a caller that has one need not set a global and
# remember to put it back.
WIZ_KEEP=

# --------------------------------------------------------------------------
# addresses, and who already has them
# --------------------------------------------------------------------------

# wiz_ip4_int turns a dotted quad into a number so two of them can be compared.
# The 10# prefixes are not decoration: bash reads a leading zero as octal, so
# without them 10.010.0.1 compares as 10.8.0.1 and the answer is quietly wrong.
wiz_ip4_int() {
    local a b c d rest x
    IFS=. read -r a b c d rest <<<"$1"
    [ -z "$rest" ] || return 1
    for x in "$a" "$b" "$c" "$d"; do
        case $x in '' | *[!0-9]*) return 1 ;; esac
        [ "$((10#$x))" -le 255 ] || return 1
    done
    printf '%s' $(((10#$a << 24) + (10#$b << 16) + (10#$c << 8) + 10#$d))
}

# wiz_net_overlap answers whether 10.<octet>.10.0/24 lands inside an address
# already on this host. Comparing the top min(24, prefix) bits is what makes a
# docker bridge on 10.42.0.0/16 count as owning 10.42.10.0/24 - a plain string
# match on the second octet would miss it, and the tunnel would come up on a
# range the kernel already routes somewhere else.
wiz_net_overlap() {
    local addr=$1 plen=$2 oct=$3 a b m
    a=$(wiz_ip4_int "$addr") || return 1
    case $plen in '' | *[!0-9]*) return 1 ;; esac
    # An octet that is not a number would become an arithmetic syntax error
    # below, and inside a validator that error is what the user gets told.
    case $oct in '' | *[!0-9]*) return 1 ;; esac
    b=$(((10 << 24) + ((10#$oct) << 16) + (10 << 8)))
    m=$plen
    [ "$m" -gt 24 ] && m=24
    # A /0 on an interface is not a claim on anything; treating it as one would
    # make every octet look taken.
    [ "$m" -ge 1 ] || return 1
    [ "$((a >> (32 - m)))" -eq "$((b >> (32 - m)))" ]
}

# wiz_link_owner prints what owns 10.<octet>.10.0/24 here, or returns 1.
wiz_link_owner() {
    local oct=$1 keep=${2:-$WIZ_KEEP} n a dev addr plen
    while IFS= read -r n; do
        [ "$n" = "$keep" ] && continue
        a=$(toml_get "$(cfg_file "$n")" tun iran)
        case ${a%%/*} in
        10."$oct".*) printf 'the tunnel %s' "$n"; return 0 ;;
        esac
    done < <(cfg_list)
    # Process substitution, not a pipe: a pipe puts the loop in a subshell and
    # the return below would leave only the subshell, so a clash on the host
    # would be found and then thrown away.
    while read -r dev addr; do
        [ -n "$addr" ] || continue
        plen=${addr#*/}
        [ "$plen" = "$addr" ] && plen=32
        if wiz_net_overlap "${addr%%/*}" "$plen" "$oct"; then
            printf '%s on %s' "$addr" "$dev"
            return 0
        fi
    done < <(ip -4 -o addr 2>/dev/null | awk '$3 == "inet" { print $2, $4 }')
    return 1
}

# wiz_device_owner prints what owns a tun device name here, or returns 1.
wiz_device_owner() {
    local dev=$1 n keep=${2:-$WIZ_KEEP}
    while IFS= read -r n; do
        [ "$n" = "$keep" ] && continue
        [ "$(toml_get "$(cfg_file "$n")" tun name)" = "$dev" ] &&
            { printf 'the tunnel %s' "$n"; return 0; }
    done < <(cfg_list)
    # An interface with no config behind it is another tool's, or one of ours
    # left over from a crash. Either way the core cannot create it again.
    [ -e "/sys/class/net/$dev" ] && { printf 'an interface already on this host'; return 0; }
    return 1
}

# Who holds a port number, on the protocol that matters.
#
# 8443/udp and 8443/tcp are two different ports and always have been, so a UDP
# tunnel on 8443 is not in the way of a TCP one, and refusing it would be a
# refusal with nothing behind it. ICMP has no ports at all, so an icmp tunnel
# matches no protocol and owns no number.
wiz_port_owner() {
    local p=$1 keep=${2:-$WIZ_KEEP} proto=${3:-${T_TRANSPORT:-udp}} n f
    while IFS= read -r n; do
        [ "$n" = "$keep" ] && continue
        f=$(cfg_file "$n")
        [ "$(toml_get "$f" transport type)" = "$proto" ] || continue
        [ "$(toml_get "$f" transport port)" = "$p" ] &&
            { printf 'the tunnel %s' "$n"; return 0; }
    done < <(cfg_list)
    return 1
}

# wiz_port_bound asks whether anything on this host already listens on a udp
# port. When ss is missing the answer is "no": refusing to go on because a
# check could not run is a wall the user cannot climb, and the core will say so
# plainly at start-up if the bind really fails.
# And what the kernel says is listening, on that same protocol.
wiz_port_bound() {
    local p=$1 proto=${2:-${T_TRANSPORT:-udp}} flag=-lnu
    have ss || return 1
    [ "$proto" = tcp ] && flag=-lnt
    ss "$flag" 2>/dev/null |
        awk -v want=":$p\$" 'NR > 1 && $4 ~ want { hit = 1 } END { exit !hit }'
}

# wiz_public_ip is a default for the KHAREJ side, read from the interfaces
# rather than from a lookup service. The first server is in Iran on a path that
# blocks half the internet, so a wizard that pauses to curl an address service
# is a wizard that hangs where it is hardest to debug.
# Every address of this server the outside world could reach, one to a line.
#
# The private ranges are struck out, carrier grade NAT included: an address in
# 100.64/10 is one the machine's provider handed it behind a shared public one,
# and a config naming it is a config nothing outside that provider can dial.
wiz_public_ips() {
    local a found=1
    for a in $(ip -4 -o addr show scope global 2>/dev/null |
        awk '$3 == "inet" { sub("/.*", "", $4); print $4 }'); do
        case $a in
        10.* | 127.* | 192.168.* | 169.254.* | \
            172.1[6-9].* | 172.2[0-9].* | 172.3[01].* | \
            100.6[4-9].* | 100.[7-9][0-9].* | 100.1[01][0-9].* | 100.12[0-7].*) continue ;;
        esac
        printf '%s\n' "$a"
        found=0
    done
    return "$found"
}

wiz_public_ip() {
    local a
    a=$(wiz_public_ips | head -1)
    [ -n "$a" ] || return 1
    printf '%s' "$a"
}

# --------------------------------------------------------------------------
# choosing what is free
# --------------------------------------------------------------------------

# free_octet is the lowest 1-254 that no tunnel here owns and that is not
# inside any address on this host. It prints nothing when there is none, and
# the caller says so rather than offering a default that will be refused.
free_octet() {
    local i=1
    while [ "$i" -le 254 ]; do
        wiz_link_owner "$i" >/dev/null || { printf '%s' "$i"; return 0; }
        i=$((i + 1))
    done
    return 1
}

free_device() {
    local i=0 dev
    while [ "$i" -lt 64 ]; do
        dev="pfy$i"
        wiz_device_owner "$dev" >/dev/null || { printf '%s' "$dev"; return 0; }
        i=$((i + 1))
    done
    return 1
}

# The name a tunnel is given, which is also the name of its file.
#
# It starts with the side, and that is the whole point of it: on a server with
# three tunnels, the first thing anybody needs to know about each one is which
# end of the border they are looking at - and `ls /root/pingify` should say so
# without opening anything.
#
# Then the transport, then the one number that tells two tunnels apart: the
# port for a tunnel that has one, and the private link's octet for ICMP, which
# has no port at all.
#
#   iran-udp-8443     kharej-udp-8443
#   iran-icmp-99      kharej-icmp-99
#
# It is built from those two because neither can name a side. The name lives in
# the shared file, so a name like iran-9443 - which is what the old scheme
# produced - is a lie on one of the two servers from the moment it is written.
default_name() {
    local side=${1:-$T_SIDE} trans=${2:-$T_TRANSPORT} port=${3:-$T_PORT} oct=${4:-$T_OCTET}
    local base n i
    # For AmneziaWG the number worth having in the name is the port somebody
    # opened, not the one the carrier uses inside the link.
    [ "$trans" = awg ] && port=${T_AWG_PORT:-$port}
    base="$side-$trans-${port:-$oct}"
    n=$base
    i=2
    while [ -e "$(cfg_file "$n")" ]; do
        n="$base-$i"
        i=$((i + 1))
        [ "$i" -gt 20 ] && break
    done
    printf '%s' "$n"
}

# The same tunnel's name on the other server.
#
# The side is the first word of the name, so this replaces the first word. It
# is why the two files differ in two lines now rather than one: the side, and
# the name that carries it. A name that does not begin with a side is left
# alone - somebody chose it by hand and it is not this function's to rewrite.
name_for_side() {
    local name=$1 side=$2
    case $name in
    iran-* | kharej-*) printf '%s-%s' "$side" "${name#*-}" ;;
    *) printf '%s' "$name" ;;
    esac
}

# The status endpoint is one loopback port per tunnel. It is written into the
# shared file, so the second server inherits the number; wizard_paste checks it
# again there because the two servers do not have the same tunnels on them.
#
# Nothing free means nothing free. This used to fall out of the loop printing
# $STATUS_BASE with status 0 - the one port it had just proved was taken - and
# both callers wrote that number into the config without a word, so the new
# core lost the race for the loopback port and the tunnel never came up.
# Whether something on this machine already holds a port on every address.
#
# A listener on one address is not in the way: the health port is bound to the
# tunnel's own tun address, and no two tunnels have the same one. A listener
# on the wildcard *is* in the way - and on Linux an IPv6 wildcard holds the
# IPv4 one along with it, so [::]:19999 blocks 10.99.10.1:19999 too.
#
# This is why the health port is not a question. There is nothing for a person
# to know here that the machine does not already know.
wiz_health_bound() {
    local p=$1 a
    have ss || return 1
    while read -r a; do
        case $a in
        "0.0.0.0:$p" | "*:$p" | "[::]:$p" | ":::$p") return 0 ;;
        esac
    done < <(ss -ltnH 2>/dev/null | awk '{ print $4 }')
    return 1
}

wiz_free_health() {
    local p=$HEALTH_PORT n=0
    while wiz_health_bound "$p"; do
        p=$((p + 1))
        n=$((n + 1))
        [ "$n" -gt 20 ] && return 1
    done
    printf '%s' "$p"
}

wiz_free_status_port() {
    local keep=${1:-$WIZ_KEEP} i=0 p n taken
    while [ "$i" -lt 100 ]; do
        p=$((STATUS_BASE + i))
        taken=
        while IFS= read -r n; do
            [ "$n" = "$keep" ] && continue
            [ "$(toml_get "$(cfg_file "$n")" status port)" = "$p" ] && { taken=1; break; }
        done < <(cfg_list)
        [ -z "$taken" ] && { printf '%s' "$p"; return 0; }
        i=$((i + 1))
    done
    return 1
}

# --------------------------------------------------------------------------
# validators the wizard adds to the ones in the UI
# --------------------------------------------------------------------------

v_wiz_octet() {
    local who
    v_octet "$1" || return 1
    if who=$(wiz_link_owner "$1"); then
        echo "10.$1.10.0/24 is in use here by $who"
        return 1
    fi
    return 0
}

v_wiz_port() {
    local who
    v_port "$1" || return 1
    if who=$(wiz_port_owner "$1"); then
        echo "port $1 already belongs to $who"
        return 1
    fi
    # A bound port only matters on the side that waits. IRAN dials out, so a
    # local listener on the same number there is not a conflict, and refusing
    # it would be a refusal with no action behind it.
    if [ "$T_SIDE" = kharej ] && wiz_port_bound "$1"; then
        echo "$T_TRANSPORT/$1 is in use here; see: ss -lnp | grep :$1"
        return 1
    fi
    return 0
}

# Two characters are refused, and both were found by writing one and reading it
# back. A double quote ends the TOML string early, because the core's parser
# toggles on every quote it sees. A hash is worse, because it round trips
# through the core perfectly and is truncated by toml_get, which strips from a
# hash without caring whether it is inside a string - so the tunnel works and
# the fingerprint on the review panel is a different token's. Backslashes,
# pipes and spaces all survive both readers and are allowed.
v_wiz_token() {
    v_token "$1" || return 1
    case $1 in
    *'"'* | *'#'*)
        echo 'no " or # in a token - the config file cannot carry them intact'
        return 1
        ;;
    esac
    return 0
}

v_wiz_review() {
    case $1 in
    y | Y | yes | YES | n | N | no | NO | t | T) return 0 ;;
    esac
    echo "y to create it, n to stop, t to type your own token"
    return 1
}

v_wiz_paste() {
    local s=${1//[[:space:]]/}
    case $s in
    '') echo "paste the whole line the other server printed"; return 1 ;;
    PFY2.*) return 0 ;;
    esac
    echo "that is not a Pingify token - the line starts with PFY2."
    return 1
}

# --------------------------------------------------------------------------
# the six questions
# --------------------------------------------------------------------------

# The questions number themselves as they are asked.
#
# They used to carry the number in the title, and an ICMP tunnel does not have
# a port to ask about - so the wizard counted 1, 2, 3, 5, 6 and the person
# following it had every reason to wonder what they had missed.
WIZ_STEP=0
wiz_ask() {
    WIZ_STEP=$((WIZ_STEP + 1))
    rule "$WIZ_STEP $G_DOT $1"
}

q_side() {
    local n
    wiz_ask "Side"
    blank
    item "1" "IRAN" "clients connect here, and the ports live here"
    item "2" "KHAREJ" "your panel and inbounds run here"
    item "3" "Paste a token" "finish this server from the other one"
    blank
    blank
    dim "q at any question leaves without building anything"
    blank
    pick n "select" 1 3 || return 1
    case $n in
    1) T_SIDE=iran ;;
    2) T_SIDE=kharej ;;
    # Not a side. It is the other way in, and it is here rather than on a menu
    # of its own because "which server is this" is the first thing anybody
    # knows about the server they are sitting on, and finishing the second one
    # is the commonest answer of the three.
    3) T_SIDE=paste ;;
    esac
    return 0
}

# Asked on both servers, identically, because the file carries the address of
# the server abroad on both. The old wizard asked one side for "the remote" and
# the other for "the local", and the two answers were the same address written
# from two points of view, which is how the pair came to disagree.
# An address, in the colour addresses are printed in.
addr_text() { printf '%s%s%s' "$C_ADDR" "$1" "$C_OFF"; }

# Two questions, one for each end of the tunnel, and this server comes first
# because it is the one the script can answer for you.
#
# The address is read off this machine's own interfaces and offered as the
# default: if it is right, enter. When a server answers on more than one they
# are listed and picked from - taking the first and saying nothing is how the
# wrong one ends up in the file, and nothing says so until the other end has
# been dialling it for a quarter of an hour.
# Both addresses, in one step. They were two, and two steps to type two lines
# is a wizard that counts its own questions rather than the reader's work.
#
# This server's is read off its own interfaces and offered as the default: if
# it is right, enter. When a server answers on more than one they are listed
# and picked from - taking the first and saying nothing is how the wrong one
# ends up in the file, and nothing says so until the other end has been
# dialling it for a quarter of an hour.
q_addresses() {
    local def= n i=0 other=KHAREJ
    local -a addrs=()
    [ "$T_SIDE" = kharej ] && other=IRAN

    wiz_ask "Endpoints"
    blank
    # A name rather than an address is the whole of the CDN arrangement, and
    # it is one word rather than a question: a name can only ever front the
    # side that waits, because an edge answers on the name and connects
    # inward to the origin behind it. So a name here is what decides which
    # side dials, and nothing else needs asking.
    dim "an address, or a domain - a domain is what puts a CDN in front of it"
    blank
    while IFS= read -r n; do addrs+=("$n"); done < <(wiz_public_ips)

    if [ "${#addrs[@]}" -gt 1 ]; then
        dim "this server answers on more than one address - pick the right one"
        blank
        while [ "$i" -lt "${#addrs[@]}" ]; do
            item "$((i + 1))" "$(addr_text "${addrs[i]}")"
            i=$((i + 1))
        done
        item "$((i + 1))" "Something else" "a hostname, or one not listed"
        blank
        pick n "select" 1 $((i + 1)) || return 1
        if [ "$n" -le "${#addrs[@]}" ]; then
            T_HERE=${addrs[n - 1]}
        fi
        blank
    else
        def=${addrs[0]:-}
    fi
    [ -n "$T_HERE" ] || ask T_HERE "this server (${T_SIDE^^})" "$def" v_host || return 1
    ask T_THERE "the other one ($other)" "" v_host || return 1

    # Generated, never asked. Any path works and none is better than another,
    # so it is not a question - it exists so that a request for anything else
    # gets the 404 a web server would have given. The Advanced screen has it
    # for the rare case where a domain is shared with something else.
    case $T_TRANSPORT in
    ws | wss) T_PATH=$(wiz_path) ;;
    esac
    return 0
}

q_transport() {
    local n
    wiz_ask "Transport"
    blank
    item "1" "UDP" "a packet in, a packet out, nothing in the way"
    item "2" "TCP" "one open port, where a network carries only TCP"
    item "3" "WS" "an ordinary WebSocket - goes where HTTP goes"
    item "4" "WSS" "the same inside TLS - a domain, or a CDN in front"
    item "5" "ICMP" "inside ping packets - no open port at all"
    item "6" "GRE" "ip protocol 47 - no port to open, and no handshake"
    item "7" "AmneziaWG" "obfuscated WireGuard, encrypted, from their packages"
    item "8" "Raw TCP" "packets inside TCP segments the kernel never sees"
    item "9" "TCP UTLS" "a TLS connection whose hello is Chrome's, not Go's"
    blank
    dim "sixteen streams, Tehran to Frankfurt:"
    dim "  WS 427   WSS 405   ICMP 371   TCP 342   GRE 317"
    dim "and on a path with no such limits, Istanbul to Frankfurt:"
    dim "  UDP 332   AmneziaWG 194"
    blank
    dim "WS and WSS go behind a CDN, which makes them the ones to try when a"
    dim "port is blocked rather than slow. ICMP and GRE need no open port at"
    dim "all; while an ICMP tunnel runs, neither server answers a ping."
    blank
    dim "UDP and AmneziaWG are the two that some Iranian networks stop: a UDP"
    dim "flow there can be cut after a handful of packets whatever is inside"
    dim "it, which is a limit no setting on either can get around. Where UDP"
    dim "lives, both are good - AmneziaWG is also the only encrypted one here."
    blank
    dim "Raw TCP looks like TCP on the wire and behaves like UDP above it: no"
    dim "handshake, no retransmit, and none of the head-of-line waiting a real"
    dim "TCP tunnel pays for. It needs iptables, and root."
    blank
    dim "TCP UTLS is a plain TLS connection, and what a filter reads of one is"
    dim "the hello: Go's own says \"a Go program\" in the first packet. This one"
    dim "is Chrome's, from uTLS - the same thing fp=chrome selects elsewhere."
    blank
    pick n "select" 1 9 || return 1
    case $n in
    1) T_TRANSPORT=udp ;;
    2) T_TRANSPORT=tcp ;;
    3) T_TRANSPORT=ws ;;
    4) T_TRANSPORT=wss ;;
    5) T_TRANSPORT=icmp ;;
    6) T_TRANSPORT=gre ;;
    7) T_TRANSPORT=awg
       awg_install || return 1
       ;;
    8) T_TRANSPORT=rawtcp ;;
    9) T_TRANSPORT=utls ;;
    esac
    return 0
}

# Skipped whole for icmp, which has no ports: there is nothing to listen on and
# nothing to misconfigure, and that is half of why it survives.
q_port() {
    local def=8443 n
    # Neither of these has ports at all: one rides in echo requests and the
    # other is its own IP protocol.
    case $T_TRANSPORT in
    icmp | gre)
        T_PORT=
        return 0
        ;;
    awg)
        # The port asked for here is AmneziaWG's own, because that is the one
        # somebody has to open in a firewall. The carrier inside the link gets
        # a port of its own, worked out from the tunnel network below, where
        # nothing outside can reach it and nothing has to be asked.
        wiz_ask "Port"
        blank
        dim "AmneziaWG listens on this. The same number on both servers."
        blank
        ask T_AWG_PORT "port" "51820" v_awg_port || return 1
        return 0
        ;;
    esac
    wiz_ask "Port"
    blank
    dim "The same number on both servers, and the only port the tunnel needs."
    blank
    while IFS= read -r n; do
        [ "$(toml_get "$(cfg_file "$n")" transport type)" = icmp ] && continue
        dim "taken here:  $(toml_get "$(cfg_file "$n")" transport port)/$(toml_get "$(cfg_file "$n")" transport type)   $n"
    done < <(cfg_list)
    # Leaving the last candidate is the point of the bare break. The scan used
    # to end with def=8443, which is the number it had just proved was taken,
    # so pressing Enter at the prompt handed v_wiz_port a port it was certain
    # to refuse and the question asked itself again for no reason.
    while wiz_port_owner "$def" >/dev/null ||
        { [ "$T_SIDE" = kharej ] && wiz_port_bound "$def"; }; do
        def=$((def + 1))
        [ "$def" -gt 8500 ] && break
    done
    ask T_PORT "port" "$def" v_wiz_port || return 1
    return 0
}

# One question, not three. The old wizard asked for the octet and then re-asked
# both addresses it had just derived from it, so a hand edit at the second
# prompt walked straight past the checks that guarded the first.
# AmneziaWG's own port, which both servers bind: they each have a ListenPort,
# so something already holding it here is a link that will not come up at all.
#
# This check is the whole reason it is worth having. A leftover process on the
# Iran server was holding udp/51820, awg-quick could not bind it, the interface
# never appeared, and every screen above reported a tunnel whose far end had
# never been seen - which was true, and said nothing about why.
v_awg_port() {
    v_port "$1" || return 1
    if wiz_port_bound "$1" udp; then
        echo "something here already listens on udp/$1; see: ss -lunp | grep :$1"
        return 1
    fi
    return 0
}

# A path nobody scans for: six hex characters, from the kernel's own random
# device where there is one and from the shell's when there is not.
wiz_path() {
    local h
    h=$(head -c 3 /dev/urandom 2>/dev/null | od -An -tx1 | tr -d ' \n')
    [ -n "$h" ] || h=$(printf '%06x' $((RANDOM * RANDOM % 16777216)))
    printf '/%s' "$h"
}

q_link() {
    local def n a dev addr
    wiz_ask "Tunnel network"
    blank
    dim "A pair of addresses nothing else on either machine uses. Pick the"
    dim "middle number; both are worked out from it."
    blank
    while IFS= read -r n; do
        a=$(toml_get "$(cfg_file "$n")" tun iran)
        [ -n "$a" ] && dim "taken here:  ${a%%/*}/24  ($n)"
    done < <(cfg_list)
    while read -r dev addr; do
        case ${addr%%/*} in
        10.*) dim "taken here:  $addr  ($dev)" ;;
        esac
    done < <(ip -4 -o addr 2>/dev/null | awk '$3 == "inet" { print $2, $4 }')

    def=$(free_octet) || def=
    if [ -z "$def" ]; then
        warn "every 10.x.10.0/24 is inside an address on this host"
        fix "ip -4 -o addr   shows what has them"
    fi
    ask T_OCTET "range  10.x.10.0/24  -  x" "$def" v_wiz_octet || return 1

    T_DEV=$(free_device) || {
        bad "there is no free pfy device left on this host"
        return 1
    }
    blank
    field "IRAN" "$(addr_text "10.$T_OCTET.10.1/24")"
    field "KHAREJ" "$(addr_text "10.$T_OCTET.10.2/24")"
    field "device" "$T_DEV"
    return 0
}

# The screen that justifies the tool. Every number here was measured on the
# real path, restarted fresh at each queue depth, and the profile moves exactly
# one setting - tuning.queue_packets. Showing a bare number instead of what it
# buys is how the old tuning menu came to be scrolled past.
q_profile() {
    local n
    wiz_ask "Profile"
    blank
    item "1" "Gaming" "600 packets - a small one waits behind less"
    item "2" "Balanced" "900 packets - the one to pick if unsure"
    item "3" "Download" "1500 packets - most on a long transfer"
    blank
    dim "How many packets may wait in the tunnel's queue. Changeable later, on"
    dim "either server, without rebuilding anything."
    blank
    pick n "select" 2 3 || return 1
    case $n in
    1) T_PROFILE=gaming ;;
    2) T_PROFILE=balanced ;;
    3) T_PROFILE=download ;;
    esac
    return 0
}

wiz_queue() {
    case $1 in
    gaming) printf '600' ;;
    download) printf '1500' ;;
    *) printf '900' ;;
    esac
}

# --------------------------------------------------------------------------
# the token, which is generated rather than asked for
# --------------------------------------------------------------------------
#
# The core wants eight bytes; eighteen random ones are twenty-four base64
# characters, which removes a question, a validation loop, and the whole class
# of bug where one server has the token with a trailing space and the other
# does not.

wiz_token() {
    local t
    t=$(head -c 18 /dev/urandom 2>/dev/null | base64 2>/dev/null) || t=
    t=${t//$'\n'/}
    [ "${#t}" -ge 16 ] || return 1
    printf '%s' "$t"
}

wiz_sha256() {
    if have sha256sum; then sha256sum | cut -d' ' -f1
    elif have shasum; then shasum -a 256 | cut -d' ' -f1
    elif have openssl; then openssl dgst -sha256 | sed 's/.*= *//'
    else return 1
    fi
}

wiz_fingerprint() {
    local h
    h=$(printf '%s' "$1" | wiz_sha256) || { printf 'unknown'; return 0; }
    printf '%s' "${h:0:8}"
}

# --------------------------------------------------------------------------
# the review panel and the file it describes
# --------------------------------------------------------------------------

wiz_review() {
    local trans prof f
    f=$(cfg_file "$T_NAME")
    trans=${T_TRANSPORT^^}
    # For AmneziaWG the number worth showing is its own listening port, which
    # is the one somebody has to open. The carrier's port is inside the link
    # and nobody has to know it.
    if [ "$T_TRANSPORT" = awg ]; then
        trans="$trans  port ${T_AWG_PORT:-$(toml_get "$f" awg port)}"
    elif [ -n "$T_PORT" ]; then
        trans="$trans  port $T_PORT"
    fi
    case $T_TRANSPORT in
    tcp | ws | wss) trans="$trans  ${T_CONNS:-8} connections" ;;
    esac
    prof=${T_PROFILE:-balanced}
    blank
    panel_open "$T_NAME"
    panel_field "This server" "${T_SIDE^^}   $(addr_text "${T_HERE:-$([ "$T_SIDE" = iran ] && printf '%s' "$T_IRAN" || printf '%s' "$T_KHAREJ")}")"
    if [ "$T_SIDE" = iran ]; then
        panel_field "KHAREJ" "$(addr_text "$T_KHAREJ")"
    else
        panel_field "IRAN" "$(addr_text "$T_IRAN")"
    fi
    panel_field "Transport" "$trans"
    # Which end dials, said out loud, because for a WebSocket tunnel it is
    # worked out from the addresses rather than chosen - and the one thing a
    # person should be able to check on this screen is that it came out the
    # way they meant.
    local dialer=iran
    case $T_IRAN in *[a-zA-Z]*) case $T_KHAREJ in *[a-zA-Z]*) ;; *) dialer=kharej ;; esac ;; esac
    local target=$T_KHAREJ
    [ "$dialer" = kharej ] && target=$T_IRAN
    if [ "$T_SIDE" = "$dialer" ]; then
        panel_field "Dials" "out to $(addr_text "$target")"
    else
        panel_field "Waits" "${dialer^^} dials in"
    fi
    # "Link", not "Private link": it is the widest key any panel in the script
    # has, and one key a column wider than the rest puts one value out of line
    # with every other value in the box. The tunnel screen already calls it
    # this, so the two screens now agree as well.
    panel_field "Link" "10.$T_OCTET.10.1  $G_BOTH  10.$T_OCTET.10.2   $T_DEV"
    panel_field "Profile" "${prof^}   queue $(wiz_queue "$prof") packets"
    panel_field "Token" "${T_TOKEN:0:8}$G_CUT  (fingerprint $(wiz_fingerprint "$T_TOKEN"))"
    panel_close
    blank
}

# wiz_confirm shows the panel and asks, and both entrances use it.
#
# The only difference between them is whether the token may be retyped. On the
# paste path it may not: the token has to be the one the other server already
# has, and a different one produces a pair that links up never and explains
# itself never.
wiz_confirm() {
    local retype=${1:-no} go
    while :; do
        wiz_review
        ask go "create $T_NAME?" y v_wiz_review || return 1
        case $go in
        t | T)
            if [ "$retype" = yes ]; then
                ask T_TOKEN "security token" "" v_wiz_token || return 1
            else
                warn "the token has to match the other server; it came with the paste"
            fi
            continue
            ;;
        n | N | no | NO)
            blank
            dim "nothing was created"
            return 1
            ;;
        esac
        return 0
    done
}

# wiz_render writes the config to stdout.
#
# One space either side of every "=", because that is exactly what toml_set
# writes when it rewrites a line. The second server flips side through
# toml_set, and if the two shapes disagreed then a diff of the two servers'
# files would show a formatting change beside the one real difference - and
# that diff is how anybody checks the pair is a pair.
wiz_render() {
    printf '# Pingify %s\n' "$PINGIFY_VERSION"
    printf '#\n'
    printf '# The same file runs on both servers, but for the side and the name.\n'
    printf '\n[tunnel]\n'
    printf 'name = "%s"\n' "$T_NAME"
    printf 'side = "%s"\n' "$T_SIDE"
    printf 'mode = "tun"\n'
    printf '\n[transport]\n'
    printf 'type = "%s"\n' "$T_TRANSPORT"
    printf 'kharej = "%s"\n' "$T_KHAREJ"
    # Recorded, not dialled. KHAREJ never dials anything, so nothing uses this
    # - but both files carry it, so the operator of either server can see
    # which pair a tunnel belongs to without logging into the other one.
    [ -n "$T_IRAN" ] && printf 'iran = "%s"\n' "$T_IRAN"
    # No port key at all for icmp. Writing port = 0 would pass the core's check
    # and then sit in the file looking like a setting somebody chose.
    [ -n "$T_PORT" ] && printf 'port = %s\n' "$T_PORT"
    # Only a stream carrier opens more than one. On this path a single TCP
    # connection is shaped to nothing and eight together are not shaped at
    # all, which is the whole reason the number is here.
    case $T_TRANSPORT in
    tcp | ws | wss) printf 'connections = %s\n' "${T_CONNS:-8}" ;;
    esac
    [ -n "$T_PATH" ] && printf 'path = "%s"\n' "$T_PATH"
    # AmneziaWG's own half of the tunnel. The keys are both pairs, because
    # WireGuard needs a private key on each side and the other side's public
    # one - four values where every other transport has a single shared token -
    # and one file still has to describe the whole tunnel.
    if [ "$T_TRANSPORT" = awg ]; then
        printf '\n[awg]\n'
        printf 'name = "%s"\n' "$T_AWG_IFACE"
        printf 'iran = "10.%s.20.1/24"\n' "$T_OCTET"
        printf 'kharej = "10.%s.20.2/24"\n' "$T_OCTET"
        printf 'mtu = 1320\n'
        printf 'port = %s\n' "$T_AWG_PORT"
        printf 'iran_key = "%s"\n' "$T_AWG_IKEY"
        printf 'iran_pub = "%s"\n' "$T_AWG_IPUB"
        printf 'kharej_key = "%s"\n' "$T_AWG_KKEY"
        printf 'kharej_pub = "%s"\n' "$T_AWG_KPUB"
        printf 'jc = %s\n' "$T_AWG_JC"
        printf 'jmin = %s\n' "$T_AWG_JMIN"
        printf 'jmax = %s\n' "$T_AWG_JMAX"
        printf 's1 = %s\n' "$T_AWG_S1"
        printf 's2 = %s\n' "$T_AWG_S2"
        printf 'h1 = %s\n' "$T_AWG_H1"
        printf 'h2 = %s\n' "$T_AWG_H2"
        printf 'h3 = %s\n' "$T_AWG_H3"
        printf 'h4 = %s\n' "$T_AWG_H4"
    fi
    printf '\n[security]\n'
    printf 'token = "%s"\n' "$T_TOKEN"
    printf '\n[tuning]\n'
    printf 'profile = "%s"\n' "$T_PROFILE"
    printf '\n[tun]\n'
    printf 'name = "%s"\n' "$T_DEV"
    printf 'iran = "10.%s.10.1/24"\n' "$T_OCTET"
    printf 'kharej = "10.%s.10.2/24"\n' "$T_OCTET"
    # Not asked. 1320 works on every path we have measured, and Measure MTU on
    # the tunnel screen finds the real number properly.
    printf 'mtu = %s\n' "${T_MTU:-1320}"
    printf '\n[logging]\n'
    printf 'level = "info"\n'
    printf '\n[status]\n'
    printf 'port = %s\n' "${T_STATUS:-$STATUS_BASE}"
    # The same on both servers, and it stays that way: it is bound to this
    # tunnel's private address, which nothing else on either machine has.
    printf 'health_port = %s\n' "${T_HEALTH:-$HEALTH_PORT}"
}

# --------------------------------------------------------------------------
# writing it, and saying honestly what happened
# --------------------------------------------------------------------------

# tunnel_create NAME [FILE] - FILE is the finished config; with no FILE the
# config is read from stdin.
tunnel_create() {
    local name=$1 src=${2:-} f out
    [ -n "$name" ] || { bad "a tunnel needs a name"; return 1; }
    if ! ensure_dirs; then
        bad "could not create $CFG_DIR"
        fix "run this as root"
        return 1
    fi
    f=$(cfg_file "$name")
    [ -e "$f" ] && { bad "there is already a tunnel called $name here"; return 1; }
    if [ ! -x "$CORE_BIN" ]; then
        bad "the core is not installed at $CORE_BIN"
        fix "install Pingify first - nothing has been changed"
        return 1
    fi

    # The file is 0600 before a single byte of the token exists in it. Writing
    # first and fixing the mode afterwards leaves a window where anyone with an
    # account on the box can read it, and on a shared VPS that window is enough.
    if ! : >"$f"; then
        bad "could not write $f"
        return 1
    fi
    chmod 0600 "$f"
    # A failed copy used to return 1 with nothing on the screen, and both
    # wizards just passed that 1 up, so six answered questions ended in silence
    # - the only failure in this file that never said what went wrong. A full
    # disk and a read-only /etc both land here.
    if [ -n "$src" ]; then
        cat "$src" >"$f" || { bad "could not write $f"; rm -f "$f"; return 1; }
    else
        cat >"$f" || { bad "could not write $f"; rm -f "$f"; return 1; }
    fi

    if ! out=$("$CORE_BIN" -c "$f" -check 2>&1); then
        bad "the core will not accept that config - nothing created"
        printf '%s\n' "$out" | sed 's/^/       /'
        rm -f "$f"
        return 1
    fi
    # Cut to fit rather than run over the edge: a long tunnel name makes a long
    # path, and this is the one line in the wizard that carries one.
    ok "$(trunc_to "$f" $((UI_W - 30))) accepted by the core"

    # A repair, not a rewrite: the units are written once at install, and doing
    # it per tunnel is how the old script came to rewrite four units whenever
    # anybody added one.
    [ -f "$UNIT_DIR/pingify@.service" ] || unit_write

    # The AmneziaWG link is the wire this tunnel runs on, so it comes up
    # first. If it will not, the tunnel is not started: a carrier dialling an
    # address on a link that does not exist would sit there reporting nothing
    # is wrong except that the far end has never been seen.
    case $(toml_get "$f" transport type) in
    awg)
        if ! awg_up "$name"; then
            rm -f "$f"
            return 1
        fi
        ok "the AmneziaWG link $(awg_iface "$name") is up"
        ;;
    rawtcp)
        # Without this the kernel answers our own segments with an RST and
        # the tunnel resets itself every few seconds.
        if ! rawtcp_guard "$(toml_get "$f" transport port)"; then
            bad "could not tell the firewall to stop answering for this port"
            fix "iptables is needed for a raw tcp tunnel"
            rm -f "$f"
            return 1
        fi
        ok "the kernel will not answer on tcp/$(toml_get "$f" transport port)"
        ;;
    esac

    # svc_do enable returns the truth about is-active and prints the journal
    # when it failed. Returning its status is the point: the old caller printed
    # a green "is running" over a unit that had never started.
    svc_do enable "$name"
}

# --------------------------------------------------------------------------
# the setup token: PFY2. + base64 of "<sha256 of body>|<the TOML verbatim>"
# --------------------------------------------------------------------------

token_encode() {
    local file=$1 body sum out
    [ -f "$file" ] || { echo "there is no file at $file" >&2; return 1; }
    # Trailing newlines are dropped here and on the way back, on purpose: a
    # command substitution eats them anyway, so checksumming what survives the
    # journey is the only way the two sums can agree.
    body=$(cat "$file") || return 1
    sum=$(printf '%s\n' "$body" | wiz_sha256) || {
        echo "no sha256 tool here, so no token can be made" >&2
        return 1
    }
    out=$( { printf '%s|' "$sum"; printf '%s\n' "$body"; } | base64) || return 1
    printf 'PFY2.%s\n' "${out//$'\n'/}"
}

token_decode() {
    local line=$1 raw sum body have
    # Every kind of whitespace comes out first. The line is long enough to wrap
    # in any terminal, and a paste that picked up the wrap is the single most
    # common way this fails; base64 has no whitespace in it to lose.
    line=${line//[[:space:]]/}
    case $line in
    PFY2.*) ;;
    *) echo "that is not a Pingify token - the line starts with PFY2." >&2; return 1 ;;
    esac
    raw=$(printf '%s' "${line#PFY2.}" | base64 -d 2>/dev/null) || {
        echo "the token will not decode - copy the whole line" >&2
        return 1
    }
    # Split on the first pipe only: a hand-typed security token may contain
    # one, and a sha256 never does.
    sum=${raw%%|*}
    body=${raw#*|}
    [ "$sum" != "$raw" ] || {
        echo "the token will not decode - copy the whole line" >&2
        return 1
    }
    have=$(printf '%s\n' "$body" | wiz_sha256) || {
        echo "no sha256 tool here, so the token cannot be checked" >&2
        return 1
    }
    if [ "$have" != "$sum" ]; then
        echo "the token checksum does not match - copy the whole line" >&2
        return 1
    fi
    printf '%s\n' "$body"
}

# --------------------------------------------------------------------------
# build a new tunnel
# --------------------------------------------------------------------------

wizard_new() {
    local f other
    WIZ_QUIT=0
    T_SIDE= T_KHAREJ= T_IRAN= T_HERE= T_THERE= T_TRANSPORT= T_PORT= T_OCTET= T_PROFILE= T_HEALTH=
    T_PATH= T_AWG_PORT= T_AWG_IFACE=
    T_AWG_IKEY= T_AWG_IPUB= T_AWG_KKEY= T_AWG_KPUB=
    T_AWG_JC= T_AWG_JMIN= T_AWG_JMAX= T_AWG_S1= T_AWG_S2=
    T_AWG_H1= T_AWG_H2= T_AWG_H3= T_AWG_H4=
    T_NAME= T_DEV= T_TOKEN= T_MTU=1320 T_STATUS=
    WIZ_STEP=0

    screen_top
    blank
    rule "New tunnel"
    blank

    q_side || return 1
    # The third answer to the first question is not a side. It is the other
    # way in: on the second server everything this wizard would ask is already
    # inside the token the first one printed, so there is nothing to ask.
    if [ "$T_SIDE" = paste ]; then
        wizard_paste
        return $?
    fi
    blank
    q_addresses || return 1

    # Which of the two answers is which key. The file names both ends, and it
    # names them the same way on both servers, so the mapping happens once
    # here rather than at every place that reads them.
    if [ "$T_SIDE" = iran ]; then
        T_IRAN=$T_HERE
        T_KHAREJ=$T_THERE
    else
        T_KHAREJ=$T_HERE
        T_IRAN=$T_THERE
    fi

    blank
    q_transport || return 1
    blank
    q_port || return 1
    blank
    q_link || return 1
    blank
    q_profile || return 1

    # AmneziaWG carries two more things the tunnel network decides: the
    # addresses of the link itself, beside the tunnel's own, and the port the
    # carrier uses inside it - which is derived rather than asked because
    # nothing outside the link can reach it and the octet already makes it
    # unique on this host.
    if [ "$T_TRANSPORT" = awg ]; then
        T_PORT=$((20900 + T_OCTET))
        # The tunnel rides inside the AmneziaWG link, so its packets have to
        # fit in one of theirs: 1320 on the link, less 20 of IP, 8 of UDP and
        # the twelve this core puts in front of a packet.
        T_MTU=1280
        T_AWG_IFACE=$(awg_free_iface) || {
            bad "there is no free awg device left on this host"
            return 1
        }
        awg_generate || {
            bad "AmneziaWG would not generate a key here"
            return 1
        }
    fi

    T_NAME=$(default_name)

    # The health port is not asked for, and this is the reason: the only thing
    # that could be wrong with it is something else on this machine holding it
    # on every address, and that is a question the machine answers faster than
    # a person can. It goes in the shared file, so both servers get the number
    # this one settled on.
    if ! T_HEALTH=$(wiz_free_health); then
        T_HEALTH=$HEALTH_PORT
        warn "$HEALTH_PORT and the twenty above it are all taken on this server"
        fix "the tunnel will work; its round trip will not be measurable"
    elif [ "$T_HEALTH" != "$HEALTH_PORT" ]; then
        blank
        dim "$HEALTH_PORT is taken here, so the health port is $T_HEALTH on both servers"
    fi
    # Stop here rather than build a tunnel whose core cannot bind its status
    # port: the home screen reads every number through that endpoint, so a
    # tunnel without one is a tunnel nothing can report on.
    if ! T_STATUS=$(wiz_free_status_port); then
        bad "every status port from $STATUS_BASE is taken here"
        fix "delete a tunnel, or set [status] port by hand"
        return 1
    fi
    if ! T_TOKEN=$(wiz_token); then
        warn "no random source here, so the token has to be typed"
        ask T_TOKEN "security token" "" v_wiz_token || return 1
    fi

    wiz_confirm yes || return 1

    blank
    f=$(mktemp) || { bad "could not make a temporary file"; return 1; }
    wiz_render >"$f"
    if ! tunnel_create "$T_NAME" "$f"; then
        rm -f "$f"
        return 1
    fi
    rm -f "$f"

    other=KHAREJ
    [ "$T_SIDE" = kharej ] && other=IRAN
    wiz_handoff "$T_NAME" "$other"
}

wiz_handoff() {
    local name=$1 other=$2 line
    if ! line=$(token_encode "$(cfg_file "$name")"); then
        bad "the config is written, but the token could not be made"
        fix "copy the file to $other by hand and change side there"
        return 1
    fi
    blank
    rule "Now the other server"
    blank
    dim "Run Pingify on $other, pick \"Finish the pair\", and paste:"
    blank
    # Printed flush left with nothing around it, so a double click or a triple
    # click selects the token and only the token.
    say "$line"
    blank
    warn "treat that like a password: the token is inside it"
    blank
    return 0
}

# --------------------------------------------------------------------------
# finish the pair
# --------------------------------------------------------------------------

wizard_paste() {
    local line f err a own n clash moved
    WIZ_QUIT=0
    blank
    rule "Paste a token"
    blank
    dim "Paste the line the first server printed. It carries"
    dim "the whole config, so there is nothing left to answer."
    blank
    ask line "paste the line from the other server" "" v_wiz_paste || return 1

    f=$(mktemp) || { bad "could not make a temporary file"; return 1; }
    # stderr into the substitution, stdout into the file: the order matters,
    # because 2>&1 copies where stdout points *now*.
    if ! err=$(token_decode "$line" 2>&1 >"$f"); then
        blank
        bad "$err"
        fix "copy the whole line again from the first server"
        rm -f "$f"
        return 1
    fi

    T_NAME=$(toml_get "$f" tunnel name)
    T_SIDE=$(toml_get "$f" tunnel side)
    T_TRANSPORT=$(toml_get "$f" transport type)
    T_KHAREJ=$(toml_get "$f" transport kharej)
    T_IRAN=$(toml_get "$f" transport iran)
    T_PORT=$(toml_get "$f" transport port)
    T_PATH=$(toml_get "$f" transport path)
    T_TOKEN=$(toml_get "$f" security token)
    T_PROFILE=$(toml_get "$f" tuning profile)
    T_DEV=$(toml_get "$f" tun name)
    T_MTU=$(toml_get "$f" tun mtu)
    a=$(toml_get "$f" tun iran)
    T_OCTET=${a#10.}
    T_OCTET=${T_OCTET%%.*}

    # The checksum says the file arrived whole; it does not say it was a
    # Pingify config. Everything below indexes on these four, so they are
    # checked here rather than found missing halfway through the collision
    # checks with an arithmetic error for a message.
    if ! v_name "$T_NAME" >/dev/null 2>&1 ||
        ! v_octet "$T_OCTET" >/dev/null 2>&1 ||
        [ -z "$T_DEV" ] || [ -z "$T_TRANSPORT" ]; then
        bad "that token decoded, but it is not a Pingify config"
        fix "paste the line the other server printed"
        rm -f "$f"
        return 1
    fi

    # The side in the file is the *other* server's. This flip is the entire
    # second installation.
    case $T_SIDE in
    iran) T_SIDE=kharej ;;
    kharej) T_SIDE=iran ;;
    *) bad "that token does not say which server made it"; rm -f "$f"; return 1 ;;
    esac
    toml_set "$f" tunnel side "$T_SIDE"

    # And the name goes with it. The name begins with the side, so a file
    # pasted onto KHAREJ that still called itself iran-udp-8443 would be the
    # one thing on this server whose name was a lie about it.
    T_NAME=$(name_for_side "$T_NAME" "$T_SIDE")
    toml_set "$f" tunnel name "$T_NAME"

    # The file is shared, so a clash here can only be fixed on both servers.
    # This is the one thing the shared-file design costs, and it is the
    # manager's job to spell out, not the user's to work out.
    clash=0
    if [ -e "$(cfg_file "$T_NAME")" ]; then
        bad "there is already a tunnel called $T_NAME here"
        fix "delete that one first, or use a different octet"
        clash=1
    fi
    if own=$(wiz_link_owner "$T_OCTET"); then
        bad "10.$T_OCTET.10.0/24 is in use here by $own"
        fix "change the range on both servers, and paste again"
        clash=1
    fi
    if own=$(wiz_device_owner "$T_DEV"); then
        bad "the device $T_DEV is in use here by $own"
        fix "the device is in the shared file - change both"
        clash=1
    fi
    # The health port comes with the file and this server has to be able to
    # bind it too. It is a warning rather than a clash: the tunnel carries
    # traffic without it, and what is lost is the round trip measurement and
    # the check that asks the far end whether it is there.
    a=$(toml_get "$f" status health_port)
    case $a in '' | *[!0-9]*) a=$HEALTH_PORT ;; esac
    if wiz_health_bound "$a"; then
        warn "something here already holds port $a on every address"
        fix "the tunnel works; its round trip will not be measurable"
        fix "to fix it, set status.health_port to a free number on both servers"
    fi

    if [ "$T_SIDE" = kharej ] && [ "$T_TRANSPORT" != icmp ]; then
        if own=$(wiz_port_owner "$T_PORT"); then
            bad "port $T_PORT already belongs to $own"
            fix "change the port on both servers, and paste again"
            clash=1
        elif wiz_port_bound "$T_PORT"; then
            bad "something here already listens on $T_TRANSPORT/$T_PORT"
            fix "ss -lnup | grep :$T_PORT   shows what has it"
            clash=1
        fi
    fi
    if [ "$clash" = 1 ]; then
        blank
        dim "nothing was created"
        rm -f "$f"
        return 1
    fi

    # The status port is loopback-only and per host, so it is the one number
    # that may legitimately differ between the two files. It is checked again
    # here because this server does not have the same tunnels on it.
    T_STATUS=$(toml_get "$f" status port)
    # Anything that is not a port counts as absent, and the empty string is the
    # reason: a pasted file with no [status] port compared equal to every local
    # tunnel that also had none, so the screen read "status port  is taken here
    # by <n>" with a blank where the number belongs. An absent port is filled
    # in below instead of being reported as a clash.
    case $T_STATUS in '' | *[!0-9]*) T_STATUS= ;; esac
    moved=0
    if [ -n "$T_STATUS" ]; then
        while IFS= read -r n; do
            [ "$(toml_get "$(cfg_file "$n")" status port)" = "$T_STATUS" ] || continue
            warn "status port $T_STATUS is taken here by $n"
            T_STATUS=
            moved=1
            break
        done < <(cfg_list)
    fi
    if [ -z "$T_STATUS" ]; then
        if ! T_STATUS=$(wiz_free_status_port); then
            bad "every status port from $STATUS_BASE is taken here"
            fix "delete a tunnel, or set [status] port by hand"
            rm -f "$f"
            return 1
        fi
        [ "$moved" = 1 ] && dim "this file uses $T_STATUS, so the two differ there too"
        toml_set "$f" status port "$T_STATUS"
    fi

    wiz_confirm no || { rm -f "$f"; return 1; }

    blank
    if ! tunnel_create "$T_NAME" "$f"; then
        rm -f "$f"
        return 1
    fi
    rm -f "$f"
    blank
    ok "both ends are configured now - nothing else to paste"
    dim "give it a few seconds and look at it on the home screen"
    blank
    return 0
}

# --------------------------------------------------------------------------
# the way in
# --------------------------------------------------------------------------

# The two entrances, and nothing else.
#
# menu_key rather than pick, because 0 is a key here and pick only answers 1..N
# on purpose - a question with a numbered list of answers must not accept a
# number that is not one of them. Navigation screens have a Back key; questions
# do not.
# The way in, and there is only one now.
#
# There were two, on a menu of their own: build a tunnel, or finish the pair.
# It was a screen that asked which of two wizards you wanted before either had
# said anything, and the answer is the same thing the first question of the
# wizard asks anyway - which server am I sitting on. So the menu is gone and
# "Paste a token" is the third answer to that question.
screen_new() {
    wizard_new
    return 0
}
#!/usr/bin/env bash
#
# The screen a person looks at most: one tunnel, what it is doing, and the
# things they might want to do to it.
#
# It is one screen and it fits on a phone. The old manager put the same
# information behind three menus and then listed the tunnels twice on the way
# in - once as a status table and again as a numbered list of the same names -
# so choosing one meant reading the same six words in two places and matching
# them up by eye.

# --------------------------------------------------------------------------
# what a tunnel is doing
# --------------------------------------------------------------------------

# tun_line fills TL_* for one tunnel: enough for a row on the home screen.
#
# Two sources and no third. systemd says whether the unit is running, and the
# core's own status endpoint says whether it is carrying anything. Nothing here
# reads the log, because a log line is prose and prose gets reworded - the old
# manager took the eighth field of an English sentence and broke the day
# somebody improved the sentence.
# The queue depth beside the profile's name. "balanced" on its own does not
# say what it does, and the depth is the whole of what a profile changes.
prof_queue_note() {
    local f=$1 q
    q=$(toml_get "$f" tuning queue_packets)
    [ -n "$q" ] || q=$(wiz_queue "$(toml_get "$f" tuning profile)")
    [ -n "$q" ] || return 0
    printf ' %s %s packets' "$G_DASH" "$q"
}

tun_line() {
    local name=$1 state
    TL_STATE=unknown TL_RATE= TL_PEER= TL_RTT= TL_TRANSPORT= TL_SIDE= TL_UPTIME=

    local f
    f=$(cfg_file "$name")
    TL_TRANSPORT=$(toml_get "$f" transport type)
    TL_SIDE=$(toml_get "$f" tunnel side)
    TL_PEER=$(peer_addr "$name")

    state=$(svc_state "$name")
    case $state in
    disabled | stopped)
        TL_STATE=$state
        return
        ;;
    esac

    if tun_stats "$name"; then
        # Running and the far end has been seen is the only state that earns a
        # green dot. Running and alone looks identical from here and is not
        # the same thing at all.
        if [ "$ST_UP" = true ] && [ "${ST_INB:-0}" != 0 ]; then
            TL_STATE=running
        else
            TL_STATE=idle
        fi
        TL_RATE="$(round1 "$ST_IN") in, $(round1 "$ST_OUT") out"
        TL_UPTIME=$(human_secs "$ST_UPTIME")
    else
        # The unit is up but the endpoint does not answer. That is a real
        # state and it is not a failure to report in red: it happens for the
        # first second of every start.
        TL_STATE=idle
    fi
    TL_RTT=$(tun_rtt "$name")
}

# peer_addr is the other end of the private link, without its prefix.
peer_addr() {
    local f side a
    f=$(cfg_file "$1")
    side=$(toml_get "$f" tunnel side)
    if [ "$side" = iran ]; then
        a=$(toml_get "$f" tun kharej)
    else
        a=$(toml_get "$f" tun iran)
    fi
    printf '%s' "${a%%/*}"
}

my_addr() {
    local f side a
    f=$(cfg_file "$1")
    side=$(toml_get "$f" tunnel side)
    if [ "$side" = iran ]; then
        a=$(toml_get "$f" tun iran)
    else
        a=$(toml_get "$f" tun kharej)
    fi
    printf '%s' "${a%%/*}"
}

# tun_rtt is the round trip across the private link, or nothing.
#
# Nothing, on an ICMP tunnel, and that is the correct answer rather than a
# missing one. An ICMP carrier stops both kernels answering echo - it has to,
# or every packet it sends is answered twice - so a ping across the link goes
# out and is deliberately ignored. The old manager would have drawn that in red
# and told the user their working tunnel was dead.
tun_rtt() {
    local name=$1 t out hp peer
    t=$(toml_get "$(cfg_file "$name")" transport type)

    # An ICMP tunnel cannot be pinged. The carrier stops both kernels
    # answering echo - it has to, or every packet it sends is answered twice -
    # so the ping goes out and is deliberately ignored, and for a long time
    # this returned nothing at all and every screen showed a dash.
    #
    # The far end answers on its health port instead, and curl's time_connect
    # is the TCP handshake: one round trip across the link and nothing else in
    # it. It is the same measurement a ping would have made.
    if [ "$t" = icmp ]; then
        have curl || return 0
        hp=$(health_port_of "$name")
        peer=$(peer_addr "$name")
        [ -n "$peer" ] && [ "$hp" -gt 0 ] 2>/dev/null || return 0
        out=$(LC_ALL=C curl -s -o /dev/null --max-time 2 \
            -w '%{time_connect}' "http://$peer:$hp/healthz" 2>/dev/null) || return 0
        case $out in '' | 0 | 0.000000) return 0 ;; esac
        LC_ALL=C awk -v t="$out" 'BEGIN { printf "%.0f", t * 1000 }'
        return 0
    fi

    have ping || return 0
    # Two packets a fifth of a second apart, and one second to wait. This is
    # on the path of every redraw of the home screen: -c 2 -W 2 meant a tunnel
    # whose far end had stopped answering cost four seconds of nothing before
    # the menu appeared, once for every tunnel on the server.
    out=$(ping -c 2 -i 0.2 -W 1 -q "$(peer_addr "$name")" 2>/dev/null |
        awk -F'/' '/^rtt|^round-trip/ {printf "%.0f", $5}')
    printf '%s' "$out"
}

# --------------------------------------------------------------------------
# the tunnel screen
# --------------------------------------------------------------------------

screen_tunnel() {
    local name=$1 f
    f=$(cfg_file "$name")
    [ -f "$f" ] || { bad "there is no tunnel called $name"; return 1; }

    while :; do
        screen_top
        tun_line "$name"
        blank
        printf '  %s%s%s%s%s %s\n' "$C_B" "$name" "$C_OFF" \
            "$(rep ' ' $((UI_W - ${#name} - 16)))" \
            "$(state_dot "$TL_STATE")" "$TL_STATE"
        blank

        local side kharej port transport mtu dev prof
        side=$(toml_get "$f" tunnel side)
        kharej=$(toml_get "$f" transport kharej)
        port=$(toml_get "$f" transport port)
        transport=$(toml_get "$f" transport type)
        mtu=$(toml_get "$f" tun mtu)
        dev=$(toml_get "$f" tun name)
        prof=$(toml_get "$f" tuning profile)

        # What this server is, in one line, said the way round that matters:
        # which end dials and which end waits. The old line said "iran" and
        # left the reader to remember which of the two does what.
        if [ "$side" = iran ]; then
            if [ "$transport" = icmp ]; then
                field "This end" "IRAN $G_DASH dials $(addr_text "$kharej") inside ping packets"
            else
                field "This end" "IRAN $G_DASH dials $(addr_text "$kharej") on $transport/$port"
            fi
        else
            local iran_addr
            iran_addr=$(toml_get "$f" transport iran)
            if [ "$transport" = icmp ]; then
                field "This end" "KHAREJ $G_DASH waits for ping packets from IRAN"
            else
                field "This end" "KHAREJ $G_DASH waits on $transport/$port"
            fi
            [ -n "$iran_addr" ] && field "IRAN is" "$(addr_text "$iran_addr")"
        fi
        # The name and the path, for the transports that have one. It is the
        # one thing about a WebSocket tunnel that is not in the line above,
        # and the one somebody putting a proxy in front of it needs.
        local dom
        dom=$(toml_get "$f" transport domain)
        if [ -n "$dom" ]; then
            field "Address" "$(addr_text "$dom")$(toml_get "$f" transport path)"
        fi
        field "Link" "$(my_addr "$name") $G_BOTH $(peer_addr "$name")   $dev   mtu $mtu"

        # One measurement to a line, each with the name of what it is. They
        # were one line with two numbers on it and nothing saying which was
        # which, five blank columns apart.
        if [ -n "$TL_RATE" ]; then
            field "Traffic" "$TL_RATE  Mbit/s"
        fi
        if [ -n "$TL_RTT" ]; then
            field "Round trip" "$(rtt_colour "$TL_RTT")$TL_RTT ms$C_OFF"
        elif [ "$transport" = icmp ]; then
            field "Round trip" "$C_MUTE""not measurable across an ICMP tunnel""$C_OFF"
        fi
        [ -n "${TL_UPTIME:-}" ] && field "Up for" "$TL_UPTIME"

        # Losses only when there are some. A line saying zero every time is a
        # line people stop reading, and then they do not see it change.
        if [ -n "${ST_LOST:-}" ] && [ "${ST_LOST:-0}" -gt 0 ]; then
            local per=$((ST_LOST / (ST_GAPS > 0 ? ST_GAPS : 1)))
            field "Path lost" "$ST_LOST packets in $ST_GAPS gaps, about $per at a time"
        fi

        local fw
        fw=$(forwards_of "$name" 2>/dev/null || true)
        [ -n "$fw" ] && field "Ports" "$fw  $G_ARROW  $(peer_addr "$name")"

        blank
        group "RUN"
        case $TL_STATE in
        stopped | disabled) item 1 "Start" "and start it again at every boot" ;;
        *) item 1 "Restart" "stop it and start it again" ;;
        esac
        item 2 "Stop" "until you start it, or the server reboots"
        item 3 "Live view" "the numbers above, once a second"
        blank
        group "CHECK"
        item 4 "Health check" "what is wrong, and what to do about it"
        item 5 "Log" "the last forty lines the core wrote"
        item 6 "Measure MTU" "the largest packet this path will carry"
        item 7 "Speed test" "iperf3 across the tunnel, sixteen streams"
        blank
        group "CHANGE"
        if [ "$side" = iran ]; then
            item2 8 "Ports" "${fw:-nothing is forwarded yet}"
        else
            item2 8 "Ports" "IRAN forwards them, not this side"
        fi
        item2 9 "Profile" "$prof$(prof_queue_note "$f")"
        item 10 "Advanced" "mtu, log level, queue depth, the file itself"
        item 11 "Delete this tunnel" "here only - the other server keeps its copy"
        item 0 "Back"
        blank

        local k
        menu_key k || return 0
        case $k in
        1) svc_do restart "$name"; pause ;;
        2) svc_do stop "$name"; pause ;;
        3) screen_live "$name" ;;
        4) health_check "$name"; pause ;;
        5) show_log "$name" ;;
        6) measure_mtu "$name"; pause ;;
        7) speed_test "$name"; pause ;;
        8) [ "$side" = iran ] && { screen_ports "$name"; } ||
            { warn "ports are forwarded from the IRAN side"; pause; } ;;
        9) edit_profile "$name" ;;
        10) screen_advanced "$name" ;;
        11) delete_tunnel "$name" && return 0 ;;
        0 | '') return 0 ;;
        esac
    done
}

pause() {
    blank
    printf '  %spress enter%s' "$C_MUTE" "$C_OFF" >&2
    IFS= read -r _ || true
}

show_log() {
    screen_top
    blank
    rule "Log $G_DASH $1"
    blank
    journalctl -u "pingify@$1" -n 40 --no-pager -o cat 2>/dev/null |
        sed 's/^/    /' || dim "there is no journal for this tunnel yet"
    pause
}

# --------------------------------------------------------------------------
# changing one
# --------------------------------------------------------------------------

# edit_profile is the screen that justifies the whole tool: it does not show a
# setting, it shows what the setting buys. Every number here was measured on a
# real path between Tehran and Frankfurt.
edit_profile() {
    local name=$1 cur choice
    cur=$(toml_get "$(cfg_file "$name")" tuning profile)

    screen_top
    blank
    rule "Profile"
    blank
    profile_row 1 gaming "$cur" "600 packets - a small one waits behind less"
    profile_row 2 balanced "$cur" "900 packets - the one to pick if unsure"
    profile_row 3 download "$cur" "1500 packets - most on a long transfer"
    blank
    dim "A profile sets one number: how many packets may wait in the tunnel's"
    dim "queue. A deeper queue carries more at once and holds a packet longer;"
    dim "a shallower one answers sooner and gives up some throughput for it."
    blank
    dim "Both servers should be on the same one. Changing it restarts the"
    dim "tunnel here, which costs a second of traffic and nothing else."
    blank

    local def=2
    case $cur in gaming) def=1 ;; download) def=3 ;; esac

    # A way out that is a number, like every other screen reached from a menu.
    # This used pick, which answers 1 to 3 and nothing else on purpose - that
    # is right for a question in the wizard and wrong here: 0 was refused and
    # the screen asked again, so the only exit was the q nothing on it
    # mentions. Enter still keeps what the tunnel already has.
    item 0 "Leave it on $cur"
    blank
    menu_key choice || return 0
    [ -z "$choice" ] && choice=$def

    local want
    case $choice in
    1) want=gaming ;;
    2) want=balanced ;;
    3) want=download ;;
    0) return 0 ;;
    *) blank; warn "there is nothing on $choice"; pause; return 0 ;;
    esac
    [ "$want" = "$cur" ] && return 0

    PROFILE_WANT=$want
    if cfg_apply "$name" _edit_profile yes; then
        ok "$name is on the $want profile"
    fi
    pause
}

_edit_profile() { toml_set "$1" tuning profile "$PROFILE_WANT"; }

# One profile, with a mark against the one this tunnel is on now.
#
# It is item() with that mark written over the left margin rather than a line
# of its own, so the three of them line up with every other menu in the script
# and there is only one place that decides how a menu line looks.
profile_row() {
    local key=$1 name=$2 cur=$3 hint=$4 line mark=' '
    # A dot, not the same arrow the line already has: two arrows on one line
    # is a line where neither of them means anything.
    [ "$name" = "$cur" ] && mark=$G_ON
    line=$(item "$key" "${name^}" "$hint")
    printf ' %s%s%s%s\n' "$C_OK" "$mark" "$C_OFF" "${line#  }"
}

screen_advanced() {
    local name=$1 f k q qs lv
    f=$(cfg_file "$name")
    while :; do
        screen_top
        # Two of these are not in the file until somebody sets them: the
        # profile carries the queue depth, and the core picks the number of
        # device queues. Reading the file alone drew "Queue depth  packets,
        # from the profile" with the number missing out of the middle of it,
        # and then offered an empty default that the validator refused - so
        # pressing enter at the question did nothing at all, twice.
        q=$(toml_get "$f" tuning queue_packets)
        qs=$(toml_get "$f" tun queues)
        lv=$(toml_get "$f" logging level)
        # Same as the two below: the core fills this in when the file leaves
        # it out, so reading the file alone drew an empty row and offered an
        # empty default that the validator then refused.
        [ -n "$lv" ] || lv=info
        blank
        rule "Advanced $G_DASH $name"
        blank
        item2 1 "MTU" "$(toml_get "$f" tun mtu)"
        item2 2 "Log level" "$lv"
        if [ -n "$q" ]; then
            item2 3 "Queue depth" "$q packets, set here"
        else
            q=$(wiz_queue "$(toml_get "$f" tuning profile)")
            item2 3 "Queue depth" "$q packets, from the profile"
        fi
        item2 4 "Device queues" "${qs:-the core chooses}"
        item2 5 "Health port" "$(health_port_of "$name") on $(my_addr "$name")"
        case $(toml_get "$f" transport type) in
        ws | wss) item2 6 "Web path" "$(toml_get "$f" transport path)" ;;
        esac
        item 7 "Show the config file"
        item 0 "Back"
        blank
        menu_key k || return 0
        case $k in
        1) local v
            ask v "mtu" "$(toml_get "$f" tun mtu)" v_mtu || continue
            MTU_WANT=$v; cfg_apply "$name" _edit_mtu yes; pause ;;
        2) local v
            blank; dim "debug says a great deal; info says what changed"; blank
            ask v "level" "$lv" v_level || continue
            LEVEL_WANT=$v; cfg_apply "$name" _edit_level yes; pause ;;
        3) blank
            dim "This comes from the profile and is the one number a profile moves."
            dim "Set it directly only if you have measured your own path."
            local v
            ask v "packets" "$q" v_queue || continue
            QUEUE_WANT=$v; cfg_apply "$name" _edit_queue yes; pause ;;
        4) local v
            ask v "queues (0 lets the core choose)" "${qs:-0}" v_queues || continue
            QUEUES_WANT=$v; cfg_apply "$name" _edit_queues yes; pause ;;
        5) blank
            dim "The port the server at the other end is asked on, over the"
            dim "private link. It is bound to this tunnel's own address, so"
            dim "nothing else on this machine can be in the way of it unless"
            dim "something holds that port on every address."
            blank
            dim "Both servers must use the same number, and changing it here"
            dim "changes it here only."
            blank
            local v
            ask v "port (-1 turns it off)" "$(health_port_of "$name")" v_hport || continue
            HEALTH_WANT=$v; cfg_apply "$name" _edit_health_port yes; pause ;;
        6) case $(toml_get "$f" transport type) in
            ws | wss) ;;
            *) blank; warn "there is nothing on 6"; pause; continue ;;
            esac
            blank
            dim "What the WebSocket handshake asks for. Anything else that"
            dim "arrives gets a 404, the way a web server would answer it."
            dim "It has to match on both servers."
            blank
            local v
            ask v "path" "$(toml_get "$f" transport path)" v_path || continue
            PATH_WANT=$v; cfg_apply "$name" _edit_path yes; pause ;;
        7) blank; sed 's/^/    /' "$f"; pause ;;
        0 | '') return 0 ;;
        esac
    done
}

_edit_mtu() { toml_set "$1" tun mtu "$MTU_WANT"; }
_edit_level() { toml_set "$1" logging level "$LEVEL_WANT"; }
_edit_queue() { toml_set "$1" tuning queue_packets "$QUEUE_WANT"; }
_edit_queues() { toml_set "$1" tun queues "$QUEUES_WANT"; }
_edit_health_port() { toml_set "$1" status health_port "$HEALTH_WANT"; }
_edit_path() { toml_set "$1" transport path "$PATH_WANT"; }

v_path() {
    case $1 in
    /*) return 0 ;;
    esac
    echo "a path starts with a slash"
    return 1
}

v_hport() {
    case $1 in
    -1) return 0 ;;
    '' | *[!0-9]*) echo "a port, or -1 to turn it off"; return 1 ;;
    esac
    { [ "$1" -ge 1 ] && [ "$1" -le 65535 ]; } || { echo "a port is between 1 and 65535"; return 1; }
}

v_level() {
    case $1 in
    debug | info | warn | error) return 0 ;;
    esac
    echo "debug, info, warn or error"
    return 1
}

v_queue() {
    case $1 in '' | *[!0-9]*) echo "a number of packets"; return 1 ;; esac
    { [ "$1" -ge 200 ] && [ "$1" -le 20000 ]; } || {
        echo "200 to 20000 - below that the queue refuses work the link could carry"
        return 1
    }
}

v_queues() {
    case $1 in '' | *[!0-9]*) echo "a number"; return 1 ;; esac
    [ "$1" -le 16 ] || { echo "0 to 16"; return 1; }
}

delete_tunnel() {
    local name=$1
    blank
    warn "this removes the tunnel $name from this server"
    dim "the other server keeps its own copy until you remove it there too"
    blank
    confirm "delete $name?" n || return 1

    svc_do stop "$name" 2>/dev/null || true
    systemctl disable "pingify@$name" >/dev/null 2>&1 || true
    nat_drop "$name" 2>/dev/null || true
    # The link underneath goes with it, and its config file with the private
    # key in it goes too.
    awg_down "$name" 2>/dev/null || true
    [ "$(toml_get "$(cfg_file "$name")" transport type)" = rawtcp ] &&
        rawtcp_unguard "$(toml_get "$(cfg_file "$name")" transport port)" 2>/dev/null
    rm -f "$(cfg_file "$name")" "$STATE_DIR/$name.forwards"
    ok "$name is gone"
    pause
    return 0
}
# --------------------------------------------------------------------------
# Ports, from the IRAN server to whatever is listening abroad.
#
# The core does not forward anything any more: it carries a private /24 and
# nothing else. This file is the whole of what stands between a user on the
# internet and a panel running on the other server.
#
# The state file is the truth and iptables is a copy of it. Every change
# writes the list under /var/lib/pingify and then rebuilds the chains from
# every tunnel's list. Nothing edits a live rule in place, so the rules cannot
# end up describing something nobody asked for - which is what happens when a
# tool adds and deletes single rules and one of the deletes quietly fails.
#
# The copy is in memory and nothing survives a reboot, so the premise needs a
# path that makes the copy again at start-up. It has one now: nat_apply_all,
# behind a oneshot unit. Without it the state files and the Ports screen went
# on listing forwarded ports after every reboot and not one of them carried a
# packet, which is the worst shape a fault can take - the machine agreeing
# with you about what it is supposed to be doing.
#
# Two faults of the old script, both named where they are fixed below. A port
# range in iptables is written with a colon, 8000:8010; the old code wrote a
# hyphen and ran it under 2>/dev/null, so every range anyone ever entered was
# accepted, stored, listed back, and never carried a packet. And five places
# parsed the port list, disagreeing about =HOST:PORT. There is one parser
# here, forward_specs, and everything goes through it.
#
# All of this is IRAN-only. KHAREJ is where the panel runs and has no ports to
# take, so the functions check the side rather than trust the caller.
# --------------------------------------------------------------------------

NAT_CHAIN=PINGIFY_NAT
NAT_POST=PINGIFY_SNAT
NAT_SYSCTL=/etc/sysctl.d/99-pingify-forward.conf
NAT_UNIT=pingify-nat.service

# Every iptables call goes through here so the lock wait cannot be forgotten.
# systemd, docker and this script can all want xtables at the same moment, and
# without -w the call fails with "another app is currently holding the xtables
# lock" - in a rebuild loop that is one rule of six missing, and nothing says
# which one.
ipt() { iptables -w 2 "$@"; }

# Keeping the kernel out of a conversation it is not part of.
#
# The raw TCP carrier builds its own segments, so the kernel has no socket for
# the port they arrive on - and its answer to a segment for a port nothing is
# listening on is an RST. That RST tears down the far end's idea of the
# conversation and tells anybody watching that nothing is there, which is the
# opposite of the point.
#
# One rule, in its own chain so it can be found and removed, and the carrier
# will not start without it.
RAWTCP_CHAIN=PINGIFY_RAWTCP

rawtcp_guard() {
    local port=$1
    ipt -t filter -N "$RAWTCP_CHAIN" 2>/dev/null
    ipt -C OUTPUT -j "$RAWTCP_CHAIN" 2>/dev/null ||
        ipt -I OUTPUT 1 -j "$RAWTCP_CHAIN" || return 1
    ipt -C "$RAWTCP_CHAIN" -p tcp --sport "$port" --tcp-flags RST RST -j DROP 2>/dev/null ||
        ipt -A "$RAWTCP_CHAIN" -p tcp --sport "$port" --tcp-flags RST RST -j DROP || return 1
    return 0
}

rawtcp_unguard() {
    local port=$1
    ipt -D "$RAWTCP_CHAIN" -p tcp --sport "$port" --tcp-flags RST RST -j DROP 2>/dev/null
    # The chain goes when the last tunnel using it does.
    if [ "$(ipt -S "$RAWTCP_CHAIN" 2>/dev/null | wc -l)" -le 1 ]; then
        ipt -D OUTPUT -j "$RAWTCP_CHAIN" 2>/dev/null
        ipt -X "$RAWTCP_CHAIN" 2>/dev/null
    fi
    return 0
}

# Rejections are plain, unmarked, and on stderr. Plain because `ask` puts its
# own mark in front of whatever a validator says, and two marks on one line
# read as two problems. On stderr because stdout carries the tuples, and a
# caller capturing those must not capture the complaints with them.
fwd_no() { printf '  %s: %s\n' "$1" "$2" >&2; }

# Where a tunnel's list is kept. This name is the file's own business: another
# part that spells the path out for itself is a second definition, and the
# health check had one - it read "$STATE_DIR/$1.ports", never found a file, and
# reported "no ports are forwarded" about a tunnel forwarding six of them.
# Read the list with forwards_of, or the parsed tuples with forward_specs_for.
fwd_file() { printf '%s/%s.forwards' "$STATE_DIR" "$1"; }

fwd_range() {
    if [ "$1" = "$2" ]; then printf '%s' "$1"; else printf '%s-%s' "$1" "$2"; fi
}

# Do lo1..hi1 and lo2..hi2 share a port.
fwd_overlap() { [ "$1" -le "$4" ] && [ "$3" -le "$2" ]; }

# fwd_tokens splits a list the way somebody writes one: commas, spaces or
# both, in one argument or several. The unquoted expansion here is the only
# one in the file, and the IFS above it is the entire reason for it.
fwd_tokens() {
    local arg tok
    local IFS=$', \t\n'
    for arg in "$@"; do
        for tok in $arg; do printf '%s\n' "$tok"; done
    done
}

fwd_port_ok() {
    case $2 in
    '') fwd_no "$1" "there is no port number in it"; return 1 ;;
    *[!0-9]*) fwd_no "$1" "$2 is not a number, and a port is a number"; return 1 ;;
    esac
    [ "$2" -ge 1 ] && [ "$2" -le 65535 ] && return 0
    fwd_no "$1" "$2 is not a port - they run from 1 to 65535"
    return 1
}

# --------------------------------------------------------------------------
# the one parser
# --------------------------------------------------------------------------
#
#   443                 tcp 443, straight across
#   udp:500             udp instead
#   443=8443            arrives on 443, delivered to 8443
#   8000-8010           a range, delivered on the same ports
#   443=10.99.10.5:443  delivered to a particular machine behind the far end
#
# Prints one tuple per line: "proto lo hi dsthost dstport". dsthost is `-`
# when the token did not name one, meaning the far end of this tunnel: the
# parser is given specs and not a tunnel, so it has nothing to resolve that
# against and does not pretend to. nat_rules_for fills it in.
#
# tcp is the default because udp: exists - if a bare port meant both, nobody
# would ever need to write the prefix.
#
# Nothing is printed unless every token is good. A half applied list is worse
# than none: the ports that did work make the ones that did not look like
# somebody else's fault.
forward_specs() {
    local tok spec dest proto lo hi dsth dstp herr wide dup i refused=0
    local -a out=() sp=() slo=() shi=()

    while read -r tok; do
        [ -n "$tok" ] || continue
        case $tok in
        *=) fwd_no "$tok" "there is nothing after the ="; refused=$((refused + 1)); continue ;;
        esac

        spec=$tok dest= proto=tcp
        case $spec in *=*) dest=${spec#*=}; spec=${spec%%=*} ;; esac
        case $spec in *:*) proto=${spec%%:*}; spec=${spec#*:} ;; esac
        case $proto in
        tcp | TCP) proto=tcp ;;
        udp | UDP) proto=udp ;;
        *) fwd_no "$tok" "iptables forwards tcp and udp; $proto is neither"
           refused=$((refused + 1)); continue ;;
        esac

        case $spec in
        *-*) lo=${spec%%-*}; hi=${spec#*-} ;;
        *) lo=$spec; hi=$spec ;;
        esac
        fwd_port_ok "$tok" "$lo" || { refused=$((refused + 1)); continue; }
        fwd_port_ok "$tok" "$hi" || { refused=$((refused + 1)); continue; }
        if [ "$lo" -gt "$hi" ]; then
            fwd_no "$tok" "the range runs backwards - $lo comes after $hi"
            refused=$((refused + 1)); continue
        fi
        # 512 is not a technical limit. It is the width at which a typo stops
        # looking like a range: 1-9999 is somebody who meant 1999, and opening
        # ten thousand ports on their behalf is not a favour.
        wide=$((hi - lo + 1))
        if [ "$wide" -gt 512 ]; then
            fwd_no "$tok" "that is $wide ports; the most in one range is 512"
            refused=$((refused + 1)); continue
        fi

        dsth=- dstp=$lo
        if [ -n "$dest" ]; then
            case $dest in
            *:*) dsth=${dest%:*}; dstp=${dest##*:} ;;
            *[!0-9]*) dsth=$dest ;;
            *) dstp=$dest ;;
            esac
            # v_host already knows what an address is and already has the
            # wording for what it is not. A second opinion here would in time
            # become a different opinion.
            if [ "$dsth" != - ] && ! herr=$(v_host "$dsth" 2>&1); then
                fwd_no "$tok" "$herr"
                refused=$((refused + 1)); continue
            fi
            fwd_port_ok "$tok" "$dstp" || { refused=$((refused + 1)); continue; }
            if [ "$lo" != "$hi" ] && [ "$dstp" != "$lo" ]; then
                # Kept short on purpose. fwd_no prints with a bare printf and
                # nothing on this path truncates, so a sentence of advice here
                # wrapped past a hundred columns on a sixty column terminal.
                fwd_no "$tok" "a range cannot go to one port"
                refused=$((refused + 1)); continue
            fi
        fi

        # The same port twice is a list somebody is still editing. Better said
        # here than left as two iptables rules, the second of which is dead
        # weight nobody can see.
        dup=0
        for ((i = 0; i < ${#sp[@]}; i++)); do
            [ "${sp[i]}" = "$proto" ] || continue
            fwd_overlap "$lo" "$hi" "${slo[i]}" "${shi[i]}" || continue
            fwd_no "$tok" "this list already has $proto $(fwd_range "${slo[i]}" "${shi[i]}") in it"
            refused=$((refused + 1)) dup=1
            break
        done
        [ "$dup" = 1 ] && continue

        sp+=("$proto") slo+=("$lo") shi+=("$hi")
        out+=("$proto $lo $hi $dsth $dstp")
    done < <(fwd_tokens "$@")

    [ "$refused" -gt 0 ] && return 1
    [ "${#out[@]}" -gt 0 ] && printf '%s\n' "${out[@]}"
    return 0
}

# --------------------------------------------------------------------------
# what a tunnel forwards, and what would collide with it
# --------------------------------------------------------------------------

# The state file holds the tokens as they were typed, one per line, not the
# parsed tuples: that is what the ports screen shows back, and what somebody
# reading /var/lib/pingify by hand expects to find.
forwards_of() {
    local f
    f=$(fwd_file "$1")
    [ -f "$f" ] || return 0
    cat "$f"
}

forwards_set() {
    local name=$1 f
    shift
    forward_specs "$@" >/dev/null || return 1
    ensure_dirs
    f=$(fwd_file "$name")
    fwd_tokens "$@" >"$f" || return 1
    chmod 0600 "$f"
}

peer_tun_addr() {
    local f a
    f=$(cfg_file "$1")
    [ -f "$f" ] || return 0
    a=$(toml_get "$f" tun kharej)
    printf '%s' "${a%%/*}"
}

# tun_dev_of prints nothing once the config has gone rather than guessing
# pfy0. The guess would be used to delete a firewall rule, and deleting one
# that belongs to another tunnel is worse than leaving one behind.
tun_dev_of() {
    local f d
    f=$(cfg_file "$1")
    [ -f "$f" ] || return 0
    d=$(toml_get "$f" tun name)
    printf '%s' "${d:-pfy0}"
}

# forward_specs_for is the parser bound to a tunnel: the same tuples, with the
# `-` in the dsthost column already replaced by that tunnel's far end.
#
# It exists because the placeholder was escaping. forward_specs is handed
# specs and not a tunnel, so it cannot resolve `-` itself and does not pretend
# to; the health check took the tuples straight from it and probed the literal
# host `-`, which cannot answer, so every plain `443` forward was reported as
# a dead backend. Anything outside this file that wants a tunnel's tuples
# wants these, and it should ask for them by tunnel name rather than spell out
# where the state file lives.
forward_specs_for() {
    local name=$1 peer tuples proto lo hi dsth dstp
    tuples=$(forward_specs "$(forwards_of "$name")") || return 1
    [ -n "$tuples" ] || return 0
    peer=$(peer_tun_addr "$name")
    while read -r proto lo hi dsth dstp; do
        [ -n "$proto" ] || continue
        if [ "$dsth" = - ]; then
            # No address for the far end and a token that needs one. Printing
            # the tuple anyway would hand an empty host to whatever consumes
            # it, and an empty host in a DNAT target is a rule iptables takes.
            [ -n "$peer" ] || return 1
            dsth=$peer
        fi
        printf '%s %s %s %s %s\n' "$proto" "$lo" "$hi" "$dsth" "$dstp"
    done <<<"$tuples"
}

# fwd_listeners prints "proto port who" for everything bound on this host.
#
# Loopback-only listeners are left out on purpose: PREROUTING takes the packet
# long before it reaches 127.0.0.1, so such a service never saw the outside
# traffic and calling it a clash is a false alarm - and false alarms are how
# people learn to ignore a collision check.
#
# The whole of 127.0.0.0/8 is loopback, not the one address. Matching only
# 127.0.0.1 meant systemd-resolved on 127.0.0.53:53 was reported as a clash on
# every Ubuntu host, which is precisely the false alarm this filter exists to
# prevent.
fwd_listeners() {
    have ss || return 0
    ss -lntup 2>/dev/null | awk '
        NR > 1 {
            addr = $5
            n = split(addr, p, ":")
            port = p[n]
            host = substr(addr, 1, length(addr) - length(port) - 1)
            if (host ~ /^127\./ || host == "[::1]") next
            who = "something"
            i = index($0, "users:((\"")
            if (i > 0) {
                rest = substr($0, i + 9)
                q = index(rest, "\"")
                if (q > 1) who = substr(rest, 1, q - 1)
            }
            print $1, port, who
        }'
}

# forwards_clash prints every clash it can find, one per line, and returns
# non-zero when there was one. Every clash, not the first: somebody given one
# reason at a time will fix it, be handed a new one, and reasonably decide the
# tool is playing with them.
#
# Two sources. Another tunnel's forwards, this tunnel's own excluded so that
# re-submitting an unchanged list is not a clash with itself. And whatever is
# bound here per ss, because a DNAT in PREROUTING takes the packet before the
# local service sees it, which looks from that service exactly like the port
# going dead for no reason.
forwards_clash() {
    local name=$1
    shift
    local tuples listeners proto lo hi dsth dstp other op olo ohi oport who
    local hits=0

    tuples=$(forward_specs "$@") || return 1
    [ -n "$tuples" ] || return 0
    listeners=$(fwd_listeners)

    # A tunnel whose stored list no longer parses contributes no tuples, and
    # the parse ran under 2>/dev/null inside a process substitution, so both
    # its complaint and its exit status went into the dark. The port it is
    # holding was then handed out as free. Said once per tunnel, here, rather
    # than once per port being checked.
    while read -r other; do
        [ -n "$other" ] || continue
        [ "$other" = "$name" ] && continue
        forward_specs "$(forwards_of "$other")" >/dev/null 2>&1 && continue
        printf '%s: its list cannot be read\n' "$other"
        hits=$((hits + 1))
    done < <(cfg_list)

    while read -r proto lo hi dsth dstp; do
        [ -n "$proto" ] || continue
        while read -r other; do
            [ -n "$other" ] || continue
            [ "$other" = "$name" ] && continue
            while read -r op olo ohi _ _; do
                [ -n "$op" ] || continue
                [ "$op" = "$proto" ] || continue
                fwd_overlap "$lo" "$hi" "$olo" "$ohi" || continue
                printf '%s %s is already forwarded by the tunnel %s\n' \
                    "$op" "$(fwd_range "$olo" "$ohi")" "$other"
                hits=$((hits + 1))
            done < <(forward_specs "$(forwards_of "$other")" 2>/dev/null)
        done < <(cfg_list)
        while read -r op oport who; do
            [ -n "$op" ] || continue
            [ "$op" = "$proto" ] || continue
            fwd_overlap "$lo" "$hi" "$oport" "$oport" || continue
            printf '%s %s is already open here, held by %s\n' "$op" "$oport" "$who"
            hits=$((hits + 1))
        done <<<"$listeners"
    done <<<"$tuples"

    [ "$hits" = 0 ]
}

# The reasons are joined onto one line because `ask` prints a validator's
# answer as one line. The full list, one per line, is what forward_specs
# prints when the screen calls it directly.
v_forwards() {
    local err
    # Empty is a legal answer. It is how somebody says "none of them".
    [ -z "$1" ] && return 0
    if err=$(forward_specs "$1" 2>&1 >/dev/null); then return 0; fi
    printf '%s' "$err" | tr '\n' ';'
    return 1
}

# --------------------------------------------------------------------------
# turning the state into iptables
# --------------------------------------------------------------------------
#
# Two chains, and not for tidiness. DNAT is only valid on the PREROUTING hook
# and MASQUERADE only on POSTROUTING, and the kernel works out which hooks a
# user chain is reachable from when the jump is added - so one chain hooked
# into both is refused outright, and one chain hooked into either cannot hold
# the other's rule.

nat_hook() {
    local chain=$1 target=$2
    ipt -t nat -C "$chain" -j "$target" 2>/dev/null && return 0
    ipt -t nat -I "$chain" 1 -j "$target"
}

# The FORWARD accepts are two plain rules rather than a chain of our own: the
# host part owns Pingify's filter chains, and two owners flushing one chain is
# how each loses the other's work. They matter, because on any machine that
# has run docker the FORWARD policy is DROP, and without them the DNAT
# succeeds and the packet dies one hop later - indistinguishable, from the
# outside, from the far end being down.
nat_forward_hook() {
    local how=$1 dev=$2
    local -a back=(-i "$dev" -m conntrack --ctstate ESTABLISHED,RELATED -j ACCEPT)
    [ -n "$dev" ] || return 0
    case $how in
    add)
        ipt -C FORWARD -o "$dev" -j ACCEPT 2>/dev/null ||
            ipt -I FORWARD 1 -o "$dev" -j ACCEPT || return 1
        # Only replies come back the other way. The far end is not a route to
        # the rest of the internet through this server.
        ipt -C FORWARD "${back[@]}" 2>/dev/null ||
            ipt -I FORWARD 1 "${back[@]}" || return 1
        ;;
    del)
        while ipt -C FORWARD -o "$dev" -j ACCEPT 2>/dev/null; do
            ipt -D FORWARD -o "$dev" -j ACCEPT || break
        done
        while ipt -C FORWARD "${back[@]}" 2>/dev/null; do
            ipt -D FORWARD "${back[@]}" || break
        done
        ;;
    esac
}

# An owned drop-in, so that removing Pingify removes Pingify's change to this
# machine and nobody else's.
nat_ip_forward() {
    local now
    mkdir -p /etc/sysctl.d 2>/dev/null
    if [ ! -s "$NAT_SYSCTL" ]; then
        cat >"$NAT_SYSCTL" <<'SYSCTL'
# Written by Pingify. A forwarded port is a packet that arrives for one
# address and leaves for another, and the kernel drops that unless this is on.
net.ipv4.ip_forward = 1
SYSCTL
    fi
    sysctl -q -w net.ipv4.ip_forward=1 >/dev/null 2>&1 ||
        printf '1\n' >/proc/sys/net/ipv4/ip_forward 2>/dev/null
    now=$(cat /proc/sys/net/ipv4/ip_forward 2>/dev/null)
    [ "$now" = 1 ] && return 0
    bad "the kernel is not forwarding packets, so nothing arrives"
    fix "sysctl -w net.ipv4.ip_forward=1"
    return 1
}

# nat_rules_for appends one tunnel's rules to the already flushed chains. A
# tunnel whose stored list no longer parses is skipped with a complaint rather
# than aborting the rebuild: the rebuild is doing the other tunnels' work too,
# and one bad state file must not take their ports down with it.
nat_rules_for() {
    local name=$1 f side dev tuples proto lo hi dsth dstp dport target
    f=$(cfg_file "$name")
    [ -f "$f" ] || return 0
    side=$(toml_get "$f" tunnel side)
    [ "$side" = iran ] || return 0

    # forward_specs_for resolves the `-` placeholder against this tunnel, so
    # it also fails when a token needs the far end and the config names none.
    tuples=$(forward_specs_for "$name") || return 1
    [ -n "$tuples" ] || return 0
    dev=$(tun_dev_of "$name")
    [ -n "$dev" ] || return 1

    while read -r proto lo hi dsth dstp; do
        [ -n "$proto" ] || continue
        if [ "$lo" = "$hi" ]; then
            dport=$lo target=$dsth:$dstp
        else
            # The colon. iptables writes a range as 8000:8010 and refuses a
            # hyphen; the old script wrote the hyphen and threw the refusal
            # away, so ranges were stored, listed back, and never forwarded.
            # A range keeps its own ports, so the target names none.
            dport=$lo:$hi target=$dsth
        fi
        # Not packets arriving out of the tunnel: without this, a connection
        # made from the far end to this port is sent straight back out again.
        ipt -t nat -A "$NAT_CHAIN" ! -i "$dev" -p "$proto" --dport "$dport" \
            -j DNAT --to-destination "$target" || return 1
    done <<<"$tuples"

    # One MASQUERADE for the device, so the far end sees the traffic coming
    # from this end of the private link and answers back down it. Without it
    # the reply is addressed to the original client and leaves through the far
    # server's own default route, where it is dropped as a stranger.
    ipt -t nat -A "$NAT_POST" -o "$dev" -j MASQUERADE || return 1
    nat_forward_hook add "$dev"
}

# nat_rebuild writes every tunnel's stored list into the freshly flushed
# chains. Everything, because the chains are shared: flushing them to write one
# tunnel's rules and not writing the others back is how a second tunnel
# silently loses its ports.
#
# The argument is the tunnel the caller is about to report on, or empty to mean
# every tunnel matters. It returns non-zero when that tunnel's rules did not go
# in. This used to be inside nat_apply, which threw the result away: a DNAT the
# kernel refused, or a config with no device or no far end, was warned about
# and then reported as a success on the very next line, with a count read from
# the state file rather than from what iptables had accepted.
nat_rebuild() {
    local want=$1 t dev rc=0
    have iptables || {
        warn "iptables is not installed, so nothing can be forwarded"
        fix "apt-get install -y iptables"
        return 1
    }
    ensure_dirs
    nat_ip_forward || return 1

    ipt -t nat -n -L "$NAT_CHAIN" >/dev/null 2>&1 || ipt -t nat -N "$NAT_CHAIN" || return 1
    ipt -t nat -n -L "$NAT_POST" >/dev/null 2>&1 || ipt -t nat -N "$NAT_POST" || return 1
    ipt -t nat -F "$NAT_CHAIN" || return 1
    ipt -t nat -F "$NAT_POST" || return 1
    nat_hook PREROUTING "$NAT_CHAIN" || return 1
    nat_hook POSTROUTING "$NAT_POST" || return 1

    while read -r t; do
        [ -n "$t" ] || continue
        # A tunnel that has stopped forwarding kept its FORWARD accepts:
        # nat_rules_for returns before it adds them and nothing ever took them
        # away again, so `-o pfy0 -j ACCEPT` sat there permitting that device
        # with no DNAT left behind it. The nat chains are flushed above; these
        # two rules live in filter and have to be removed by name.
        if [ -z "$(forwards_of "$t")" ]; then
            dev=$(tun_dev_of "$t")
            nat_forward_hook del "$dev"
            continue
        fi
        nat_rules_for "$t" && continue
        warn "$t: its stored ports could not be applied"
        if [ -z "$want" ] || [ "$t" = "$want" ]; then rc=1; fi
    done < <(cfg_list)
    return "$rc"
}

# nat_apply rebuilds everything, then reports on the one tunnel it was called
# for. The report is the outcome, not a wish: it is only printed when the
# rebuild said that tunnel's rules went in.
nat_apply() {
    local name=$1 n peer word
    nat_rebuild "$name" || {
        bad "$name: its ports are not forwarded"
        fix "read the warnings above, then set the list again"
        return 1
    }
    nat_unit_write || {
        warn "the boot unit is not written, so a reboot loses these"
        fix "check that $UNIT_DIR can be written"
    }

    n=$(forwards_of "$name" | grep -c .) || n=0
    peer=$(peer_tun_addr "$name")
    word=ports
    [ "$n" = 1 ] && word=port
    if [ "$n" = 0 ]; then
        ok "$name forwards nothing now"
    elif [ -n "$peer" ]; then
        ok "$name sends $n $word to $peer"
    else
        # Every token named its own destination, so there is no far end to
        # name here. The old line ended "to " with nothing after it.
        ok "$name sends $n $word across the tunnel"
    fi
    return 0
}

# nat_apply_all is the boot path, and the reason the unit below exists.
#
# iptables keeps its rules in memory alone. Nothing replayed them at start-up,
# so every forwarded port died at the first reboot while the state files and
# the Ports screen went on saying the ports were forwarded - the one failure
# with no symptom anywhere on the machine except that no packet arrives.
nat_apply_all() {
    [ "$(cfg_count)" -gt 0 ] || return 0
    nat_rebuild "" || return 1
    ok "the forwarded ports are back in the kernel"
}

# The unit re-enters this same script rather than repeating the rules, so the
# boot path cannot drift from the interactive one. It sources the manager with
# PINGIFY_NO_MAIN set, which is what stops a sourced copy opening the menu, and
# calls the one function - there is no command line flag for this and adding
# one would put a second entry point on the same work.
nat_unit_write() {
    mkdir -p "$UNIT_DIR" 2>/dev/null
    # The write is checked. A unit that was never written is the reboot fault
    # again, and it would be reported under the same green tick as before.
    cat >"$UNIT_DIR/$NAT_UNIT" <<UNIT || return 1
[Unit]
Description=Pingify forwarded ports
After=network-online.target
Wants=network-online.target

[Service]
Type=oneshot
RemainAfterExit=yes
ExecStart=/bin/bash -c 'PINGIFY_NO_MAIN=1 . $PINGIFY_BIN && nat_apply_all'

[Install]
WantedBy=multi-user.target
UNIT
    systemctl daemon-reload >/dev/null 2>&1 || true
    systemctl enable "$NAT_UNIT" >/dev/null 2>&1 || true
}

# nat_drop removes one tunnel's forwarding. Call it before the config file is
# deleted: the tun device name comes out of the config, and without it the
# FORWARD rules for that device can never be found again.
nat_drop() {
    local name=$1 dev t left=0
    rm -f "$(fwd_file "$name")"
    # The state file has gone either way, so say so. Returning in silence here
    # left the menu item printing nothing at all after the confirmation, which
    # reads as a key that did not work.
    have iptables || { ok "$name forwards nothing now"; return 0; }
    dev=$(tun_dev_of "$name")
    nat_forward_hook del "$dev"

    while read -r t; do
        [ -n "$t" ] || continue
        [ -s "$(fwd_file "$t")" ] && left=1
    done < <(cfg_list)

    if [ "$left" = 1 ]; then
        nat_apply "$name"
        return
    fi
    nat_teardown
    ok "$name forwards nothing, and the chains have gone with it"
}

# nat_teardown is what the last tunnel and the uninstall both call. The loops
# around the unhooking are there because an older version inserted the jump on
# every run: a single -D would leave the duplicates pointing at a chain that
# is about to be deleted.
nat_teardown() {
    # The boot unit goes first and always, iptables or not: a unit left behind
    # would replay chains at the next reboot that nothing on this machine now
    # asks for.
    systemctl disable --now "$NAT_UNIT" >/dev/null 2>&1 || true
    rm -f "$UNIT_DIR/$NAT_UNIT"
    systemctl daemon-reload >/dev/null 2>&1 || true

    have iptables || return 0
    while ipt -t nat -C PREROUTING -j "$NAT_CHAIN" 2>/dev/null; do
        ipt -t nat -D PREROUTING -j "$NAT_CHAIN" || break
    done
    while ipt -t nat -C POSTROUTING -j "$NAT_POST" 2>/dev/null; do
        ipt -t nat -D POSTROUTING -j "$NAT_POST" || break
    done
    ipt -t nat -F "$NAT_CHAIN" 2>/dev/null
    ipt -t nat -X "$NAT_CHAIN" 2>/dev/null
    ipt -t nat -F "$NAT_POST" 2>/dev/null
    ipt -t nat -X "$NAT_POST" 2>/dev/null
    # The drop-in goes, so a reboot comes up without it. The running kernel
    # keeps ip_forward=1 until then, deliberately: something else here may be
    # relying on it and it was not ours to switch off.
    rm -f "$NAT_SYSCTL"
    return 0
}

# --------------------------------------------------------------------------
# the screen
# --------------------------------------------------------------------------

screen_ports() {
    local name=$1 f side peer cur tuples proto lo hi dsth dstp key
    f=$(cfg_file "$name")
    [ -f "$f" ] || { bad "there is no tunnel called $name"; return 1; }
    screen_top

    while :; do
        side=$(toml_get "$f" tunnel side)
        blank
        rule "Ports $G_CUR $name"
        blank
        if [ "$side" != iran ]; then
            warn "this is the KHAREJ side; nothing is forwarded here"
            fix "run this on the IRAN server, where users connect"
            blank
            return 0
        fi

        peer=$(peer_tun_addr "$name")
        # Short because dim prints with a bare printf: the sentence this
        # replaces came to 72 columns against a 60 column floor and wrapped.
        dim "these ports go to $peer across the tunnel"
        blank
        cur=$(forwards_of "$name" | tr '\n' ' ')
        cur=${cur% }
        if [ -z "$cur" ]; then
            dim "nothing is forwarded yet"
        elif ! tuples=$(forward_specs "$cur"); then
            warn "the stored list cannot be read, so nothing is forwarded"
            fix "choose 1 and enter the ports again"
        else
            UI_COLS=(14 7 30)
            row "PORT" "PROTO" "GOES TO"
            while read -r proto lo hi dsth dstp; do
                [ -n "$proto" ] || continue
                [ "$dsth" = - ] && dsth=$peer
                if [ "$lo" = "$hi" ]; then
                    row "$lo" "$proto" "$dsth:$dstp"
                else
                    row "$lo-$hi" "$proto" "$dsth, the same ports"
                fi
            done <<<"$tuples"
        fi

        blank
        item "1" "Set the list"
        item "2" "Forward nothing"
        item "0" "Back"
        blank
        menu_key key || return 0
        case $key in
        1) screen_ports_set "$name" ;;
        2) confirm "stop forwarding every port for $name?" n && nat_drop "$name" ;;
        0 | '') return 0 ;;
        esac
    done
}

screen_ports_set() {
    local name=$1 cur answer clashes
    cur=$(forwards_of "$name" | tr '\n' ' ')
    cur=${cur% }
    blank
    dim "one port  443     a range  8000-8010     udp  udp:500"
    dim "somewhere else  443=8443  or  443=10.99.10.5:443"
    blank
    # The clash report is a re-ask, not a refusal: the answer is still on the
    # screen above and the next one is usually one character different.
    while :; do
        ask answer "ports, comma separated" "$cur" v_forwards || return 0
        clashes=$(forwards_clash "$name" "$answer") && break
        blank
        bad "something else already has one of those:"
        printf '%s\n' "$clashes" | sed 's/^/       /'
        fix "pick other ports, or stop what is holding these"
        blank
    done
    forwards_set "$name" "$answer" || return 1
    nat_apply "$name"
}
#!/usr/bin/env bash
#
# Diagnostics: the screens you open when something is wrong, and the two
# measurements worth taking when nothing is.
#
# Four decisions shape this whole part.
#
#   Every failure carries a fix. A health check that lists problems and stops
#   is a list of reasons to be worried with no way to stop being worried. That
#   was the old check's one good idea, and it is kept without its 320 lines.
#
#   Grey is a verdict. Red means "this is broken", never "this could not be
#   measured". An ICMP tunnel switches off echo replies on both servers while
#   it runs, so a ping across it is answered by nobody - the design working,
#   not the link failing. The old manager drew that in red and told a healthy
#   tunnel it was dead. Here it is one grey line.
#
#   Status comes from the core, never from its prose. `tun_stats` reads the
#   JSON the core serves on loopback. The old manager took the eighth field of
#   an English sentence out of the journal with awk, and broke the day somebody
#   reworded the sentence.
#
#   Every message fits in sixty columns, which is UI_W's floor. None of
#   ok/warn/bad/fix/dim truncates - they carry prose, and prose that overruns
#   wraps and destroys the indentation that carries the meaning. The budgets
#   are 54 characters for a verdict, 46 for a fix, 56 for a grey note.

# --------------------------------------------------------------------------
# collecting a verdict
# --------------------------------------------------------------------------
#
# health_check buffers its result rather than printing as it goes, so the text
# screen and --json are one pass rendered twice. Two passes would eventually
# disagree, and the one a script reads is the one nobody looks at.

CHK_STATE=() CHK_ID=() CHK_TEXT=() CHK_FIX=()
CHK_NBAD=0 CHK_NWARN=0

chk_reset() {
    CHK_STATE=() CHK_ID=() CHK_TEXT=() CHK_FIX=()
    CHK_NBAD=0 CHK_NWARN=0
}

# chk_add STATE ID TEXT [FIX...]
#
# STATE is ok, warn, bad or note. note is the grey one: something worth saying
# that is not a fault, and it is never counted as one. Every warn and every bad
# passes at least one fix; nothing else passes any.
chk_add() {
    local state=$1 id=$2 text=$3 joined= one
    shift 3
    for one in "$@"; do joined=$joined$one$'\n'; done
    CHK_STATE+=("$state")
    CHK_ID+=("$id")
    CHK_TEXT+=("$text")
    CHK_FIX+=("$joined")
    case $state in
    bad) CHK_NBAD=$((CHK_NBAD + 1)) ;;
    warn) CHK_NWARN=$((CHK_NWARN + 1)) ;;
    esac
}

# count_word turns a small number into the word for it. "one problem" reads;
# "1 problem(s)" is a form to be filled in.
count_word() {
    case $1 in
    1) printf 'one' ;; 2) printf 'two' ;; 3) printf 'three' ;;
    *) printf '%s' "$1" ;;
    esac
}

# plural_s prints the s, or nothing, inline, so a count and its noun cannot
# drift apart in an edit.
plural_s() { [ "$1" = 1 ] || printf 's'; }

chk_tally() {
    local out=
    [ "$CHK_NBAD" = 0 ] && [ "$CHK_NWARN" = 0 ] &&
        { printf 'nothing wrong here'; return; }
    [ "$CHK_NBAD" -gt 0 ] &&
        out="$(count_word "$CHK_NBAD") problem$(plural_s "$CHK_NBAD")"
    if [ "$CHK_NWARN" -gt 0 ]; then
        [ -n "$out" ] && out="$out, "
        out="$out$(count_word "$CHK_NWARN") warning$(plural_s "$CHK_NWARN")"
    fi
    printf '%s' "$out"
}

chk_render() {
    local name=$1 i line
    blank
    rule "Health of $name"
    blank
    for ((i = 0; i < ${#CHK_ID[@]}; i++)); do
        case ${CHK_STATE[i]} in
        ok) ok "${CHK_TEXT[i]}" ;;
        warn) warn "${CHK_TEXT[i]}" ;;
        bad) bad "${CHK_TEXT[i]}" ;;
        # ok/warn/bad each spend two columns on a glyph before their text. A
        # grey note has no glyph, so it is padded into the same column; without
        # that it sits two to the left and reads as a different list.
        *) dim "  ${CHK_TEXT[i]}" ;;
        esac
        if [ -n "${CHK_FIX[i]}" ]; then
            while IFS= read -r line; do
                [ -n "$line" ] && fix "$line"
            done <<<"${CHK_FIX[i]}"
        fi
    done
    blank
    dim "$(chk_tally)"
    blank
}

# json_esc covers what can actually appear in these strings: backslashes,
# quotes and tabs. Nothing here builds a check line out of text with a newline
# in it - the one place that could, the core's own refusal, is cut to its first
# line before it gets here.
json_esc() {
    local s=$1
    s=${s//\\/\\\\}
    s=${s//\"/\\\"}
    s=${s//$'\t'/ }
    printf '%s' "$s"
}

chk_json() {
    local name=$1 i last first line
    last=$((${#CHK_ID[@]} - 1))
    printf '{\n'
    printf '  "tunnel": "%s",\n' "$(json_esc "$name")"
    printf '  "problems": %s,\n' "$CHK_NBAD"
    printf '  "warnings": %s,\n' "$CHK_NWARN"
    printf '  "checks": [\n'
    for ((i = 0; i <= last; i++)); do
        printf '    {"id": "%s", "state": "%s", "text": "%s", "fixes": [' \
            "$(json_esc "${CHK_ID[i]}")" "${CHK_STATE[i]}" \
            "$(json_esc "${CHK_TEXT[i]}")"
        first=1
        if [ -n "${CHK_FIX[i]}" ]; then
            while IFS= read -r line; do
                [ -n "$line" ] || continue
                [ "$first" = 1 ] || printf ', '
                printf '"%s"' "$(json_esc "$line")"
                first=0
            done <<<"${CHK_FIX[i]}"
        fi
        printf ']}'
        [ "$i" -lt "$last" ] && printf ','
        printf '\n'
    done
    printf '  ]\n}\n'
}

# --------------------------------------------------------------------------
# reading a tunnel's own idea of itself
# --------------------------------------------------------------------------
#
# Eight values every screen here needs, read once into CK_* globals. Reading
# them per screen meant eight awk passes over one file and, in the old script,
# two of the readers disagreed about which side we were on.

chk_load() {
    local name=$1
    CK_FILE=$(cfg_file "$name")
    [ -f "$CK_FILE" ] || return 1
    CK_SIDE=$(toml_get "$CK_FILE" tunnel side)
    CK_TRANSPORT=$(toml_get "$CK_FILE" transport type)
    CK_PORT=$(toml_get "$CK_FILE" transport port)
    CK_KHAREJ=$(toml_get "$CK_FILE" transport kharej)
    CK_DEV=$(toml_get "$CK_FILE" tun name)
    CK_MTU=$(toml_get "$CK_FILE" tun mtu)
    # The core fills these in when the file leaves them out, so the manager has
    # to agree with it or it reports a mismatch that is not one.
    [ -n "$CK_TRANSPORT" ] || CK_TRANSPORT=udp
    [ -n "$CK_DEV" ] || CK_DEV=pfy0
    [ -n "$CK_MTU" ] || CK_MTU=1320
    if [ "$CK_SIDE" = iran ]; then
        CK_MINE=$(toml_get "$CK_FILE" tun iran)
        CK_THEIRS=$(toml_get "$CK_FILE" tun kharej)
    else
        CK_MINE=$(toml_get "$CK_FILE" tun kharej)
        CK_THEIRS=$(toml_get "$CK_FILE" tun iran)
    fi
    CK_PEER=${CK_THEIRS%%/*}
    return 0
}

# link_rtt pings the other end of the private link and prints the round trip in
# milliseconds. It is bound to the tun device, so the answer is the tunnel's
# latency and not the carrier's. Prints nothing and returns 1 when no reply
# comes, which on an ICMP tunnel is always - see the note in health_check.
link_rtt() {
    local dev=$1 peer=$2 out
    out=$(ping -n -c1 -W1 -I "$dev" "$peer" 2>/dev/null) || return 1
    case $out in
    *time=*) out=${out#*time=}; printf '%s' "${out%% *}" ;;
    *) return 1 ;;
    esac
}

# tcp_reach says whether something accepts a connection at HOST:PORT. bash's
# own /dev/tcp is tried first because it is always there and needs no package;
# nc is the fallback for the builds that compile it out.
tcp_reach() {
    local host=$1 port=$2
    if timeout 2 bash -c "exec 3<>/dev/tcp/$host/$port" 2>/dev/null; then
        return 0
    fi
    have nc && nc -z -w2 "$host" "$port" >/dev/null 2>&1
}

# The forwarding part owns the port spec and where it is kept; this only reads
# it. When forwarding was never set up the check says nothing about ports
# rather than inventing a failure out of an absent file.
#
# The path comes from fwd_file rather than being spelled out a second time
# here. It used to read $STATE_DIR/$1.ports, a name nothing has ever written -
# the forwarding part writes $1.forwards - so the file was never found, section
# 7 always took the absent-file branch, and a server forwarding six ports was
# told in grey that it forwards none, with any dead backend behind them never
# reported at all.
chk_forward_spec() {
    local f
    declare -F fwd_file >/dev/null 2>&1 || return 1
    f=$(fwd_file "$1")
    [ -f "$f" ] || return 1
    # The tokens are stored one per line. Deleting the newlines glued 443 and
    # 8080 into 4438080, forward_specs refused that as one impossible port, and
    # the check told the user to set the list again about a list that was fine.
    # fwd_tokens splits on newlines as readily as on commas, so the file is
    # passed on as it stands.
    cat "$f"
}

# --------------------------------------------------------------------------
# health_check
# --------------------------------------------------------------------------
#
# One pass, in the order things fail. A check whose evidence is missing says so
# in grey and does not guess: with no core installed there is no verdict to
# give about whether it accepts the config, and giving one anyway is how a
# health report comes to be ignored. Exit 0 clean, 1 warnings, 2 problems, so
# `pingify --check NAME` is usable from cron; the old one ended in `pause`.

health_check() {
    local name=$1 mode=${2:-}
    local core_ver out st since addr fl live_mtu lpm heard cc
    local spec proto lo hi rhost rport total missing unknown

    chk_reset
    if ! chk_load "$name"; then
        chk_add bad config "there is no tunnel called $name" \
            "run pingify with no arguments to see the list"
        chk_finish "$name" "$mode"
        return 2
    fi

    # 1. the core itself. Everything below is a question about what the core is
    # doing, so a missing core makes the rest unanswerable rather than failed.
    if [ ! -x "$CORE_BIN" ]; then
        chk_add bad core "the core is not installed at $CORE_BIN" \
            "run pingify and choose 6, Update Pingify"
        chk_add note core-rest "nothing below could be checked without it"
        chk_finish "$name" "$mode"
        return 2
    fi
    if core_ver=$("$CORE_BIN" -version 2>&1); then
        core_ver=${core_ver%%$'\n'*}
        core_ver=${core_ver##* }
        if [ "$core_ver" = "$PINGIFY_VERSION" ]; then
            chk_add ok core "core $core_ver, matching this script"
        else
            chk_add warn core "core $core_ver, this script is $PINGIFY_VERSION" \
                "an older core can lack a setting this writes" \
                "update both:  pingify --update"
        fi
    else
        chk_add bad core "$CORE_BIN will not run" \
            "it may be built for another architecture" \
            "reinstall it:  pingify --update"
    fi

    # 2. the config, judged by the only judge that counts. The core's refusal
    # is one long sentence, so it goes through the UI's own cut rather than
    # over the right-hand edge of a phone terminal.
    if out=$("$CORE_BIN" -c "$CK_FILE" -check 2>&1); then
        chk_add ok config "the core accepts $CK_FILE"
    else
        chk_add bad config \
            "the core refuses it: $(trunc_to "${out%%$'\n'*}" $((UI_W - 26)))" \
            "edit $CK_FILE" \
            "the same change is needed on both servers"
    fi

    # 3. systemd. svc_state tells stopped (enabled, not running) from disabled
    # (not even wanted), and the two need different advice.
    st=$(svc_state "$name")
    case $st in
    active)
        since=$(systemctl show -p ActiveEnterTimestamp --value \
            "pingify@$name" 2>/dev/null)
        chk_add ok service "running since ${since:-a moment ago}"
        ;;
    stopped)
        # The command goes on the fix line bare. The old "read why:  " prefix
        # spent ten columns of a 46-column budget, so any tunnel name over ten
        # characters wrapped, and fix() pads rather than cuts, so the wrapped
        # half landed hard against the left margin and read as a line of its
        # own.
        chk_add bad service "the service is enabled but not running" \
            "systemctl start pingify@$name" \
            "journalctl -u pingify@$name -n 30"
        ;;
    *)
        chk_add bad service "the service is neither running nor enabled" \
            "systemctl enable --now pingify@$name"
        ;;
    esac

    # 4. the private link. operstate on a tun device reads "unknown" even when
    # it is carrying perfectly - the driver has no carrier to report - so the
    # flags word is the thing to look at. Bit 0 of it is IFF_UP.
    if [ ! -d "/sys/class/net/$CK_DEV" ]; then
        chk_add bad link "the private link $CK_DEV does not exist" \
            "the core makes it at start, so it never started" \
            "journalctl -u pingify@$name -n 30"
    else
        fl=$(cat "/sys/class/net/$CK_DEV/flags" 2>/dev/null)
        addr=$(ip -4 -o addr show dev "$CK_DEV" 2>/dev/null | awk '{print $4; exit}')
        live_mtu=$(cat "/sys/class/net/$CK_DEV/mtu" 2>/dev/null)
        if [ $((${fl:-0} & 1)) -ne 1 ]; then
            chk_add bad link "$CK_DEV exists but is down" \
                "restart it:  systemctl restart pingify@$name"
        elif [ -z "$addr" ]; then
            chk_add bad link "$CK_DEV is up but has no address" \
                "restart it:  systemctl restart pingify@$name"
        elif [ "$addr" != "$CK_MINE" ]; then
            chk_add bad link "$CK_DEV carries $addr, not $CK_MINE" \
                "something else set it; restart the tunnel"
        else
            chk_add ok link "link $CK_DEV is up, $addr, mtu ${live_mtu:-?}"
        fi
        if [ -n "$live_mtu" ] && [ "$live_mtu" != "$CK_MTU" ]; then
            chk_add warn mtu "device mtu $live_mtu, the config says $CK_MTU" \
                "a hand-set mtu is lost on the next restart" \
                "put the number in the config instead"
        fi
    fi

    # 5. has the far end ever been heard from. Nothing else stands in for it:
    # the link can be up, the config right and the service running with no
    # packet from over there having ever arrived.
    if tun_stats "$name"; then
        # Only the word true. up is a Go bool in the core's report, so the
        # value is true or false and never 1 or yes, and accepting those two
        # here made this section disagree with the loss check and the speed
        # test below, which both test for true alone. Had the core ever
        # answered 1, this line would have said the far end was there while
        # the loss check vanished and the speed test called the same tunnel
        # unseen.
        # up alone is not the question. On the side that dials, the core's up
        # is true from the first second because it knows the address it was
        # given; only bytes arriving prove there is anybody at it. Twenty
        # seconds of grace so that a check run right after a start does not
        # call a healthy tunnel dead.
        heard=$ST_UP
        case $ST_INB in '' | 0) [ "${ST_UPTIME:-0}" -ge 20 ] && heard=false ;; esac
        case $heard in
        true)
            if [ "${ST_INB:-0}" = 0 ]; then
                chk_add note peer "started $(human_secs "$ST_UPTIME") ago; nothing back yet"
            else
                # "has been heard from", not "is there": this counts bytes
                # that have arrived since the tunnel started, so it is a fact
                # about the past. Whether anybody is at the far end *now* is
                # the next check, and the two disagree exactly when something
                # has just broken. The time is this tunnel's own, not the far
                # end's - it used to read "the far end is there, up for 3m",
                # which is our uptime wearing their name.
                chk_add ok peer \
                    "the far end has been heard from - this tunnel has run $(human_secs "$ST_UPTIME")"
            fi
            ;;
        *)
            case $CK_TRANSPORT in
            icmp)
                chk_add bad peer "the far end has never been seen" \
                    "on KHAREJ:  systemctl status pingify@$name" \
                    "watch there:  tcpdump -ni any icmp" \
                    "if nothing arrives at all, try tcp or udp"
                ;;
            awg)
                # The port worth naming here is AmneziaWG's, not the carrier's:
                # the carrier's is inside the link and nothing outside can
                # reach it or block it.
                chk_add bad peer "the far end has never been seen inside the link" \
                    "the line below says whether the link itself is up" \
                    "if it handshook, the path is dropping udp once it flows" \
                    "on KHAREJ:  systemctl status pingify@$name"
                ;;
            gre)
                chk_add bad peer "the far end has never been seen" \
                    "on KHAREJ:  systemctl status pingify@$name" \
                    "watch there:  tcpdump -ni any proto gre" \
                    "some networks drop ip protocol 47 outright; try tcp or ws"
                ;;
            tcp)
                # TCP is the one transport whose far end can be tested from
                # here without the tunnel: a connection either opens or it
                # does not, and which of the two it is decides where to look.
                if [ "$CK_SIDE" = iran ] && tcp_reach "$CK_KHAREJ" "$CK_PORT"; then
                    chk_add bad peer \
                        "tcp/$CK_PORT is open there, but nothing pingify sent has come back" \
                        "the token differs between the two servers" \
                        "compare:  grep token $CK_FILE   on both" \
                        "or something else is answering on that port there"
                else
                    chk_add bad peer "the far end has never been seen" \
                        "on KHAREJ:  systemctl status pingify@$name" \
                        "open it there:  ufw allow $CK_PORT/tcp" \
                        "from here:  nc -zv $CK_KHAREJ $CK_PORT"
                fi
                ;;
            *)
                # Bare again: the address on this line is a hostname somebody
                # else chose, so the prefix is the only part of it there is
                # room to give up.
                chk_add bad peer "the far end has never been seen" \
                    "on KHAREJ:  systemctl status pingify@$name" \
                    "open it there:  ufw allow $CK_PORT/udp" \
                    "nc -uzv $CK_KHAREJ $CK_PORT" \
                    "a token edited on one side only does this"
                ;;
            esac
            ;;
        esac

        # The link underneath, when there is one. An AmneziaWG tunnel has two
        # things that can be down and they fail differently: the handshake is
        # theirs and says whether the two servers have agreed on keys at all,
        # and everything below this is ours and runs inside it.
        if [ "$CK_TRANSPORT" = awg ]; then
            local iface age
            iface=$(awg_iface "$name")
            if [ -z "$iface" ] || ! ip link show "$iface" >/dev/null 2>&1; then
                chk_add bad awg "the AmneziaWG link ${iface:-for this tunnel} is not up" \
                    "systemctl status awg-quick@${iface:-awg0}" \
                    "nothing below this can work without it"
            elif age=$(awg_handshake "$iface"); then
                if [ "$age" -lt 180 ]; then
                    chk_add ok awg "AmneziaWG handshook $(human_secs "$age") ago on $iface"
                else
                    chk_add warn awg "the last AmneziaWG handshake was $(human_secs "$age") ago" \
                        "the far end may be down, or the path stopped carrying udp" \
                        "awg show $iface"
                fi
            else
                chk_add bad awg "AmneziaWG on $iface has never handshaken" \
                    "the two servers have not agreed on keys" \
                    "open udp/$(toml_get "$CK_FILE" awg port) on KHAREJ" \
                    "awg show $iface"
            fi
        fi

        # The far end, asked through the tunnel.
        #
        # Everything above is this server's own opinion of the tunnel. This is
        # the one question in the check whose answer comes from the other
        # server, and the asking is the test: if it answers, a packet put into
        # the tun device here came out of the one over there and the reply
        # found its way back. The carrier being up does not say that.
        if [ "$heard" = true ]; then
            local far fv fp mine_p
            if far=$(far_report "$name") && [ -n "$far" ]; then
                chk_add ok link-end "the far end answers on the private link"

                # Two servers on two versions is the commonest way a pair that
                # worked stops working, and until now finding it meant logging
                # into both of them.
                fv=$(json_field "$far" version)
                if [ -n "$fv" ] && [ -n "$core_ver" ] && [ "$fv" != "$core_ver" ]; then
                    chk_add warn far-version \
                        "the far end runs core $fv, this one runs $core_ver" \
                        "update both servers:  pingify --update"
                fi
                fp=$(json_field "$far" profile)
                mine_p=$(toml_get "$CK_FILE" tuning profile)
                if [ -n "$fp" ] && [ -n "$mine_p" ] && [ "$fp" != "$mine_p" ]; then
                    chk_add warn far-profile \
                        "the far end is on $fp, this one on $mine_p" \
                        "pick one on both, from the tunnel screen"
                fi
            else
                chk_add warn link-end "the far end does not answer on the private link" \
                    "the carrier is up, so this is the link and not the path" \
                    "on the other server:  pingify --status" \
                    "a core older than $PINGIFY_VERSION has no health port"
            fi
        fi
    else
        if have curl; then
            chk_add bad status \
                "no answer on 127.0.0.1:$(status_port "$name")" \
                "systemctl status pingify@$name" \
                "status.port 0 in the config turns it off"
        else
            # Not knowing is a warning, not a note: a note is something that is
            # fine, and a tunnel nobody can question is not fine.
            chk_add warn status "curl is missing, so nothing could ask it" \
                "install curl:  apt-get install -y curl"
        fi
    fi

    # 6. loss, as a rate. There is no denominator in the report - the core
    # counts what it missed, not what it should have had - so this is losses
    # per minute since it started, and it is not called a percentage.
    if [ "$ST_UP" = true ] && [ -n "$ST_UPTIME" ]; then
        lpm=$(awk -v l="${ST_LOST:-0}" -v s="$ST_UPTIME" \
            'BEGIN { if (s + 0 < 30) print "early"; else printf "%.1f", l * 60 / s }')
        case $lpm in
        early)
            chk_add note loss "too early to say anything about loss yet"
            ;;
        *)
            if [ "${lpm%%.*}" -ge 60 ]; then
                chk_add bad loss "the path is losing $lpm packets a minute" \
                    "run Measure MTU; a large mtu loses big packets" \
                    "if the mtu is right, the path is congested"
            elif [ "${lpm%%.*}" -ge 5 ]; then
                chk_add warn loss "the path is losing $lpm packets a minute" \
                    "run Measure MTU: a slightly large mtu does this"
            else
                chk_add ok loss "loss is $lpm a minute, ${ST_LATE:-0} arrived late"
            fi
            ;;
        esac
    fi

    # 7. the forwarded ports, and whether anything is behind them. IRAN only:
    # KHAREJ forwards nothing, because nobody connects to it.
    if [ "$CK_SIDE" = iran ]; then
        spec=$(chk_forward_spec "$name") || spec=
        if [ -z "$spec" ]; then
            chk_add note ports "no ports are forwarded from this server"
        elif ! declare -F forward_specs >/dev/null 2>&1; then
            chk_add note ports "ports unchecked: forwarding is not loaded"
        else
            total=0 missing=0 unknown=0
            while read -r proto lo hi rhost rport; do
                [ -n "$proto" ] || continue
                # forward_specs writes - in the destination column when the
                # token named no host, and it means "the far end of this
                # tunnel"; nat_rules_for substitutes the peer address before it
                # builds a rule. This did not, so a plain 443 forward probed
                # the host called - , always failed, and every ordinary forward
                # drew a warning telling the operator to listen on -:443.
                [ "$rhost" = - ] && rhost=$CK_PEER
                total=$((total + 1))
                if [ "$proto" != tcp ]; then
                    # There is no way to ask a udp port whether anybody is
                    # behind it. "Closed" would be a guess dressed up as a
                    # measurement, and this screen does not do that.
                    unknown=$((unknown + 1))
                    continue
                fi
                if ! tcp_reach "$rhost" "$rport"; then
                    missing=$((missing + 1))
                    chk_add warn "port-$lo" \
                        "$lo/tcp goes to $rhost:$rport, nothing there" \
                        "on KHAREJ, listen on $rhost:$rport" \
                        "from here:  nc -zv $rhost $rport"
                fi
            done < <(forward_specs "$spec" 2>/dev/null)
            if [ "$total" = 0 ]; then
                chk_add warn ports "the forwarded port list parsed to nothing" \
                    "open Ports on the tunnel screen and set them again"
            elif [ "$missing" = 0 ]; then
                chk_add ok ports \
                    "$total forwarded port$(plural_s "$total"), each one answers"
            fi
            [ "$unknown" -gt 0 ] &&
                chk_add note ports-udp "$unknown are udp and cannot be tested here"
        fi
    fi

    # A stream carrier on a path that drops packets lives or dies by the
    # kernel's congestion control, and this is not a preference. Measured on
    # the Tehran to Frankfurt pair, the same tunnel, minutes apart:
    #
    #	cubic    31 Mbit/s over sixteen streams
    #	bbr     348
    #
    # Cubic reads a dropped packet as congestion and halves the window. On a
    # path that drops packets for reasons of its own, that is a window that
    # never opens again. It is worth a warning rather than a note because the
    # tunnel is carrying a tenth of what it could.
    if [ "$CK_TRANSPORT" = tcp ]; then
        cc=$(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null)
        if [ -n "$cc" ] && [ "$cc" != bbr ]; then
            chk_add warn bbr "a tcp tunnel, and this kernel is on $cc" \
                "measured here: bbr carried 348 Mbit/s where cubic carried 31" \
                "pingify, 4 Host tuning, 2 BBR - on both servers"
        fi
    fi

    # The ICMP note, last, because it explains something rather than reporting
    # it. Grey, uncounted, one line.
    #
    # An ordinary ping across this link gets nothing back and that is correct:
    # the carrier stops both kernels answering echo. The round trip on the
    # screens above is not a ping - it is the handshake with the far end's
    # health port, which is a real crossing of the link and back.
    if [ "$CK_TRANSPORT" = icmp ]; then
        chk_add note icmp "ping gets no answer here by design; the round trip is measured on the health port"
    fi

    chk_finish "$name" "$mode"
    [ "$CHK_NBAD" -gt 0 ] && return 2
    [ "$CHK_NWARN" -gt 0 ] && return 1
    return 0
}

# chk_finish picks the renderer. One place, so an early return in health_check
# cannot forget the --json case and print a screen at a caller that wanted
# something a machine could read.
#
# Both spellings of the mode word are matched, and that is not tidiness. main
# calls health_check with the bare word json, while this tested only for
# --json, so `pingify --check NAME --json` rendered the escape-coded human
# screen into whatever script was parsing it and exited 0, 1 or 2 as though it
# had answered. Taking either word means neither side can break it again by
# settling on the other one.
chk_finish() {
    case ${2:-} in
    json | --json) chk_json "$1" ;;
    *) chk_render "$1" ;;
    esac
}

# --------------------------------------------------------------------------
# the live view
# --------------------------------------------------------------------------
#
# A fixed block repainted in place about once a second. It moves the cursor up
# with \033[<n>A and erases each line as it rewrites it, and never clears the
# screen: over a link with 100 ms of delay and real loss, the scrollback above
# is where you look when the connection stutters.
#
# The cursor is hidden on entry and put back by a trap on EXIT and INT. The old
# spinner hid it and had no trap, so one Ctrl-C left the cursor invisible for
# the rest of the ssh session. This is the only EXIT trap in the script; if
# another is ever added, this one has to save and restore it.

LIVE_STOP=0

live_cursor_on() { printf '\033[?25h'; }

# spark_bar is one column of the round-trip history. A reply that never came is
# drawn as the failure glyph, not as a low bar: a low bar is the same shape as
# a fast reply and would read as good news.
spark_bar() {
    local ms=$1 bars i
    case $ms in
    '' | *[!0-9.]*) printf '%s' "$G_BAD"; return ;;
    esac
    if [ "$UI_GLYPH" = utf8 ]; then bars='▁▂▃▄▅▆▇█'; else bars='._-=+*#@'; fi
    ms=${ms%%.*}
    if [ "$ms" -lt 60 ]; then i=0
    elif [ "$ms" -lt 80 ]; then i=1
    elif [ "$ms" -lt 100 ]; then i=2
    elif [ "$ms" -lt 130 ]; then i=3
    elif [ "$ms" -lt 170 ]; then i=4
    elif [ "$ms" -lt 220 ]; then i=5
    elif [ "$ms" -lt 300 ]; then i=6
    else i=7; fi
    printf '%s' "${bars:i:1}"
}

screen_live() {
    local name=$1
    local -a lines
    local painted=0 spark= rtt= key rxp txp last_rx= last_tx= din dout w

    chk_load "$name" || { bad "there is no tunnel called $name"; return 1; }

    blank
    if [ ! -t 0 ] || [ ! -t 1 ]; then
        # Nothing to repaint into and nobody to press a key. One frame, plain,
        # so a script or a test gets an answer instead of a spin.
        live_frame "$name" '' ''
        return 0
    fi

    w=$((UI_W - 34))
    [ "$w" -lt 10 ] && w=10

    LIVE_STOP=0
    trap 'LIVE_STOP=1' INT
    trap 'live_cursor_on' EXIT
    printf '\033[?25l'

    while :; do
        rxp=$(cat "/sys/class/net/$CK_DEV/statistics/rx_packets" 2>/dev/null)
        txp=$(cat "/sys/class/net/$CK_DEV/statistics/tx_packets" 2>/dev/null)
        din= dout=
        if [ -n "$last_rx" ] && [ -n "$rxp" ]; then
            din=$((rxp - last_rx))
            dout=$((txp - last_tx))
        fi
        last_rx=$rxp last_tx=$txp

        # One ping per frame, bound to the tun. On an ICMP tunnel there is
        # nothing to ping, so that row becomes the grey explanation and the
        # block keeps its height. The ping and the status read add about a
        # tenth of a second, so a frame is about a second, not exactly.
        rtt=
        if [ "$CK_TRANSPORT" != icmp ]; then
            rtt=$(link_rtt "$CK_DEV" "$CK_PEER") || rtt=
            spark=$spark$(spark_bar "$rtt")
            # Trim only once it is over the width. ${spark: -w} on a string
            # shorter than w returns nothing at all, so trimming on every frame
            # left the sparkline empty until it had run for w seconds.
            [ "${#spark}" -gt "$w" ] && spark=${spark: -w}
        fi

        lines=()
        while IFS= read -r key; do lines+=("$key"); done < <(
            live_frame "$name" "$spark" "$rtt" "$din" "$dout"
        )

        [ "$painted" -gt 0 ] && printf '\033[%dA' "$painted"
        for key in "${lines[@]}"; do printf '\r\033[K%s\n' "$key"; done
        painted=${#lines[@]}

        [ "$LIVE_STOP" = 1 ] && break
        # read returns non-zero for both a timeout and a keystroke, so the
        # variable is what tells them apart: only a keystroke sets it.
        key=
        read -rsn1 -t 1 key
        [ -n "$key" ] && break
        [ "$LIVE_STOP" = 1 ] && break
    done

    trap - INT
    trap - EXIT
    live_cursor_on
    blank
    return 0
}

# live_frame prints the block once, from the CK_* screen_live loaded. Separate,
# so the non-interactive path and the loop draw the same thing and the height
# of the block is a property of one function rather than of the loop.
live_frame() {
    local name=$1 spark=$2 rtt=$3 din=${4:-} dout=${5:-} state=unknown
    local carrying losses packets

    if tun_stats "$name"; then
        [ "$ST_UP" = true ] && state=running || state=idle
    else
        [ "$(svc_state "$name")" = active ] && state=idle || state=stopped
    fi

    carrying="$(round1 "$ST_IN") Mbit/s in, $(round1 "$ST_OUT") out"
    losses="${ST_LOST:-0} lost, ${ST_LATE:-0} late, ${ST_GAPS:-0}"
    losses="$losses gap$(plural_s "${ST_GAPS:-0}")"
    if [ -n "$din" ]; then
        packets="$din in, $dout out in the last second"
    else
        packets="counting"
    fi

    rule "$name  $(state_dot "$state")"
    field "Carrying" "$carrying"
    if [ "$CK_TRANSPORT" = icmp ]; then
        field "Round trip" "$(printf '%snot measurable while ICMP runs%s' \
            "$C_MUTE" "$C_OFF")"
    else
        field "Round trip" "$(printf '%s%s ms%s  %s' "$(rtt_colour "$rtt")" \
            "${rtt:-?}" "$C_OFF" "$spark")"
    fi
    field "Losses" "$losses"
    field "Packets" "$packets"
    field "Uptime" "$(human_secs "$ST_UPTIME")"
    dim "any key to leave"
}

# --------------------------------------------------------------------------
# measuring the mtu
# --------------------------------------------------------------------------
#
# A binary search for the largest packet that crosses the private link intact.
# `ping -M do` sets don't-fragment, so a packet too big for the carrier path is
# dropped rather than quietly cut in half and the search finds the boundary.
# The device's own mtu is the ceiling - the kernel will not send a bigger
# don't-fragment packet - so this measures whether the configured mtu is
# honest, and when it is not, what is.

MTU_WANT=

mtu_editor() { toml_set "$1" tun mtu "$MTU_WANT"; }

# One probe. -s is the payload, so the packet on the wire is 28 bytes larger:
# 20 of IP and 8 of ICMP. Getting that 28 wrong is the classic way to set an
# mtu a little too big and then lose exactly the full-size packets.
mtu_probe() {
    local dev=$1 peer=$2 total=$3
    ping -n -c1 -W2 -M do -s $((total - 28)) -I "$dev" "$peer" >/dev/null 2>&1
}

measure_mtu() {
    local name=$1 lo hi mid best=0 tries=0

    chk_load "$name" || { bad "there is no tunnel called $name"; return 1; }
    blank
    rule "Measure MTU for $name"
    blank

    if [ "$CK_TRANSPORT" = icmp ]; then
        dim "This cannot be measured on an ICMP tunnel. The core"
        dim "stops both kernels answering echo while one runs, so"
        dim "a probe is answered by nobody, every size looks too"
        dim "big, and the search sets the floor on no evidence."
        blank
        say "  Use a number instead of a measurement:"
        # Short enough to survive field's cut at UI_W-20 on a 60-column
        # terminal: a truncated explanation explains nothing.
        field "1320" "the default, and right on a 1500 path"
        field "1280" "survives PPPoE, mobile, double tunnels"
        blank
        if [ "$CK_MTU" != 1280 ] && confirm "set the mtu to 1280?" n; then
            MTU_WANT=1280
            # yes, not restart. cfg_apply compares its third argument against
            # the word yes, so the literal restart passed here read as "do not
            # restart" - and cfg_apply still returned 0, so this printed a
            # green line over a tunnel still running the old mtu until somebody
            # happened to restart it by hand.
            cfg_apply "$name" mtu_editor yes &&
                ok "mtu 1280 - set the same number on KHAREJ"
        fi
        return 0
    fi

    if [ ! -d "/sys/class/net/$CK_DEV" ]; then
        bad "$CK_DEV does not exist, so there is nothing to measure"
        fix "start the tunnel:  systemctl start pingify@$name"
        return 1
    fi

    dim "Probing $CK_PEER over $CK_DEV, don't-fragment set."
    dim "One ping per size, so this takes a few seconds."
    blank

    lo=576 hi=$CK_MTU
    while [ "$lo" -le "$hi" ]; do
        mid=$(((lo + hi) / 2))
        tries=$((tries + 1))
        if mtu_probe "$CK_DEV" "$CK_PEER" "$mid"; then
            dim "$(printf '%5s  crosses' "$mid")"
            best=$mid
            lo=$((mid + 1))
        else
            dim "$(printf '%5s  does not' "$mid")"
            hi=$((mid - 1))
        fi
    done
    blank

    if [ "$best" = 0 ]; then
        # Nothing crossed, not even the smallest legal packet. That is a dead
        # link or a firewall eating echo, and lowering the mtu on this evidence
        # would be exactly the wrong move: it would hide a real fault behind a
        # setting nobody would think to put back.
        bad "nothing crossed at any size: not an mtu problem"
        fix "check the tunnel first:  pingify --check $name"
        fix "echo may be blocked; the mtu was left alone"
        return 2
    fi

    if [ "$best" -ge "$CK_MTU" ]; then
        ok "$CK_MTU crosses intact, in $tries probes"
        dim "The device mtu is the ceiling, so more may work."
        return 0
    fi

    warn "the largest that crosses is $best, config says $CK_MTU"
    fix "the difference is lost as whole packets"
    blank
    if confirm "set the mtu to $best?" y; then
        MTU_WANT=$best
        # yes is the word cfg_apply tests for; restart quietly meant no, and
        # the measured mtu sat in the file unused.
        if cfg_apply "$name" mtu_editor yes; then
            ok "mtu $best"
            dim "Set the same on KHAREJ: the file is shared."
        fi
    fi
    return 1
}

# --------------------------------------------------------------------------
# the speed test
# --------------------------------------------------------------------------
#
# Honest, or nothing. Only one thing is reachable across a private /24 without
# cooperation from the far server - the far kernel's echo reply - and that is
# rate limited to about a thousand a second, so a figure built from it would be
# net.ipv4.icmp_msgs_per_sec reported as the link's throughput. The old
# bench_menu had the same shape of fault: it curl'd a third-party script that
# measured the machine's own path to the internet and printed the answer as if
# it were the tunnel.
#
# A real test needs a listener at the other end. Ask for one, use it, and when
# there is not one say so, and show what the link is actually carrying instead
# of inventing a number.

speed_test() {
    local name=$1 out rc ref

    chk_load "$name" || { bad "there is no tunnel called $name"; return 1; }
    blank
    rule "Speed test for $name"
    blank

    if [ "$(svc_state "$name")" != active ]; then
        bad "the tunnel is not running: nothing to push"
        fix "systemctl start pingify@$name"
        return 1
    fi
    if tun_stats "$name" && [ "$ST_UP" != true ]; then
        bad "the far end has not been seen; nothing is there"
        fix "check it first:  pingify --check $name"
        return 1
    fi

    say "  What the link is carrying right now:"
    field "in" "$(round1 "$ST_IN") Mbit/s"
    field "out" "$(round1 "$ST_OUT") Mbit/s"
    blank

    if ! have iperf3; then
        warn "iperf3 is missing, and it is the honest way"
        fix "apt-get install -y iperf3"
        fix "dnf install -y iperf3 on Rocky or Alma"
        blank
        dim "Nothing else on the far server can be pushed into,"
        dim "and a figure built from pings would measure the far"
        dim "kernel's echo rate limit, not this link."
        return 1
    fi

    dim "This needs a listener there. On KHAREJ, run:"
    say "       iperf3 -s"
    blank
    confirm "is it running there?" y || {
        dim "Nothing measured."
        return 1
    }

    # Sixteen streams and six seconds, so the answer is directly comparable
    # with the table the profiles come from: gaming 397 Mbit/s over 16 streams,
    # balanced 448, download 466. A four-stream figure would be smaller for
    # reasons that have nothing to do with this link.
    blank
    dim "16 streams for six seconds, matching the numbers"
    dim "the profiles were measured at."
    blank
    out=$(iperf3 -c "$CK_PEER" -t 6 -P 16 2>&1)
    rc=$?
    printf '%s\n' "$out" | sed 's/^/       /'
    blank

    if [ "$rc" -ne 0 ]; then
        bad "iperf3 did not finish"
        case $out in
        *"onnection refused"*)
            fix "nothing on $CK_PEER:5201 - run iperf3 -s there"
            ;;
        *"o route to host"* | *"imed out"*)
            fix "the link is up but nothing crosses it"
            fix "pingify --check $name"
            ;;
        *)
            fix "read the message above, then:"
            fix "pingify --check $name"
            ;;
        esac
        return 1
    fi

    case ${ST_PROFILE:-$(toml_get "$CK_FILE" tuning profile)} in
    gaming) ref="gaming measured 397 Mbit/s over 16 streams" ;;
    download) ref="download measured 466 Mbit/s over 16 streams" ;;
    *) ref="balanced measured 448 Mbit/s over 16 streams" ;;
    esac
    ok "done"
    dim "$ref on the reference path."
    dim "A slower path abroad reads lower; that is the path."
    return 0
}
#!/usr/bin/env bash
#
# Things done to the machine rather than to a tunnel: kernel tuning, and
# blocking. Both screens obey one rule - everything this file changes, it owns
# outright and can take back.
#
# The kernel settings are one drop-in file. Not three, which is what the old
# manager grew: a profile file, a BBR file and a forwarding file, so "revert"
# was a list somebody had to keep in step and did not. One file means revert is
# deleting one file, and it means the file carries its own state in two comment
# lines instead of needing marker files beside it.
#
# The firewall rules are two chains of our own, hooked into INPUT and OUTPUT at
# position 1 and rebuilt from empty on every apply. The state files in
# $STATE_DIR are the truth and iptables is derived from them, so a flush can
# never reach a rule the operator's panel put there.
#
# One sysctl is deliberately absent. net.ipv4.icmp_echo_ignore_all belongs to
# the ICMP carrier: internal/carrier/icmp.go sets it to 1 while an ICMP tunnel
# runs, because both ends of that tunnel send echo requests and a kernel that
# answers them doubles every packet on the wire. Nothing here reads it, writes
# it, or reports its value as a fault.

HOST_SYSCTL=/etc/sysctl.d/99-pingify.conf
HOST_LIMITS=/etc/security/limits.d/99-pingify.conf

# Benchmark sites, so a customer cannot spend the whole link proving how fast
# it is. The old list carried a CJK entry that no resolver and no string match
# would ever match; it is gone. Read with an unquoted expansion on purpose -
# the whitespace is the separator.
SPEEDTEST_HOSTS="speedtest.net ooklaserver.net speedtestcustom.com fast.com
nperf.com speedof.me openspeedtest.com speedcheck.org librespeed.org
speedtest.cn"

HOSTS_MARK='# --- pingify speedtest block ---'
HOSTS_END='# --- end pingify ---'

# --------------------------------------------------------------------------
# host tuning
# --------------------------------------------------------------------------

# host_profile and host_bbr_state read the drop-in rather than a state file.
# The file is written by exactly one function and always carries both comment
# lines, so it cannot disagree with itself the way a file and a marker beside
# it can.
host_profile() {
    awk '/^# profile: /{ sub(/^# profile: /, ""); print; exit }' "$HOST_SYSCTL" 2>/dev/null
}

host_bbr_state() {
    local s
    s=$(awk '/^# bbr: /{ sub(/^# bbr: /, ""); print; exit }' "$HOST_SYSCTL" 2>/dev/null)
    printf '%s' "${s:-off}"
}

host_summary() {
    local p
    p=$(host_profile)
    [ -n "$p" ] || { printf 'not applied'; return; }
    printf '%s, BBR %s' "$p" "$(host_bbr_state)"
}

host_bbr_available() {
    # Setting the sysctl asks the kernel for the module by name, so this is
    # also how tcp_bbr gets loaded the first time. That is why there is no
    # /etc/modules-load.d entry here: one less file to remember in revert.
    modprobe tcp_bbr 2>/dev/null || true
    local avail
    avail=$(sysctl -n net.ipv4.tcp_available_congestion_control 2>/dev/null)
    # list_has, not `... | grep -qx bbr`: grep would exit at the match, sysctl
    # would take SIGPIPE writing into the closed pipe, and pipefail would hand
    # back 141 for a question that was answered yes. Deliberate word split.
    list_has bbr $avail
}

# host_write_sysctl writes the whole drop-in from scratch. Both the profile and
# the BBR switch come through here, because a switch that appends to a file it
# did not write is a file nobody can predict.
#
# The three profiles differ in one idea: how much the kernel may hold for a
# socket, and how long it may spend draining the card in one go. Measured on
# the real path, a single stream carries 448 Mbit/s at 81 ms idle, which is a
# bandwidth-delay product of about 4.5 MB - so even the smallest ceiling below
# is seven times what one connection can have in flight. The ceiling is not for
# one stream. It is for the sixteen that arrive at once when a household starts
# using the link, and that is what moves between the three.
host_write_sysctl() {
    local profile=$1 bbr=$2
    local sockbuf defbuf udpmin backlog budget budget_us

    case $profile in
    gaming)
        sockbuf=33554432 defbuf=524288 udpmin=131072
        backlog=100000 budget=300 budget_us=2000
        ;;
    download)
        sockbuf=134217728 defbuf=4194304 udpmin=524288
        backlog=300000 budget=1200 budget_us=8000
        ;;
    *)
        profile=balanced
        sockbuf=67108864 defbuf=1048576 udpmin=262144
        backlog=200000 budget=600 budget_us=4000
        ;;
    esac

    # The write is checked. It used to be assumed, so a full disk or a
    # read-only /etc left the old file in place, sysctl --system succeeded on
    # what was already there, and the caller printed "host tuning applied" over
    # settings nobody had changed.
    cat >"$HOST_SYSCTL" <<SYSCTL || { bad "could not write $HOST_SYSCTL"; return 1; }
# Written by Pingify $PINGIFY_VERSION. Delete this file, run "sysctl --system",
# and the distribution's own settings are what is left.
# profile: $profile
# bbr: $bbr

# Room in flight. A long path with real loss needs far more than a datacentre
# LAN, which is what the stock numbers are sized for.
net.core.rmem_max = $sockbuf
net.core.wmem_max = $sockbuf
net.core.rmem_default = $defbuf
net.core.wmem_default = $defbuf
net.core.optmem_max = 4194304
net.ipv4.tcp_rmem = 4096 $defbuf $sockbuf
net.ipv4.tcp_wmem = 4096 $defbuf $sockbuf
net.ipv4.udp_rmem_min = $udpmin
net.ipv4.udp_wmem_min = $udpmin

# Behave on a long path. slow_start_after_idle costs a fresh ramp every time a
# connection pauses, which over 81 ms is felt as the first second of every page.
net.ipv4.tcp_mtu_probing = 1
net.ipv4.tcp_slow_start_after_idle = 0
net.ipv4.tcp_no_metrics_save = 1
net.ipv4.tcp_notsent_lowat = 131072

# Drain the card's bursts without starving everything else.
net.core.netdev_max_backlog = $backlog
net.core.netdev_budget = $budget
net.core.netdev_budget_usecs = $budget_us

# Connection churn, and the descriptors it needs.
net.core.somaxconn = 65535
net.ipv4.tcp_fin_timeout = 15
net.ipv4.tcp_tw_reuse = 1
net.ipv4.ip_local_port_range = 10240 65535
fs.file-max = 2097152
fs.nr_open = 2097152
vm.swappiness = 10
SYSCTL

    # fq is the queue discipline BBR is designed against, and BBR without it
    # paces in software instead. The tunnel puts fq on its own device whatever
    # this says - tuning.pace in the config does that - so this line is about
    # the host's other interfaces, not about the link.
    if [ "$bbr" = on ]; then
        cat >>"$HOST_SYSCTL" <<'SYSCTL' || { bad "could not add the BBR lines"; return 1; }

net.core.default_qdisc = fq
net.ipv4.tcp_congestion_control = bbr
SYSCTL
    fi

    if ! sysctl --system >/dev/null 2>&1; then
        warn "the kernel would not take some of those settings"
        fix "sysctl --system   prints the line it refused"
        return 1
    fi
    return 0
}

# host_limits raises the descriptor ceiling for logins. It is a separate switch
# because it is the one change here that a service does not see: systemd units
# get their limit from the unit, and pingify@.service already carries
# LimitNOFILE=1048576. This is for the shell you ssh in with.
host_limits() {
    # Checked, because the success line below said the limit was raised whether
    # or not a single byte reached the file.
    cat >"$HOST_LIMITS" <<'LIMITS' || { bad "could not write $HOST_LIMITS"; return 1; }
# Written by Pingify. Delete this file to undo it.
*    soft  nofile  1048576
*    hard  nofile  1048576
root soft  nofile  1048576
root hard  nofile  1048576
LIMITS
    ok "descriptor limit raised to 1048576"
    dim "PAM reads this at login, so this shell keeps the $(ulimit -n) it started with"
}

# revert_tuning removes what this file wrote, and says plainly what removing it
# does not achieve. The old manager kept a thousand-line dump of sysctl -a and
# called it a restore path; nothing ever read it back, and it would not have
# helped, because most of those values were defaults that were never set.
revert_tuning() {
    rm -f "$HOST_SYSCTL" "$HOST_LIMITS"
    sysctl --system >/dev/null 2>&1 || true
    ok "the Pingify drop-in and the limits file are gone"
    blank
    dim "what that does not undo:"
    dim "  a value we raised stays raised until this machine reboots - sysctl"
    dim "  --system replays the files that are left, and nothing recorded what"
    dim "  the kernel held before, so there is nothing to put back"
    dim "  shells already logged in keep the descriptor limit they started with"
    if [ "$(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null)" = bbr ]; then
        dim "  congestion control is still bbr for this boot; 'Turn BBR off' sets"
        dim "  it back now, a reboot does it either way"
    fi
    dim "blocking rules are not tuning and are still in place - clear them on"
    dim "the Blocking screen"
}

screen_host() {
    local key p n bbr cc qd
    while :; do
        screen_top
        blank
        rule "Host tuning"
        dim "The kernel's own network settings, which apply to everything this"
        dim "server does, not only to the tunnel. Every change is written to one"
        dim "drop-in file and can be taken back from this screen."
        blank
        dim "A tunnel's queue profile is a different thing with the same three"
        dim "names; it lives on that tunnel's screen."
        blank
        p=$(host_profile)
        bbr=$(host_bbr_state)
        # Read back from the kernel, not from the file we wrote. A drop-in that
        # says bbr and a kernel running cubic is exactly the state worth seeing,
        # and the file alone cannot show it.
        cc=$(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null)
        qd=$(sysctl -n net.core.default_qdisc 2>/dev/null)
        # Two fields, not one sentence. field cuts its value to UI_W - 20, so
        # at the 60-column floor the single line ran out at 40 columns and the
        # qdisc - half of what the read-back is for - was what fell off.
        field "Profile" "${p:-not applied}"
        field "BBR" "$bbr"
        field "Kernel" "${cc:-unknown} over ${qd:-unknown}"
        field "Open files" "$(ulimit -n) here, $([ -f "$HOST_LIMITS" ] && printf '1048576 at next login' || printf 'unchanged at login')"
        field "Drop-in" "$HOST_SYSCTL"
        blank
        item2 "1" "Profile" "${p:-none applied}"
        item2 "2" "BBR" "$bbr $G_DASH the congestion control the kernel uses"
        item2 "3" "Descriptor limits" \
            "$([ -f "$HOST_LIMITS" ] && printf 'raised to 1048576' || printf 'left at the distribution default')"
        item "4" "Revert" "put every setting on this screen back"
        item "0" "Back"
        blank
        menu_key key || return 0
        case $key in
        1)
            blank
            group "WHAT THIS MACHINE MOSTLY CARRIES"
            item "1" "Gaming" "smaller socket buffers, so a reply waits less"
            item "2" "Balanced" "the one to pick if the answer is everything"
            item "3" "Download" "larger buffers, for long transfers"
            item "0" "Back"
            blank
            dim "This sets the kernel's socket buffer sizes and backlog. It is"
            dim "written to $HOST_SYSCTL and applied at once."
            blank
            # menu_key rather than pick, because this screen was reached from
            # a menu and every one of those has a numeric way back out. pick
            # answers 1 to 3 and nothing else, which is right for a question
            # in the wizard and wrong here: 0 was refused and it asked again.
            menu_key n || continue
            [ -z "$n" ] && n=2
            case $n in
            1) p=gaming ;;
            2) p=balanced ;;
            3) p=download ;;
            0) continue ;;
            *) blank; warn "there is nothing on $n"; pause; continue ;;
            esac
            blank
            host_write_sysctl "$p" "$(host_bbr_state)" && ok "$p host tuning applied"
            ;;
        2)
            blank
            if [ "$(host_bbr_state)" = on ]; then
                # Taking the two lines out of the drop-in does not take BBR off
                # the running kernel: sysctl --system only sets what a file
                # names, and no file names a default. So this branch used to
                # rewrite the file, read the live value back, and print "back
                # to bbr". Set the values here, then report what is true.
                if host_write_sysctl "${p:-balanced}" off; then
                    sysctl -qw net.ipv4.tcp_congestion_control=cubic \
                        net.core.default_qdisc=fq_codel >/dev/null 2>&1
                    cc=$(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null)
                    if [ "$cc" = bbr ]; then
                        warn "the drop-in dropped BBR but the kernel is still on bbr"
                        fix "a reboot clears it"
                    else
                        ok "back to ${cc:-the kernel default}"
                    fi
                fi
            elif ! host_bbr_available; then
                bad "this kernel does not offer BBR"
                fix "kernel $(uname -r) - 4.9 or newer with tcp_bbr is what has it"
            else
                host_write_sysctl "${p:-balanced}" on &&
                    ok "BBR is on, with fq underneath it"
            fi
            ;;
        3) blank; host_limits ;;
        4)
            blank
            confirm "remove the drop-in and the limits file?" n && { blank; revert_tuning; }
            ;;
        0 | '') return 0 ;;
        esac
    done
}

# --------------------------------------------------------------------------
# blocking
# --------------------------------------------------------------------------

# block_ipt is prefixed rather than called ipt, because the part that owns
# forwarding hooks its own chains and the two must not end up sharing one
# wrapper by accident and then disagreeing about which errors are quiet.
#
# -w 2, which was missing. Every one of these takes the xtables lock, and
# without a wait iptables gives up the moment the forwarding part is applying
# its own NAT rules. The error goes to /dev/null here, so those rules simply
# were not installed and the screen said they were; the callers below now
# check each one instead.
block_ipt() { iptables -w 2 "$@" 2>/dev/null; }

block_state() { [ -f "$STATE_DIR/block-$1" ] && printf 'on' || printf 'off'; }

host_badge() {
    if [ "$1" = on ]; then printf '%s%s on%s' "$C_OK" "$G_ON" "$C_OFF"
    else printf '%s%s off%s' "$C_MUTE" "$G_OFF" "$C_OFF"; fi
}

block_toggle() {
    local what=$1
    ensure_dirs
    if [ -f "$STATE_DIR/block-$what" ]; then rm -f "$STATE_DIR/block-$what"
    else : >"$STATE_DIR/block-$what"; fi
}

# block_tun_ifaces is every private-link device this server has or will have.
# Both sources are needed: a config names the device before it exists, and a
# device can outlive the config that made it if a delete went half way.
block_tun_ifaces() {
    local n d out= p
    # $out is split on purpose here and below: it is a word list, not a value.
    for n in $(cfg_list); do
        d=$(toml_get "$(cfg_file "$n")" tun name)
        [ -n "$d" ] || continue
        list_has "$d" $out || out="$out $d"
    done
    for p in /sys/class/net/pfy*; do
        [ -e "$p" ] || continue
        d=${p##*/}
        list_has "$d" $out || out="$out $d"
    done
    printf '%s' "${out# }"
}

block_icmp_tunnel() {
    local n
    for n in $(cfg_list); do
        [ "$(toml_get "$(cfg_file "$n")" transport type)" = icmp ] && return 0
    done
    return 1
}

# block_carrier_443 names a tunnel whose carrier is udp 443, which is the port
# the QUIC switch takes away. The wizard lets the operator pick any port and
# 443 is a common choice precisely because it looks like ordinary web traffic,
# so this is not a corner case.
block_carrier_443() {
    local n f
    while IFS= read -r n; do
        f=$(cfg_file "$n")
        [ "$(toml_get "$f" transport type)" = icmp ] && continue
        [ "$(toml_get "$f" transport port)" = 443 ] || continue
        printf '%s' "$n"
        return 0
    done < <(cfg_list)
    return 1
}

# block_carrier_accept puts this server's own carrier out of reach of the
# string match, and has to run before those rules go in.
#
# Nothing under internal/ encrypts the payload, so a customer's request for
# speedtest.net travels through the tunnel with those bytes in clear and
# -m string matches them inside the carrier's own packet. The rule aimed at a
# browser then rejects the packet carrying it, and the whole link stutters for
# a reason nothing on the screen explains.
#
# Both port directions, because the two ends are not symmetrical: IRAN dials
# out, so its carrier packets carry the port as the destination, and KHAREJ
# listens and answers from it as the source.
block_carrier_accept() {
    local n f t p rc=0 icmp_done=0
    while IFS= read -r n; do
        f=$(cfg_file "$n")
        t=$(toml_get "$f" transport type)
        if [ "$t" = icmp ]; then
            [ "$icmp_done" = 1 ] && continue
            icmp_done=1
            block_ipt -A PINGIFY_OUT -p icmp -j ACCEPT || rc=1
            continue
        fi
        p=$(toml_get "$f" transport port)
        case $p in '' | *[!0-9]*) continue ;; esac
        block_ipt -A PINGIFY_OUT -p udp --dport "$p" -j ACCEPT || rc=1
        block_ipt -A PINGIFY_OUT -p udp --sport "$p" -j ACCEPT || rc=1
    done < <(cfg_list)
    return "$rc"
}

# The chains, hooked once at position 1 and rebuilt from empty on every apply.
block_reset_chains() {
    local c
    for c in PINGIFY_IN PINGIFY_OUT; do
        block_ipt -N "$c" || block_ipt -F "$c" || return 1
    done
    block_ipt -C INPUT -j PINGIFY_IN || block_ipt -I INPUT 1 -j PINGIFY_IN
    block_ipt -C OUTPUT -j PINGIFY_OUT || block_ipt -I OUTPUT 1 -j PINGIFY_OUT
    return 0
}

block_drop_chains() {
    local c i rc=0
    # -D removes one match. An older script that inserted its hook twice leaves
    # the second behind, still sending every packet through a chain nothing
    # maintains, so take them off in a bounded loop rather than once.
    for i in 1 2 3 4 5; do block_ipt -D INPUT -j PINGIFY_IN || break; done
    for i in 1 2 3 4 5; do block_ipt -D OUTPUT -j PINGIFY_OUT || break; done
    for c in PINGIFY_IN PINGIFY_OUT; do
        block_ipt -F "$c"
        block_ipt -X "$c"
        # -X refuses while anything still jumps to the chain, and that refusal
        # went to /dev/null, so a hook the loops above could not unpick left a
        # live chain behind under a green "every blocking rule is gone". -S
        # fails on a chain that is not there, which is the answer wanted.
        block_ipt -S "$c" >/dev/null 2>&1 && rc=1
    done
    return "$rc"
}

hosts_block_off() {
    grep -qF "$HOSTS_MARK" /etc/hosts 2>/dev/null || return 0
    local tmp
    tmp=$(mktemp)
    # Written back through the same inode. /etc/hosts is a bind mount inside a
    # container and mv over it fails, or worse, succeeds locally and changes
    # nothing the container can see.
    awk -v a="$HOSTS_MARK" -v b="$HOSTS_END" '
        $0 == a { skip = 1; next }
        $0 == b { skip = 0; next }
        !skip
    ' /etc/hosts >"$tmp" && cat "$tmp" >/etc/hosts
    rm -f "$tmp"
}

hosts_block_on() {
    hosts_block_off
    {
        printf '%s\n' "$HOSTS_MARK"
        local h
        for h in $SPEEDTEST_HOSTS; do
            case $h in *[!a-zA-Z0-9.-]*) continue ;; esac
            printf '127.0.0.1 %s\n127.0.0.1 www.%s\n' "$h" "$h"
        done
        printf '%s\n' "$HOSTS_END"
    } >>/etc/hosts
}

# apply_blocking is the only thing that writes rules, and it writes all of them
# every time from the state files. Nothing anywhere adds a single rule.
apply_blocking() {
    # rc is the honest answer. This function used to end with an unconditional
    # ok and return 0, so a rule iptables refused - the lock, a missing module,
    # a kernel without the match - was reported as a rule that went in.
    local quiet=${1:-} ifc h any rc=0 carrier
    have iptables || {
        [ "$quiet" = quiet ] || warn "iptables is not installed, so nothing was applied"
        return 1
    }
    ensure_dirs
    block_reset_chains || {
        [ "$quiet" = quiet ] || bad "iptables would not give us our chains"
        return 1
    }

    if [ "$(block_state icmp)" = on ]; then
        # The private link goes first, and the order is the whole rule.
        # `ping -I pfy0 10.99.10.2` is how anybody checks a udp tunnel is
        # carrying, and it is the far end's INPUT chain that has to answer it.
        # Put the global drop above these and blocking pings from the internet
        # quietly takes away the only test the operator has.
        for ifc in $(block_tun_ifaces); do
            block_ipt -A PINGIFY_IN -i "$ifc" -p icmp --icmp-type echo-request -j ACCEPT || rc=1
        done

        # And where a tunnel on this host uses the icmp transport, the global
        # drop is not installed at all.
        #
        # The old manager's comment said our own transport "rides in echo
        # replies, which nothing here matches". True of the old core, false of
        # this one: internal/carrier/icmp.go sends echo requests in both
        # directions. They arrive on the public interface, from an address the
        # KHAREJ side cannot know in advance, and INPUT is traversed before the
        # kernel feeds a raw socket - so the drop would eat the carrier and the
        # tunnel would go deaf with every rule on the screen looking correct.
        #
        # Nothing is lost by leaving it out: the carrier has already set
        # icmp_echo_ignore_all, so this host answers no pings anyway, which is
        # exactly what the switch was for.
        if block_icmp_tunnel; then
            [ "$quiet" = quiet ] ||
                dim "an ICMP tunnel is configured, so the blanket drop is left out - the"
            [ "$quiet" = quiet ] ||
                dim "core has already stopped this host answering pings"
        else
            block_ipt -A PINGIFY_IN -p icmp --icmp-type echo-request -j DROP || rc=1
        fi
    fi

    if [ "$(block_state quic)" = on ]; then
        # A udp carrier on 443 is left alone, the same care the ICMP branch
        # takes. These two rules match on the destination port only, which is
        # the dialling side's carrier on the way out and the listening side's
        # on the way in, so with the tunnel on 443 they made it deaf with every
        # rule on the screen looking correct. Nothing on this host can tell one
        # udp 443 datagram from another, so the choice is to leave them out.
        if carrier=$(block_carrier_443); then
            [ "$quiet" = quiet ] || dim "$carrier carries on udp 443"
            [ "$quiet" = quiet ] ||
                dim "so the QUIC rules are left out - nothing here can tell"
            [ "$quiet" = quiet ] ||
                dim "that carrier from a browser on the same port"
        else
            # Rejected on the way out, not dropped: a browser that gets a port
            # unreachable falls back to TCP now, and one that gets silence waits
            # for a timeout first, which is felt as the page hanging.
            block_ipt -A PINGIFY_OUT -p udp --dport 443 -j REJECT --reject-with icmp-port-unreachable || rc=1
            block_ipt -A PINGIFY_IN -p udp --dport 443 -j DROP || rc=1
        fi
    fi

    if [ "$(block_state speedtest)" = on ]; then
        hosts_block_on
        block_carrier_accept || rc=1
        any=0
        for h in $SPEEDTEST_HOSTS; do
            case $h in *[!a-zA-Z0-9.-]*) continue ;; esac
            # The hostname travels in clear in the TLS ClientHello, so this
            # catches a client that brought its own resolver and never asked
            # this machine for an address.
            block_ipt -A PINGIFY_OUT -m string --string "$h" --algo bm -j REJECT && any=1
        done
        if [ "$any" = 0 ] && [ "$quiet" != quiet ]; then
            warn "this kernel has no string match, so only the hosts file is blocking"
            fix "modprobe xt_string, or accept that a client with its own DNS gets through"
        fi
    else
        hosts_block_off
    fi

    firewall_unit_write || rc=1
    if [ "$rc" != 0 ]; then
        [ "$quiet" = quiet ] || bad "some of those rules would not go in"
        [ "$quiet" = quiet ] || fix "iptables -S PINGIFY_OUT   shows what did"
        return 1
    fi
    [ "$quiet" = quiet ] || ok "blocking rules rebuilt from the state files"
    return 0
}

# iptables forgets everything at reboot, so one oneshot unit replays the state
# files. It calls back into this same script, which means there is one apply
# path and the boot path cannot drift from the interactive one.
firewall_unit_write() {
    local unit=$UNIT_DIR/pingify-firewall.service
    # The unit used to run "$PINGIFY_BIN --apply-firewall", and argv in the
    # main part has no such option: unknown flags print the usage and die, so
    # every boot the unit failed, every rule stayed gone, and the Blocking
    # screen still read "on". Source the script with PINGIFY_NO_MAIN instead
    # and call the function directly, which is what the forwarding part's own
    # boot unit does and what build.sh and the updater already use.
    cat >"$unit" <<UNIT || { bad "could not write the boot unit"; fix "$unit"; return 1; }
[Unit]
Description=Pingify blocking rules
After=network-online.target
Wants=network-online.target

[Service]
Type=oneshot
RemainAfterExit=yes
ExecStart=/bin/bash -c 'PINGIFY_NO_MAIN=1 . $PINGIFY_BIN && apply_blocking quiet'

[Install]
WantedBy=multi-user.target
UNIT
    systemctl daemon-reload >/dev/null 2>&1 || true
    systemctl enable pingify-firewall.service >/dev/null 2>&1 || true
}

remove_blocking() {
    local rc=0
    rm -f "$STATE_DIR"/block-icmp "$STATE_DIR"/block-quic "$STATE_DIR"/block-speedtest
    hosts_block_off
    have iptables && { block_drop_chains || rc=1; }
    systemctl disable --now pingify-firewall.service >/dev/null 2>&1 || true
    rm -f "$UNIT_DIR/pingify-firewall.service"
    systemctl daemon-reload >/dev/null 2>&1 || true
    # Uninstall calls this and prints its own success after it, so a chain that
    # survived has to come back as a non-zero rather than as the line below.
    if [ "$rc" != 0 ]; then
        bad "the PINGIFY chains are still in the kernel"
        fix "iptables -S PINGIFY_IN   shows what points at it"
        return 1
    fi
    ok "every blocking rule, state file and the boot unit are gone"
    dim "the tunnels themselves are untouched"
}

# The two long explanations live in their own functions. In the old script they
# were inline in the case arms and the dispatch was thirty lines of prose with
# the actual branches hidden in it.
why_block_icmp() {
    blank
    dim "Stops this server answering pings from the internet, which is what a"
    dim "scanner uses to find out it is there at all. Pings inside the private"
    dim "link keep working, because those rules are accepted first."
    if block_icmp_tunnel; then
        blank
        dim "You have an ICMP tunnel here. The core has already stopped the"
        dim "kernel answering echoes - that is how the carrier avoids doubling"
        dim "its own traffic - so this switch has little left to do, and the"
        dim "blanket drop is deliberately not installed while it is running."
    fi
}

why_block_quic() {
    blank
    dim "QUIC is HTTP over UDP 443. It carries its own loss recovery, and over"
    dim "a lossy carrier that recovery and the tunnel's back off from the same"
    dim "loss twice. A browser refused UDP 443 falls back to TCP immediately."
    dim "Nothing else uses the port, so the cost is a browser feature and not"
    dim "a site."
}

screen_firewall() {
    local key
    while :; do
        screen_top
        blank
        rule "Blocking"
        dim "state lives in $STATE_DIR. Every apply flushes our two chains and"
        dim "builds them again, so your own rules are never in the way of it."
        blank
        item2 "1" "Ping from outside" "$(host_badge "$(block_state icmp)")"
        item2 "2" "QUIC, udp 443" "$(host_badge "$(block_state quic)")"
        item2 "3" "Speedtest sites" "$(host_badge "$(block_state speedtest)")"
        blank
        item "4" "Show the rules that are in place"
        item "5" "Clear everything, including the boot unit"
        item "0" "Back"
        blank
        menu_key key || return 0
        case $key in
        # The explainer is printed after the flip and only when the answer is
        # now on, so it describes what is true rather than what was clicked.
        1) blank; block_toggle icmp
           [ "$(block_state icmp)" = on ] && why_block_icmp
           blank; apply_blocking ;;
        2) blank; block_toggle quic
           [ "$(block_state quic)" = on ] && why_block_quic
           blank; apply_blocking ;;
        3) blank; block_toggle speedtest; apply_blocking ;;
        4)
            blank
            if ! have iptables; then
                warn "iptables is not installed"
            else
                # Cut to the width like everything else on this screen. A
                # string rule is about 127 columns as iptables prints it, so
                # ten of them wrapped into each other at any width this UI
                # supports and the list stopped being readable at all.
                rule "PINGIFY_IN"
                iptables -S PINGIFY_IN 2>/dev/null | grep -v '^-N ' |
                    sed 's/^/    /' | cut -c "1-$((UI_W - 3))"
                rule "PINGIFY_OUT"
                iptables -S PINGIFY_OUT 2>/dev/null | grep -v '^-N ' |
                    sed 's/^/    /' | cut -c "1-$((UI_W - 3))"
            fi
            blank
            field "hosts file" "$(grep -qF "$HOSTS_MARK" /etc/hosts 2>/dev/null && printf 'our block is in it' || printf 'nothing of ours in it')"
            ;;
        5)
            blank
            confirm "remove every Pingify blocking rule?" n && { blank; remove_blocking; }
            ;;
        0 | '') return 0 ;;
        esac
    done
}
#
# The front door: getting the manager onto the machine, working out what the
# command line asked for, and the one screen everything else hangs off. It is
# last so that everything it dispatches to is already defined when the guard
# at the bottom calls main.
#
# Two rules shape it. A non-interactive flag must work with no terminal at all
# - a monitoring script calling --status has no stdin and no tty - so nothing
# on that path asks a question or draws a menu. And there is one renderer for
# a tunnel's line: home draws it with a key beside it, --status draws it
# without one, and they are the same function, because two renderers of the
# same five numbers drift apart and then disagree in front of the user.

# --------------------------------------------------------------------------
# putting the manager where the pingify command can find it
# --------------------------------------------------------------------------

# install_self copies this script over /usr/local/bin/pingify when the copy
# sitting there is not this one. It runs on every interactive launch, and it
# has to, because "update" for most people means re-running the install line
# from the README: that leaves a fresh script in the current directory and a
# fresh core in /usr/local/bin, with the *old* manager still on PATH beside
# it - the one combination the two of them are not built to work in.
#
# The new copy is renamed into place rather than written over the destination.
# bash reads a script as it runs, a few kilobytes at a time, so truncating the
# file it is still reading turns the rest of the run into whatever lands at
# that offset. A rename leaves the running copy's inode alone.
install_self() {
    local src=${BASH_SOURCE[0]} dir tmp stamp
    if [ ! -f "$src" ]; then
        # Started from a process substitution - bash <(curl ...) - so there is
        # no file on disk to copy from. Nothing is broken; say what is missing.
        warn "the pingify command was not installed - this script has no file on disk"
        fix "save it first:  curl -fsSLo pingify <url> && bash pingify"
        return 1
    fi

    if ! cmp -s "$src" "$PINGIFY_BIN"; then
        dir=${PINGIFY_BIN%/*}
        tmp=$(mktemp "$dir/.pingify.XXXXXX") || return 1
        if ! { cat "$src" >"$tmp" && chmod 0755 "$tmp" && mv -f "$tmp" "$PINGIFY_BIN"; }; then
            rm -f "$tmp"
            warn "could not write $PINGIFY_BIN"
            return 1
        fi
    fi

    # The unit is a template. It changes with the script and never with a
    # tunnel, so it is written here, once, and on a version change - which is
    # what stops it being rewritten four times whenever somebody adds a fifth
    # tunnel.
    #
    # The stamp is written only when the unit is really there. It used to be
    # written whether or not unit_write had worked, so a run where $UNIT_DIR
    # was unwritable left pingify@.service missing and never tried again - the
    # stamp said this version had already done it. The file is the test rather
    # than unit_write's status, because unit_write ends in a daemon-reload and
    # so returns 0 even when its heredoc failed.
    stamp=$STATE_DIR/script.version
    if [ "$(cat "$stamp" 2>/dev/null)" != "$PINGIFY_VERSION" ]; then
        if unit_write && [ -s "$UNIT_DIR/pingify@.service" ]; then
            printf '%s\n' "$PINGIFY_VERSION" >"$stamp"
        else
            warn "could not write $UNIT_DIR/pingify@.service"
            return 1
        fi
    fi
    return 0
}

# --------------------------------------------------------------------------
# home
# --------------------------------------------------------------------------

# --------------------------------------------------------------------------
# what this machine is, and what Pingify is doing on it
# --------------------------------------------------------------------------

# srv_info fills in the three lines at the top of the home screen: the address
# the outside world sees this server at, and where that address is.
#
# It is cached in a file and read back from there. The home screen is drawn
# again every time you come back to it, and a lookup over the network inside
# that loop is the difference between a manager that answers at once and one
# that stops for six seconds on every return. A datacentre does not move: the
# cache is a week old before anything is fetched again.
#
# None of it is required. A server with no route out shows the address on its
# own interface and says plainly that it does not know the rest, because
# "not known from here" in a panel is information and a blank line is a bug.
SRV_TTL_DAYS=7

srv_info() {
    [ -n "${SRV_IP:-}" ] && return 0
    local cache=$STATE_DIR/server.info j

    if [ -f "$cache" ] && [ -z "$(find "$cache" -mtime "+$SRV_TTL_DAYS" 2>/dev/null)" ]; then
        IFS='|' read -r SRV_IP SRV_LOC SRV_ORG <"$cache"
    fi

    # One request, three fields, six seconds at the outside. The address being
    # looked up is this server's own. json_field is no use here - it reads the
    # core's output, which is one field to a line, and this arrives as one.
    if [ -z "${SRV_IP:-}" ] && have curl; then
        j=$(curl -fsS --max-time 6 \
            'http://ip-api.com/json/?fields=query,country,isp' 2>/dev/null)
        SRV_IP=$(printf '%s' "$j" | sed -n 's/.*"query":"\([^"]*\)".*/\1/p')
        SRV_LOC=$(printf '%s' "$j" | sed -n 's/.*"country":"\([^"]*\)".*/\1/p')
        SRV_ORG=$(printf '%s' "$j" | sed -n 's/.*"isp":"\([^"]*\)".*/\1/p')
        [ -n "$SRV_IP" ] &&
            printf '%s|%s|%s\n' "$SRV_IP" "$SRV_LOC" "$SRV_ORG" >"$cache"
    fi

    [ -n "${SRV_IP:-}" ] || SRV_IP=$(wiz_public_ip)
    [ -n "${SRV_IP:-}" ] || SRV_IP=$G_DASH
    [ -n "${SRV_LOC:-}" ] || SRV_LOC="not known from here"
    [ -n "${SRV_ORG:-}" ] || SRV_ORG="not known from here"
    return 0
}

# home_panels is the two boxes under the name.
#
# Everything on them is one file read or one systemctl call, because they are
# drawn again on every return to this screen. The side of the border is here
# rather than on every tunnel row: one server is one side - `side` is the only
# line that differs between the two ends - so it is the same in all of this
# server's configs and belongs with the server, not with a tunnel.
home_panels() {
    local n st side= up=0 off=0 total=0 core=$G_DASH core_txt tun_txt dog secs rest

    while IFS= read -r n; do
        total=$((total + 1))
        st=$(svc_state "$n")
        [ "$st" = active ] && up=$((up + 1))
        [ "$st" = disabled ] && off=$((off + 1))
        [ -n "$side" ] || side=$(toml_get "$(cfg_file "$n")" tunnel side)
    done < <(cfg_list)

    case $side in
    iran) side="IRAN $G_DASH users connect here" ;;
    kharej) side="KHAREJ $G_DASH your panel is here" ;;
    *) side="not decided yet" ;;
    esac

    srv_info
    blank
    panel_open "SERVER"
    panel_field "IP" "$(addr_text "$SRV_IP")"
    panel_field "Location" "$SRV_LOC"
    panel_field "Datacenter" "$SRV_ORG"
    panel_field "Side" "$side"
    panel_close

    # A core that is installed but will not run - built for another
    # architecture, or truncated - returns 1 with nothing on stdout, and the
    # assignment used to keep that empty string, so the line read "core" with
    # a hole where the version belongs. Put the dash back on either failure.
    if [ -x "$CORE_BIN" ]; then
        core=$(core_version) || core=$G_DASH
        [ -n "$core" ] || core=$G_DASH
    fi
    if [ "$core" = "$G_DASH" ]; then
        core_txt="${C_BAD}not installed${C_OFF}"
    elif [ "$core" = "$PINGIFY_VERSION" ]; then
        core_txt=$core
    else
        # Not a detail. A core and a script from two versions is the one
        # combination neither of them is built to work in.
        core_txt="$core ${C_WARN}$G_DASH the script is $PINGIFY_VERSION${C_OFF}"
    fi

    if [ "$total" = 0 ]; then
        tun_txt="$(state_dot none) none configured"
        dog="$(state_dot none) nothing to watch yet"
    else
        if [ "$up" = "$total" ]; then
            tun_txt="$(state_dot running) $up of $total up"
        elif [ "$up" = 0 ]; then
            tun_txt="$(state_dot stopped) none of $total up"
        else
            tun_txt="$(state_dot idle) $up of $total up"
        fi
        # There is no separate watchdog process and there should not be one.
        # systemd is the watchdog: the unit brings a tunnel back two seconds
        # after it dies. What can be wrong is a tunnel that was never enabled,
        # so that is what this line reports.
        if [ "$off" = 0 ]; then
            dog="$(state_dot running) on, a dead tunnel is back in 2s"
        else
            dog="$(state_dot idle) $off not started at boot"
        fi
    fi

    read -r secs rest </proc/uptime 2>/dev/null || secs=
    panel_open "STATUS"
    panel_field "Core ver" "$core_txt"
    panel_field "Script ver" "$PINGIFY_VERSION"
    panel_field "Tunnels" "$tun_txt"
    panel_field "Watchdog" "$dog"
    panel_field "Uptime" "$(human_secs "${secs%%.*}")"
    panel_close
}

# home_row is one tunnel, and it is also the menu item for that tunnel. The
# old manager printed a status table and then a second numbered list of the
# same names under it, so every name was on the screen twice and the numbers
# on the second list matched nothing on the first.
#
# The round trip is measured only for a tunnel that is running: probing a
# stopped one costs three seconds of ping timeout for an answer already known.
home_row() {
    local name=$1 key=$2 st=stopped dot=stopped rtt=$G_DASH up=$G_DASH rate= transport=
    st=$(svc_state "$name")
    transport=$(toml_get "$(cfg_file "$name")" transport type)
    [ -n "$transport" ] || transport=udp
    rate=$st

    case $st in
    active)
        dot=idle
        if tun_stats "$name"; then
            # How long this tunnel has been carrying, which is not how long
            # the machine has been up and not how long the unit has existed:
            # it is the core's own clock, so a tunnel that has been quietly
            # restarting every few minutes says so here.
            up=$(human_secs "$ST_UPTIME")
            # Green means somebody is at the other end, which is not what the
            # core's up says on the side that dials: there, up is true from
            # the first second because the address was in the config. Amber
            # for running-and-alone, which is what the dot has always meant.
            [ "$ST_UP" = true ] && [ "${ST_INB:-0}" != 0 ] && dot=running
            [ -n "$ST_TRANSPORT" ] && transport=$ST_TRANSPORT
            rate="$(round1 "$ST_IN")/$(round1 "$ST_OUT")"
        else
            rate="no answer"
        fi
        rtt=$(tun_rtt "$name")
        # Grey, never red. An ICMP tunnel cannot be pinged across - both
        # kernels have stopped answering echo, deliberately - so "no number"
        # here means "not measurable", not "slow".
        case $rtt in
        '' | *[!0-9.]*) rtt=$G_DASH ;;
        *) rtt="$(rtt_colour "$rtt")$rtt ms$C_OFF" ;;
        esac
        ;;
    disabled) dot=unknown ;;
    esac

    # The key is right aligned in two columns so that the tenth tunnel's dot
    # stands in the same place as the first one's, and so that the blank key
    # --status passes costs the line nothing.
    row "$(printf '%2s' "$key") $(state_dot "$dot")" \
        "$name" "${transport^^}" "$up" "$rtt" "$rate"
}

# The names of the columns, once, above them.
#
# Five numbers with no headings is a row somebody has to be told how to read.
# It is dim because it is not the data, and it goes through row() like every
# line under it, so a column cannot be renamed into the wrong place.
home_head() {
    printf '%s%s%s\n' "$C_KEY" \
        "$(row "" "TUNNEL" "VIA" "UP" "PING" "MBIT/S")" "$C_OFF"
}

# The widths the tunnel list is drawn at, in one place, because home and
# --status both draw it. The old script kept four magic numbers in the header
# and four more in the row and they had already drifted apart.
#
# Everything but the name is a known width - "412.3/38.1 Mbit/s" is the widest
# thing the last column ever holds - so the name takes the slack, up to the 24
# characters v_name allows and no further. A wide window should not stretch one
# column across half the screen.
home_cols() {
    local nw=$((UI_W - 50))
    # 24, not 26. v_name refuses a twenty-fifth character, so the two columns
    # of slack above it could never hold anything and only pushed the numbers
    # further from the name they belong to.
    [ "$nw" -gt 24 ] && nw=24
    [ "$nw" -lt 8 ] && nw=8
    # key and dot, name, transport, uptime, round trip, and the two rates.
    # The rates lose their unit to make room for the uptime; the heading over
    # the column carries it instead, which is where a unit belongs.
    UI_COLS=(4 "$nw" 6 7 8 12)
}

# The home screen: the name, the two panels, whatever is running, and a
# numbered list of everything that can be done from here.
#
# The numbers are fixed, and that is the point of them. They were letters, and
# the tunnels themselves were keys on this screen, so the key for Uninstall
# moved down the alphabet every time somebody added a tunnel. Nothing here
# moves now: 7 is Remove on a server with no tunnels and on a server with ten.
screen_home() {
    local n names=()
    while IFS= read -r n; do names+=("$n"); done < <(cfg_list)

    screen_top
    home_panels

    if [ "${#names[@]}" -gt 0 ]; then
        blank
        group "RUNNING NOW"
        home_cols
        home_head
        for n in "${names[@]}"; do home_row "$n" " "; done
    fi

    blank
    group "TUNNELS"
    item 1 "New tunnel" "set this server up, or finish the pair"
    item 2 "Manage tunnels" "status, ports, profile, logs, remove"
    item 3 "Health check" "every tunnel, and what to do about it"
    blank
    group "NETWORK"
    item 4 "Host tuning" "kernel profile, BBR, descriptor limits"
    item 5 "Blocking" "ping from outside, QUIC on udp 443, speedtest"
    blank
    group "MAINTENANCE"
    item 6 "Update Pingify" "script and core together, to the same version"
    item 7 "Remove" "uninstall part of it, or all of it"
    blank
    item 0 "Exit"
    blank
}

# screen_tunnels is the list, and the way into one of them.
#
# One tunnel is the common case and it does not deserve a screen of its own:
# with one there is nothing to choose, so this goes straight in. The list is
# read again on the way back out of a tunnel, because the last thing that
# screen offers is deleting it, and a tunnel that has just been deleted must
# not still be on the list you are returned to.
screen_tunnels() {
    local names=() n i k
    while IFS= read -r n; do names+=("$n"); done < <(cfg_list)

    if [ "${#names[@]}" -eq 0 ]; then
        screen_top
        blank
        rule "Manage tunnels"
        blank
        dim "no tunnels on this server yet - pick New tunnel to make one"
        pause
        return 0
    fi
    if [ "${#names[@]}" -eq 1 ]; then
        screen_tunnel "${names[0]}"
        return 0
    fi

    while :; do
        screen_top
        blank
        rule "Manage tunnels"
        blank
        home_cols
        home_head
        i=0
        while [ "$i" -lt "${#names[@]}" ]; do
            home_row "${names[i]}" "$((i + 1))"
            i=$((i + 1))
        done
        blank
        item 0 "Back"
        blank

        menu_key k || return 0
        case $k in
        0 | '') return 0 ;;
        *[!0-9]*) blank; warn "there is nothing on $k" ;;
        *)
            if [ "$k" -ge 1 ] && [ "$k" -le "${#names[@]}" ]; then
                screen_tunnel "${names[k - 1]}"
                names=()
                while IFS= read -r n; do names+=("$n"); done < <(cfg_list)
                [ "${#names[@]}" -eq 0 ] && return 0
            else
                blank
                warn "there is nothing on $k"
            fi
            ;;
        esac
    done
}

# screen_health runs the check over every tunnel rather than over one.
#
# The worst answer is the one that is kept. Returning whatever the last check
# said would tell a server whose second tunnel of three is broken that it was
# clean, because the third one was.
screen_health() {
    local names=() n rc=0 one
    while IFS= read -r n; do names+=("$n"); done < <(cfg_list)
    screen_top

    if [ "${#names[@]}" -eq 0 ]; then
        blank
        warn "there are no tunnels to check yet"
        pause
        return 0
    fi
    for n in "${names[@]}"; do
        health_check "$n" || { one=$?; [ "$one" -gt "$rc" ] && rc=$one; }
    done
    pause
    return "$rc"
}

main_menu() {
    local c
    while :; do
        screen_home
        menu_key c || return 0
        case $c in
        1) screen_new ;;
        2) screen_tunnels ;;
        3) screen_health ;;
        4) screen_host ;;
        5) screen_firewall ;;
        6) update_pingify ;;
        7) uninstall_all && exit 0 ;;
        # q is not on the screen and works anyway: it is what every question
        # in the wizard takes for "let me out of this", and somebody who
        # learned it there types it here.
        0 | q | Q) blank; return 0 ;;
        '') ;;
        *) blank; warn "there is nothing on $c" ;;
        esac
    done
}

# --------------------------------------------------------------------------
# what the command line asked for
# --------------------------------------------------------------------------

usage() {
    cat <<USAGE

  Pingify $PINGIFY_VERSION - a tunnel between a server in Iran and one abroad

    pingify                    the menu
    pingify --new              straight to building a tunnel
    pingify --status [NAME]    one line per tunnel, or one named tunnel
    pingify --check NAME       health check; exits 0 clean, 1 warnings, 2 problems
    pingify --json             with --status or --check, machine readable
    pingify --version          the version of this script, and of the core
    pingify --update           fetch a newer script and core
    pingify --uninstall        take Pingify off this server
    pingify --help             this

  Configs   $CFG_DIR/<name>.toml - identical on both servers but for one line
  Core      $CORE_BIN

USAGE
}

# --status is what a monitoring script calls. It draws the same line home
# draws, with a blank where the menu key would be, and it exits non-zero if
# any tunnel it was asked about is not running.
cmd_status() {
    local n names=() rc=0
    if [ -n "$ARG_NAME" ]; then
        [ -f "$(cfg_file "$ARG_NAME")" ] || die "there is no tunnel called $ARG_NAME"
        names=("$ARG_NAME")
    else
        while IFS= read -r n; do names+=("$n"); done < <(cfg_list)
    fi
    # To stderr, because this is the one line on this path that is prose. On
    # stdout it went into the --json stream, where a consumer parsing objects
    # got "! no tunnels are configured" instead.
    [ "${#names[@]}" -gt 0 ] || { warn "no tunnels are configured" >&2; return 1; }

    if [ -n "$ARG_JSON" ]; then
        # The same answer as the screen below gives. This loop used to return
        # 0 whatever it found, so a monitoring script that asked for JSON -
        # the only kind that reads the exit status without reading the output
        # - was told every tunnel was fine while they were all stopped.
        for n in "${names[@]}"; do
            status_json "$n"
            [ "$(svc_state "$n")" = active ] || rc=1
        done
        return "$rc"
    fi

    home_cols
    home_head
    for n in "${names[@]}"; do
        home_row "$n" " "
        [ "$(svc_state "$n")" = active ] || rc=1
    done
    return "$rc"
}

# One object per tunnel, one per line, so `--status --json | while read` is a
# whole integration. The field names are the core's own; inventing a second
# vocabulary for the same numbers is how the two come to mean different things.
status_json() {
    local n=$1 st
    st=$(svc_state "$n")
    # A tunnel that does not answer is not up, and saying so is the report,
    # not a failure to make one.
    tun_stats "$n" || ST_UP=false
    printf '{"name":"%s","service":"%s","up":%s,"transport":"%s","profile":"%s"' \
        "$n" "$st" "${ST_UP:-false}" "$ST_TRANSPORT" "$ST_PROFILE"
    printf ',"side":"%s","in_mbit":%s,"out_mbit":%s,"lost":%s,"reordered":%s,"uptime_sec":%s}\n' \
        "$ST_SIDE" "${ST_IN:-0}" "${ST_OUT:-0}" "${ST_LOST:-0}" "${ST_LATE:-0}" "${ST_UPTIME:-0}"
}

argv() {
    ARG_MODE=menu ARG_NAME= ARG_JSON=
    while [ "$#" -gt 0 ]; do
        case $1 in
        --status)
            ARG_MODE=status
            # The name is optional, so only take the next word if it is one.
            case ${2:-} in '' | -*) ;; *) ARG_NAME=$2; shift ;; esac
            ;;
        --check)
            # A flag here is a missing name, not a name. `--check --json` used
            # to become a health check on a tunnel called "--json".
            ARG_MODE=check
            case ${2:-} in '' | -*) die "--check needs the name of a tunnel" ;; esac
            ARG_NAME=$2
            shift
            ;;
        --json) ARG_JSON=1 ;;
        --new) ARG_MODE=new ;;
        # The health check tells both operators to run `pingify --update` when
        # the two ends disagree about a version. Until this case existed that
        # advice fell through to the catch-all below and died with "--update is
        # not an option this script has", which is a poor thing to read when
        # the program itself sent you there.
        --update) ARG_MODE=update ;;
        # Not for people. update_pingify installs the new script and then execs
        # it with this, because the script that did the fetching no longer
        # knows what core the new one wants.
        --rebuild-core) ARG_MODE=rebuild ;;
        --uninstall) ARG_MODE=uninstall ;;
        --version | -v) ARG_MODE=version ;;
        --help | -h) ARG_MODE=help ;;
        *)
            usage >&2
            die "$1 is not an option this script has"
            ;;
        esac
        shift
    done
}

# --------------------------------------------------------------------------
# taking it all off again
# --------------------------------------------------------------------------

# uninstall_all prints the whole list before it touches any of it.
#
# The firewall goes first, and the order is not cosmetic: a DNAT rule pointing
# at a tun address that no longer exists does not error. It quietly swallows
# every connection to that port, and whatever is installed on that port next
# looks broken for a reason nothing on the machine explains.
# update_pingify fetches a newer script and, if the version moved, a core to
# match it.
#
# Two places are tried and the order is deliberate. A release asset is what a
# version number points at, but a push to main updates the raw URL instantly
# while the release carrying the matching core lands minutes later - so
# somebody updating in that window from the release alone gets a script that
# does not match the core beside it. Raw main is the fallback, not the first
# choice, because it is whatever was pushed rather than whatever was released.
#
# Nothing is installed until it parses. A half-downloaded shell script is a
# syntactically valid prefix of a working one, which is the worst possible
# failure: it runs, and it stops in the middle.
PINGIFY_REPO=${PINGIFY_REPO:-GreatTeejay/Pingify}

update_pingify() {
    local tmp rc=1 url
    screen_top
    blank
    rule "Update"
    blank

    have curl || have wget || {
        bad "neither curl nor wget is here, so there is nothing to fetch with"
        fix "apt install curl"
        pause
        return 1
    }

    tmp=$(mktemp) || return 1
    for url in \
        "https://github.com/$PINGIFY_REPO/releases/latest/download/Pingify.sh" \
        "https://raw.githubusercontent.com/$PINGIFY_REPO/main/Pingify.sh"; do
        dim "trying $url"
        if have curl; then
            curl -fsSL --connect-timeout 20 --retry 2 -o "$tmp" "$url" 2>/dev/null && rc=0
        else
            wget -qO "$tmp" "$url" 2>/dev/null && rc=0
        fi
        [ "$rc" = 0 ] && break
    done

    if [ "$rc" != 0 ]; then
        rm -f "$tmp"
        bad "nothing could be fetched from either place"
        fix "check this server can reach github, or copy Pingify.sh over yourself"
        pause
        return 1
    fi

    # It must be a shell script, it must parse, and it must be ours. A captive
    # portal answering every request with an HTML login page passes "the
    # download worked" and fails all three of these.
    if ! head -1 "$tmp" | grep -q '^#!.*bash'; then
        rm -f "$tmp"
        bad "what came back is not a shell script - something on the way answered instead"
        pause
        return 1
    fi
    if ! bash -n "$tmp" 2>/dev/null; then
        rm -f "$tmp"
        bad "what came back does not parse, so it arrived incomplete"
        fix "try again - a truncated script is worse than an old one"
        pause
        return 1
    fi

    local newver
    newver=$(PINGIFY_NO_MAIN=1 bash -c '. "$1"; printf "%s" "$PINGIFY_VERSION"' _ "$tmp" 2>/dev/null)
    if [ -z "$newver" ]; then
        rm -f "$tmp"
        bad "that script would not tell us its version, so it is not one of ours"
        pause
        return 1
    fi
    if [ "$newver" = "$PINGIFY_VERSION" ]; then
        rm -f "$tmp"
        ok "already on $PINGIFY_VERSION - nothing to do"
        pause
        return 0
    fi

    blank
    field "installed" "$PINGIFY_VERSION"
    field "available" "$newver"
    blank
    dim "the core is rebuilt to match, and every running tunnel is restarted"
    blank

    # Which way it is going. Anything that is not the version installed used to
    # be offered as an update, so a release that had been rolled back - or a
    # server running a build made by hand - was told to go backwards, with
    # enter as the answer that did it. Backwards is allowed, and it is not the
    # default and does not call itself an update.
    if ver_ge "$newver" "$PINGIFY_VERSION"; then
        confirm "update to $newver?" || { rm -f "$tmp"; return 1; }
    else
        warn "$newver is older than the $PINGIFY_VERSION on this server"
        fix "the core is rebuilt to match, so both ends go back together"
        confirm "go back to $newver?" n || { rm -f "$tmp"; return 1; }
    fi

    install -m 0755 "$tmp" "$PINGIFY_BIN" || {
        rm -f "$tmp"
        bad "could not write $PINGIFY_BIN"
        pause
        return 1
    }
    rm -f "$tmp"
    ok "the manager is now $newver"

    # The core has to move with it: a script and a core from different versions
    # is the one combination neither is built to work in. Hand over to the new
    # script rather than doing it here, because this one no longer knows what
    # the new core is supposed to be.
    blank
    dim "handing over to the new script to build its core"
    blank
    exec "$PINGIFY_BIN" --rebuild-core
}

uninstall_all() {
    local names=() n keep=yes unit rc=0 units=0
    while IFS= read -r n; do names+=("$n"); done < <(cfg_list)

    screen_top
    blank
    rule "Uninstall"
    field "manager" "$PINGIFY_BIN"
    field "core" "$CORE_BIN"
    field "units" "$UNIT_DIR/pingify@.service and every pingify-* unit"
    field "firewall" "the PINGIFY_* chains, flushed and removed"
    field "state" "$STATE_DIR"
    [ "${#names[@]}" -gt 0 ] && field "tunnels" "${names[*]}"
    field "tunnels in" "$CFG_DIR - kept, unless you say so below"
    blank
    # 2, not 1. Saying no is a decision rather than a failure, and main turns
    # this into an exit 0 so that `pingify --uninstall` does not report an
    # error for a deliberate no. It cannot simply be 0 either: the Remove key
    # exits the program when this function succeeds, and a decline has to leave
    # the operator on the screen they were looking at.
    confirm "remove all of that?" n || { dim "nothing was removed"; return 2; }
    confirm "delete the configs in $CFG_DIR as well?" n && keep=no
    blank

    for n in "${names[@]}"; do
        nat_drop "$n"
        svc_do stop "$n"
        svc_do disable "$n"
    done
    # Both of these ran with their status thrown away, under ok lines that
    # printed regardless. An uninstall that could not reach iptables reported a
    # clean removal with the PINGIFY_* chains still in the kernel, which is the
    # worst way to leave them: whatever is installed on one of those ports next
    # looks broken for a reason nothing on the machine explains.
    # They are two separate cleanups and both run whatever the other did: a
    # failed NAT teardown is no reason to leave the blocking rules behind too.
    nat_teardown || rc=1
    remove_blocking || rc=1
    if [ "$rc" != 0 ]; then
        bad "the firewall chains are still installed"
        fix "run this again once iptables works"
    fi

    for unit in "$UNIT_DIR"/pingify@.service "$UNIT_DIR"/pingify-*.service \
        "$UNIT_DIR"/pingify-*.timer; do
        [ -e "$unit" ] || continue
        systemctl disable --now "${unit##*/}" >/dev/null 2>&1
        rm -f "$unit"
        # rm -f says nothing about a file it could not remove, so the file
        # itself is the test.
        [ -e "$unit" ] && { units=1; rc=1; }
    done
    systemctl daemon-reload >/dev/null 2>&1
    if [ "$units" = 0 ]; then
        ok "services stopped and removed"
    else
        bad "some units are still in $UNIT_DIR"
    fi

    # The core and its sources go whatever the answer below was: they are the
    # program, not the settings, and keeping them without a manager to run
    # them leaves a binary nothing on the machine explains.
    rm -rf "$CORE_DIR" "$STATE_DIR"
    if [ "$keep" = no ]; then
        rm -rf "$CFG_DIR"
        ok "tunnels deleted"
    else
        ok "tunnels left in $CFG_DIR"
    fi
    # Only if it is empty, which it is when the tunnels went too.
    rmdir "$BASE_DIR" 2>/dev/null
    rm -f "$PINGIFY_BIN"
    # The closing line reports what happened rather than what was intended.
    if [ "$rc" = 0 ]; then
        ok "Pingify is removed"
    else
        bad "Pingify is off, but the lines above say what is left"
    fi

    # The ICMP carrier sets net.ipv4.icmp_echo_ignore_all=1 and nothing puts
    # it back, this included: the sysctl is the core's, and a tunnel still
    # running elsewhere on this box would start answering its own echoes and
    # double its own traffic. So the command is printed, not run.
    if [ "$(cat /proc/sys/net/ipv4/icmp_echo_ignore_all 2>/dev/null)" = 1 ]; then
        blank
        warn "this server is still not answering pings; an ICMP tunnel turned that on"
        fix "sysctl -w net.ipv4.icmp_echo_ignore_all=0"
    fi
    blank
    return "$rc"
}

# --------------------------------------------------------------------------

main() {
    local rc
    argv "$@"

    # Neither of these reads a config or writes anything, so neither needs to
    # be root, and --version is the first thing anybody runs when a pair does
    # not come up.
    case $ARG_MODE in
    help) usage; exit 0 ;;
    version)
        say "Pingify $PINGIFY_VERSION"
        [ -x "$CORE_BIN" ] && say "core $(core_version)"
        exit 0
        ;;
    esac

    require_root
    ensure_dirs

    # The exit status is the answer on these three, so it is passed straight
    # out rather than being replaced by whatever the last printf returned.
    case $ARG_MODE in
    status) cmd_status; exit $? ;;
    # The word matters. chk_finish tests for --json, and the bare "json" that
    # was passed here never matched it, so `--check NAME --json` rendered the
    # escape coded human screen into whatever was parsing it and exited as
    # though it had answered the question that was asked.
    check) health_check "$ARG_NAME" "${ARG_JSON:+--json}"; exit $? ;;
    uninstall)
        uninstall_all
        rc=$?
        # 2 is "you said no", which is not an error to report to a shell.
        [ "$rc" = 2 ] && rc=0
        exit "$rc"
        ;;
    esac

    # Update comes before ensure_core on purpose. Building the core this
    # version wants, moments before the next version asks for a different one,
    # is a Go build on a slow server that nobody gets any use out of - and
    # update_pingify installs the manager itself, so install_self has nothing
    # to add either.
    case $ARG_MODE in
    update) update_pingify; exit $? ;;
    esac

    # Only the interactive paths reinstall the manager. A cron line calling
    # --status every minute has no business rewriting /usr/local/bin, and if
    # it did it would rewrite it from whatever stale copy that cron line
    # happens to point at.
    # Before install_self, not after. install_self writes its version stamp
    # into the state directory, so running it first put a file in the new
    # place that the move then refused to overwrite - and left the old
    # directory behind with one file in it, for ever.
    migrate_layout
    install_self

    # A missing core warns rather than exits: Uninstall and the host screens
    # still work without one, and a server that cannot reach GitHub and has no
    # Go toolchain is exactly the server whose operator needs to get at them.
    ensure_core || warn "there is no working core installed; Update can fetch or build one"

    case $ARG_MODE in
    new) screen_new ;;
    rebuild)
        require_root
        ensure_dirs
        unit_write
        if ensure_core; then
            local n
            while IFS= read -r n; do
                systemctl is-enabled --quiet "pingify@$n" 2>/dev/null &&
                    svc_do restart "$n"
            done < <(cfg_list)
            ok "everything is on $PINGIFY_VERSION"
        else
            bad "the manager was updated but its core could not be built"
            fix "run pingify and choose 6, Update Pingify, once the reason is fixed"
            exit 1
        fi
        ;;
    *) main_menu ;;
    esac
}

# build.sh and the tests source this file to get at its functions; that must
# not launch the menu.
[ -n "${PINGIFY_NO_MAIN:-}" ] || main "$@"
